import json
import os
from pathlib import Path
from typing import Any

BRIEFS_PATH = os.environ.get("CONTENT_BRIEFS_PATH", "content_briefs.json")
DEFAULT_STATUS = "pending"


def _clean_text(value: Any, default: str = "") -> str:
    if value is None:
        return default
    text = str(value).strip()
    return text if text else default


def _clean_keywords(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        raw_items = value.split(",")
    elif isinstance(value, (list, tuple, set)):
        raw_items = value
    else:
        return []
    keywords: list[str] = []
    seen: set[str] = set()
    for item in raw_items:
        keyword = _clean_text(item)
        if not keyword:
            continue
        marker = keyword.casefold()
        if marker not in seen:
            seen.add(marker)
            keywords.append(keyword)
    return keywords


def load_content_briefs(file_path: str) -> list[dict[str, Any]]:
    path = Path(file_path)
    if not path.is_file():
        raise FileNotFoundError(f"Content brief file not found: {path}")
    raw_text = path.read_text(encoding="utf-8").strip()
    if not raw_text:
        raise ValueError(f"Content brief file is empty: {path}")
    try:
        payload = json.loads(raw_text)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in content brief file: {path}") from exc
    if not isinstance(payload, list):
        raise ValueError("Content brief payload must be a JSON array")
    if len(payload) == 0:
        raise ValueError("Content brief payload must contain at least one brief")

    normalized_briefs: list[dict[str, Any]] = []
    for index, item in enumerate(payload):
        if not isinstance(item, dict):
            raise ValueError(f"Brief at index {index} must be a JSON object")
        status = _clean_text(item.get("status"), DEFAULT_STATUS).lower()
        if status != DEFAULT_STATUS:
            continue
        brief = {
            "title": _clean_text(item.get("title"), "Untitled"),
            "content": _clean_text(item.get("content")),
            "audience": _clean_text(item.get("audience")),
            "tone": _clean_text(item.get("tone")),
            "keywords": _clean_keywords(item.get("keywords")),
            "status": status,
        }
        normalized_briefs.append(brief)
    return normalized_briefs


content_briefs = load_content_briefs(BRIEFS_PATH)

def select_inference_provider(complexity_score):
    routing_table = {
        'groq': (0, 5),
        'together': (6, 10),
        'openai': (11, float('inf'))
    }
    for provider, (min_score, max_score) in routing_table.items():
        if min_score <= complexity_score <= max_score:
            return provider
    return 'unknown'

# Example usage
provider = select_inference_provider(complexity_score)

import os
import urllib.request
import json

def call_inference_provider(provider, prompt):
    url = ''
    if provider == 'groq':
        url = 'https://api.groq.com/openai/v1/chat/completions'
    elif provider == 'together':
        url = 'https://api.together.xyz/v1/chat/completions'
    elif provider == 'openai':
        url = 'https://api.openai.com/v1/chat/completions'
    else:
        return None  # Unknown provider

    headers = {
        'Authorization': f'Bearer {os.environ.get("API_KEY")}',
        'Content-Type': 'application/json'
    }
    data = json.dumps({'prompt': prompt}).encode('utf-8')
    request = urllib.request.Request(url, data=data, headers=headers)
    with urllib.request.urlopen(request) as response:
        return json.loads(response.read().decode('utf-8'))

