import json
import urllib.request
import os

def run_openai_baseline(prompts):
    responses = []
    url = 'https://api.openai.com/v1/chat/completions'
    headers = {
        'Authorization': f'Bearer {os.environ.get("OPENAI_API_KEY")}',
        'Content-Type': 'application/json'
    }
    for prompt in prompts:
        payload = json.dumps({'model': 'gpt-4o-mini', 'messages': [{'role': 'user', 'content': prompt}]})
        request = urllib.request.Request(url, data=payload.encode('utf-8'), headers=headers)
        try:
            with urllib.request.urlopen(request) as response:
                result = json.loads(response.read().decode('utf-8'))
                responses.append(result.get('choices', [{}])[0].get('message', {}).get('content', ''))
        except urllib.error.HTTPError as e:
            responses.append(f"HTTP error: {e.code}")
        except urllib.error.URLError as e:
            responses.append(f"URL error: {e.reason}")
    return responses

openai_responses = run_openai_baseline(prompts)

