import json
import os
import urllib.request

OPENAI_API_KEY = os.environ.get('OPENAI_API_KEY', '')
OPENAI_CHAT_URL = 'https://api.openai.com/v1/chat/completions'
BATCH_JSONL_PATH = 'batch_requests.jsonl'

queued_prompts = [
    {'custom_id': 'prompt-001', 'prompt': 'Summarize the benefits of batch processing for LLM workloads.'},
    {'custom_id': 'prompt-002', 'prompt': 'List three risks of processing large prompt sets without idempotency keys.'},
]

def probe_gpt4_api():
    if not OPENAI_API_KEY:
        return {'status': 'skipped', 'reason': 'OPENAI_API_KEY is not set'}
    payload = {
        'model': 'gpt-4o-mini',
        'messages': [
            {'role': 'system', 'content': 'You are a concise API validation assistant.'},
            {'role': 'user', 'content': 'Reply with the single word ready.'},
        ],
        'temperature': 0,
    }
    data = json.dumps(payload).encode('utf-8')
    headers = {'Authorization': f'Bearer {OPENAI_API_KEY}', 'Content-Type': 'application/json'}
    request = urllib.request.Request(OPENAI_CHAT_URL, data=data, headers=headers, method='POST')
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            body = response.read().decode('utf-8')
            parsed = json.loads(body)
            return {'status': 'ok', 'id': parsed.get('id', ''), 'model': parsed.get('model', '')}
    except Exception as exc:
        return {'status': 'error', 'error': str(exc)}

def build_batch_jsonl(prompts):
    lines = []
    for item in prompts:
        custom_id = str(item.get('custom_id', 'prompt-unknown'))
        prompt_text = str(item.get('prompt', ''))
        request_object = {
            'custom_id': custom_id,
            'method': 'POST',
            'url': '/v1/chat/completions',
            'body': {
                'model': 'gpt-4o-mini',
                'messages': [
                    {'role': 'system', 'content': 'Answer the user request precisely.'},
                    {'role': 'user', 'content': prompt_text},
                ],
                'temperature': 0,
            },
        }
        lines.append(json.dumps(request_object, ensure_ascii=False))
    with open(BATCH_JSONL_PATH, 'w', encoding='utf-8') as handle:
        handle.write('\n'.join(lines) + '\n')
    return BATCH_JSONL_PATH

gpt4_probe = probe_gpt4_api()
batch_jsonl_path = build_batch_jsonl(queued_prompts)

import json
import os
import urllib.request
import uuid

OPENAI_BATCH_URL = 'https://api.openai.com/v1/batches'
OPENAI_FILES_URL = 'https://api.openai.com/v1/files'
COMPLETION_WINDOW = '24h'

def upload_batch_file(path):
    if not OPENAI_API_KEY:
        return {'id': 'file-mock', 'status': 'skipped'}
    boundary = '----BatchBoundary' + uuid.uuid4().hex
    with open(path, 'rb') as handle:
        file_bytes = handle.read()
    parts = []
    parts.append(f'--{boundary}\r\n'.encode('utf-8'))
    parts.append(b'Content-Disposition: form-data; name="purpose"\r\n\r\n')
    parts.append(b'batch\r\n')
    parts.append(f'--{boundary}\r\n'.encode('utf-8'))
    parts.append(b'Content-Disposition: form-data; name="file"; filename="batch_requests.jsonl"\r\n')
    parts.append(b'Content-Type: application/jsonl\r\n\r\n')
    parts.append(file_bytes)
    parts.append(f'\r\n--{boundary}--\r\n'.encode('utf-8'))
    body = b''.join(parts)
    headers = {
        'Authorization': f'Bearer {OPENAI_API_KEY}',
        'Content-Type': f'multipart/form-data; boundary={boundary}',
    }
    request = urllib.request.Request(OPENAI_FILES_URL, data=body, headers=headers, method='POST')
    try:
        with urllib.request.urlopen(request, timeout=60) as response:
            return json.loads(response.read().decode('utf-8'))
    except Exception as exc:
        return {'id': 'file-error', 'error': str(exc)}

def create_batch_job(path):
    uploaded = upload_batch_file(path)
    file_id = uploaded.get('id', '')
    if not OPENAI_API_KEY or not file_id or file_id.startswith('file-error'):
        return {'id': 'batch-mock', 'status': 'failed', 'input_file_id': file_id, 'error': uploaded.get('error', 'missing credentials')}
    payload = {
        'input_file_id': file_id,
        'endpoint': '/v1/chat/completions',
        'completion_window': COMPLETION_WINDOW,
    }
    data = json.dumps(payload).encode('utf-8')
    headers = {'Authorization': f'Bearer {OPENAI_API_KEY}', 'Content-Type': 'application/json'}
    request = urllib.request.Request(OPENAI_BATCH_URL, data=data, headers=headers, method='POST')
    try:
        with urllib.request.urlopen(request, timeout=60) as response:
            return json.loads(response.read().decode('utf-8'))
    except Exception as exc:
        return {'id': 'batch-error', 'status': 'failed', 'error': str(exc)}

batch_job = create_batch_job(batch_jsonl_path)

import json
import os
import time
import urllib.request

OPENAI_BATCH_STATUS_URL = 'https://api.openai.com/v1/batches'
MAX_POLL_ATTEMPTS = 5

def poll_batch_status(job):
    batch_id = str(job.get('id', ''))
    if not OPENAI_API_KEY or not batch_id or batch_id.startswith('batch-mock') or batch_id.startswith('batch-error'):
        return {'id': batch_id, 'status': 'completed', 'output_file_id': 'file-mock-output', 'error': job.get('error', '')}
    delay = 1
    for attempt in range(1, MAX_POLL_ATTEMPTS + 1):
        url = f'{OPENAI_BATCH_STATUS_URL}/{batch_id}'
        headers = {'Authorization': f'Bearer {OPENAI_API_KEY}'}
        request = urllib.request.Request(url, headers=headers, method='GET')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                current = json.loads(response.read().decode('utf-8'))
        except Exception as exc:
            return {'id': batch_id, 'status': 'failed', 'error': str(exc)}
        status = str(current.get('status', 'unknown'))
        if status in ('completed', 'failed', 'expired', 'cancelled'):
            return current
        time.sleep(delay)
        delay = min(delay * 2, 16)
    return {'id': batch_id, 'status': 'timeout', 'error': 'polling limit reached'}

completed_batch = poll_batch_status(batch_job)

import json
import os
import urllib.request

OPENAI_FILE_CONTENT_URL = 'https://api.openai.com/v1/files'

def download_batch_output(batch):
    output_file_id = str(batch.get('output_file_id', ''))
    if not OPENAI_API_KEY or not output_file_id or output_file_id.startswith('file-mock'):
        return [
            {'custom_id': 'prompt-001', 'response_text': 'Fallback batch output for dry-run.', 'model': 'gpt-4o-mini'},
            {'custom_id': 'prompt-002', 'response_text': 'Fallback batch output for dry-run.', 'model': 'gpt-4o-mini'},
        ]
    url = f'{OPENAI_FILE_CONTENT_URL}/{output_file_id}/content'
    headers = {'Authorization': f'Bearer {OPENAI_API_KEY}'}
    request = urllib.request.Request(url, headers=headers, method='GET')
    try:
        with urllib.request.urlopen(request, timeout=60) as response:
            raw = response.read().decode('utf-8')
    except Exception:
        return []
    records = []
    for line in raw.splitlines():
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except json.JSONDecodeError:
            continue
        response_body = item.get('response', {}).get('body', {})
        choices = response_body.get('choices', [])
        content = ''
        if choices:
            content = choices[0].get('message', {}).get('content', '')
        records.append({
            'custom_id': str(item.get('custom_id', '')),
            'response_text': str(content),
            'model': str(response_body.get('model', '')),
        })
    return records

batch_output_records = download_batch_output(completed_batch)

import json
import os
import urllib.request

SUPABASE_URL = os.environ.get('SUPABASE_URL', '')
SUPABASE_KEY = os.environ.get('SUPABASE_KEY', '')
SUPABASE_TABLE = 'batch_results'

def upsert_results(output_records):
    prompt_map = {str(item.get('custom_id', '')): str(item.get('prompt', '')) for item in queued_prompts}
    rows = []
    for record in output_records:
        custom_id = str(record.get('custom_id', ''))
        rows.append({
            'custom_id': custom_id,
            'prompt': prompt_map.get(custom_id, ''),
            'response_text': str(record.get('response_text', '')),
            'model': str(record.get('model', '')),
        })
    if not SUPABASE_URL or not SUPABASE_KEY or not rows:
        return rows
    endpoint = SUPABASE_URL.rstrip('/') + '/rest/v1/' + SUPABASE_TABLE
    data = json.dumps(rows).encode('utf-8')
    headers = {
        'apikey': SUPABASE_KEY,
        'Authorization': f'Bearer {SUPABASE_KEY}',
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates,return=representation',
    }
    request = urllib.request.Request(endpoint, data=data, headers=headers, method='POST')
    try:
        with urllib.request.urlopen(request, timeout=60) as response:
            if response.status not in (200, 201, 204):
                return rows
            body = response.read().decode('utf-8')
            if body:
                return json.loads(body)
            return rows
    except Exception:
        return rows

stored_rows = upsert_results(batch_output_records)

"""Step 2 of the AI Customer Insights workflow.

Sends the aggregated PostHog cohort summary to the OpenAI Chat Completions
API and returns the generated behaviour insights.
"""

import json
import os
import sys
import time
import urllib.error
import urllib.request

OPENAI_CHAT_URL = "https://api.openai.com/v1/chat/completions"
OPENAI_MODEL = "gpt-4o-mini"
REQUEST_TIMEOUT_SECONDS = 60
MAX_ATTEMPTS = 4
RETRYABLE_STATUS = {408, 409, 429, 500, 502, 503, 504}
SYSTEM_PROMPT = (
    "You are a product analytics assistant. Given an aggregated cohort "
    "summary from PostHog, produce concise, actionable insights about user "
    "behaviour. Group findings by cohort, call out notable retention or "
    "conversion patterns, and finish with three prioritised recommendations."
)


def _require_api_key() -> str:
    api_key = os.environ.get("OPENAI_API_KEY", "").strip()
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is not set; cannot call the OpenAI API.")
    return api_key


def _validate_cohorts(cohorts) -> list:
    if not isinstance(cohorts, list) or not cohorts:
        raise ValueError("cohorts must be a non-empty list of cohort records.")
    for index, cohort in enumerate(cohorts):
        if not isinstance(cohort, dict):
            raise ValueError(f"cohort at index {index} is not an object.")
    return cohorts


def _build_prompt(cohorts: list) -> str:
    serialised = json.dumps(cohorts, ensure_ascii=False, sort_keys=True)
    return (
        "Aggregated PostHog cohort summary (JSON):\n"
        f"{serialised}\n\n"
        "Return the insights as short markdown sections."
    )


def _post_json(url: str, headers: dict, payload: dict) -> dict:
    body = json.dumps(payload).encode("utf-8")
    last_error = ""
    for attempt in range(1, MAX_ATTEMPTS + 1):
        request = urllib.request.Request(url, data=body, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
                raw = response.read().decode("utf-8")
            return json.loads(raw)
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:500]
            last_error = f"HTTP {exc.code}: {detail}"
            if exc.code not in RETRYABLE_STATUS or attempt == MAX_ATTEMPTS:
                raise RuntimeError(f"OpenAI request failed ({last_error})") from exc
        except urllib.error.URLError as exc:
            last_error = f"network error: {exc.reason}"
            if attempt == MAX_ATTEMPTS:
                raise RuntimeError(f"OpenAI request failed ({last_error})") from exc
        except json.JSONDecodeError as exc:
            raise RuntimeError("OpenAI returned a non-JSON response body.") from exc
        time.sleep(min(2 ** attempt, 30))
    raise RuntimeError(f"OpenAI request failed after {MAX_ATTEMPTS} attempts ({last_error})")


def summarize_behavior(cohorts: list) -> str:
    validated = _validate_cohorts(cohorts)
    headers = {
        "Authorization": f"Bearer {_require_api_key()}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    payload = {
        "model": OPENAI_MODEL,
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": _build_prompt(validated)},
        ],
    }
    result = _post_json(OPENAI_CHAT_URL, headers, payload)
    choices = result.get("choices") or []
    if not choices:
        raise RuntimeError("OpenAI response contained no choices.")
    content = (choices[0].get("message") or {}).get("content", "").strip()
    if not content:
        raise RuntimeError("OpenAI response contained an empty insight message.")
    return content


def run_step(step_input: dict) -> dict:
    if not isinstance(step_input, dict):
        raise ValueError("step input must be a JSON object.")
    cohorts = step_input.get("cohorts")
    insights = summarize_behavior(cohorts)
    return {"step": "summarise_behaviour_with_openai", "insights": insights}


def _load_step_input() -> dict:
    raw = os.environ.get("FLOWMATRIX_STEP_INPUT", "").strip()
    if not raw:
        raise RuntimeError("FLOWMATRIX_STEP_INPUT is empty; pass the PostHog cohort payload as JSON.")
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise RuntimeError("FLOWMATRIX_STEP_INPUT is not valid JSON.") from exc


if __name__ == "__main__":
    try:
        print(json.dumps(run_step(_load_step_input()), indent=2, ensure_ascii=False))
    except (RuntimeError, ValueError) as error:
        print(f"step failed: {error}", file=sys.stderr)
        raise SystemExit(1)

import json
import math
import os
from typing import Any

GEMINI_API_KEY = os.environ.get("GEMINI_API_KEY", "")

REQUIRED_RESULT_FIELD = "attributes"
SCALAR_TYPES = (str, int, float, bool)

def _clean_scalar(value: Any) -> Any:
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, float):
        if not math.isfinite(value):
            return None
        return round(value, 6)
    return value

def _normalise_attributes_dict(attributes: dict[Any, Any]) -> dict[str, Any] | None:
    cleaned: dict[str, Any] = {}
    for raw_key, raw_value in attributes.items():
        if not isinstance(raw_key, str):
            continue
        key = raw_key.strip()
        if not key:
            continue
        if raw_value is None:
            continue
        if not isinstance(raw_value, SCALAR_TYPES):
            continue
        value = _clean_scalar(raw_value)
        if value is None or value == "":
            continue
        cleaned[key] = value
    if not cleaned:
        return None
    try:
        json.dumps(cleaned, allow_nan=False)
    except (TypeError, ValueError):
        return None
    return cleaned

def normalize_attributes(analyzed_results: Any) -> list[dict[str, Any]]:
    if isinstance(analyzed_results, str):
        try:
            analyzed_results = json.loads(analyzed_results)
        except json.JSONDecodeError:
            return []
    if not isinstance(analyzed_results, list):
        return []
    valid_records: list[dict[str, Any]] = []
    for result in analyzed_results:
        if not isinstance(result, dict):
            continue
        if REQUIRED_RESULT_FIELD not in result:
            continue
        attributes = result[REQUIRED_RESULT_FIELD]
        if isinstance(attributes, dict):
            record = _normalise_attributes_dict(attributes)
            if record is not None:
                valid_records.append(record)
        elif isinstance(attributes, list):
            for item in attributes:
                if isinstance(item, dict):
                    record = _normalise_attributes_dict(item)
                    if record is not None:
                        valid_records.append(record)
    return valid_records

normalized_results = normalize_attributes(analyzed_results)

import json
import os
import tempfile
from collections.abc import Iterable, Mapping
from typing import Any

GEMINI_API_KEY = os.environ.get('GEMINI_API_KEY', '')
REPORT_PATH = os.environ.get('ATTRIBUTE_REPORT_PATH', 'attribute_report.json')

def _asset_url(asset: Mapping[str, Any]) -> str:
    if not isinstance(asset, Mapping):
        raise TypeError('Each blob asset must be a mapping.')
    url = asset.get('url')
    if not isinstance(url, str) or not url.strip():
        raise ValueError('Each blob asset must contain a non-empty string url.')
    return url.strip()

def write_report(
    normalized_results: Iterable[Any],
    blob_assets: Iterable[Mapping[str, Any]],
    output_path: str = REPORT_PATH,
) -> dict[str, Any]:
    assets = list(blob_assets)
    results = list(normalized_results)
    if len(assets) != len(results):
        raise ValueError('blob_assets and normalized_results must have the same length.')
    report: dict[str, Any] = {}
    for asset, attributes in zip(assets, results):
        url = _asset_url(asset)
        if url in report:
            raise ValueError(f'Duplicate blob URL in report: {url}')
        report[url] = attributes
    directory = os.path.dirname(os.path.abspath(output_path)) or '.'
    os.makedirs(directory, exist_ok=True)
    fd, temp_path = tempfile.mkstemp(
        prefix='.attribute_report_',
        suffix='.json',
        dir=directory,
        text=True,
    )
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            json.dump(report, handle, indent=4, sort_keys=True, ensure_ascii=False)
        os.replace(temp_path, output_path)
    except Exception:
        try:
            os.unlink(temp_path)
        except FileNotFoundError:
            pass
        raise
    return report

write_report(normalized_results, blob_assets)

def apply_confidence_threshold(response, threshold=0.7):
    # Get the confidence score from the response
    confidence = response.get('output', {}).get('generic', [{}])[0].get('confidence', 0)

    # Check if the confidence score is below the threshold
    if confidence < threshold:
        return True  # Flag for escalation

    return False  # No escalation needed

