import os
import re
from typing import Final

_MARKER_PATTERN: Final[re.Pattern[str]] = re.compile(r'\[marker\]', re.IGNORECASE)

def _require_text(script: object) -> str:
    if not isinstance(script, str):
        raise TypeError('Voiceover script must be a string.')
    if not script.strip():
        raise ValueError('Voiceover script cannot be empty or whitespace-only.')
    return script

def _reject_unsupported_characters(script: str) -> None:
    for index, character in enumerate(script):
        if character in ('\n', '\r', '\t'):
            continue
        if ord(character) < 32 or ord(character) == 127:
            raise ValueError(f'Voiceover script contains unsupported control character at index {index}.')

def _normalize_markers(script: str) -> str:
    normalized = _MARKER_PATTERN.sub('', script)
    normalized = re.sub(r'[ \t]{2,}', ' ', normalized)
    normalized = re.sub(r'\n{3,}', '\n\n', normalized)
    return normalized.strip()

def validate_script(script: object) -> str:
    text = _require_text(script)
    _reject_unsupported_characters(text)
    normalized = _normalize_markers(text)
    if not normalized:
        raise ValueError('Voiceover script is empty after marker normalization.')
    return normalized

raw_script = os.environ.get('VOICEOVER_SCRIPT', '')
validated_script = validate_script(raw_script)
print(validated_script)

import json
import os
import urllib.error
import urllib.parse
import urllib.request
import uuid

WEAVIATE_URL = os.environ.get('WEAVIATE_URL', '').rstrip('/')
WEAVIATE_API_KEY = os.environ.get('WEAVIATE_API_KEY', '')
WEAVIATE_CLASS = os.environ.get('WEAVIATE_CLASS', 'Article')
WEAVIATE_TIMEOUT = float(os.environ.get('WEAVIATE_TIMEOUT', '30'))

def _headers():
    headers = {'Content-Type': 'application/json', 'Accept': 'application/json'}
    if WEAVIATE_API_KEY:
        headers['Authorization'] = f'Bearer {WEAVIATE_API_KEY}'
    return headers

def _request_json(method, path, payload=None):
    if not WEAVIATE_URL:
        raise RuntimeError('WEAVIATE_URL environment variable is required')
    url = f'{WEAVIATE_URL}{path}'
    data = None
    if payload is not None:
        data = json.dumps(payload).encode('utf-8')
    request = urllib.request.Request(url, data=data, headers=_headers(), method=method)
    try:
        with urllib.request.urlopen(request, timeout=WEAVIATE_TIMEOUT) as response:
            raw = response.read().decode('utf-8')
            if not raw.strip():
                return {}
            return json.loads(raw)
    except urllib.error.HTTPError as exc:
        body = exc.read().decode('utf-8', errors='replace')
        raise RuntimeError(f'Weaviate {method} {path} failed with {exc.code}: {body}') from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f'Weaviate {method} {path} failed: {exc.reason}') from exc

def _object_uuid(article_id):
    text = str(article_id)
    try:
        return str(uuid.UUID(text))
    except ValueError:
        return str(uuid.uuid5(uuid.NAMESPACE_URL, f'article:{text}'))

def _validate_embedding(embedding):
    if not isinstance(embedding, (list, tuple)) or not embedding:
        raise ValueError('embedding must be a non-empty list of numbers')
    vector = []
    for value in embedding:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError('embedding values must be numeric')
        vector.append(float(value))
    return vector

def index_embeddings(embeddings, article_ids=None):
    if not isinstance(embeddings, (list, tuple)) or not embeddings:
        raise ValueError('embeddings must be a non-empty sequence')
    if article_ids is None:
        article_ids = [str(index) for index in range(len(embeddings))]
    if len(article_ids) != len(embeddings):
        raise ValueError('article_ids and embeddings must have the same length')
    indexed_ids = []
    for article_id, embedding in zip(article_ids, embeddings):
        vector = _validate_embedding(embedding)
        object_id = _object_uuid(article_id)
        payload = {
            'class': WEAVIATE_CLASS,
            'id': object_id,
            'properties': {'article_id': str(article_id)},
            'vector': vector,
        }
        _request_json('POST', '/v1/objects', payload)
        indexed_ids.append(object_id)
    return indexed_ids

def find_neighbors(object_id, limit=5):
    if not object_id:
        raise ValueError('object_id is required')
    if limit < 1:
        raise ValueError('limit must be positive')
    encoded_id = urllib.parse.quote(str(object_id), safe='')
    path = f'/v1/objects/{encoded_id}/neighbors?limit={int(limit)}'
    response = _request_json('GET', path)
    if not response:
        return []
    neighbors = response.get('neighbors', response.get('objects', []))
    return neighbors if isinstance(neighbors, list) else []

def index_and_compare(embeddings, article_ids=None, neighbor_limit=5):
    indexed_ids = index_embeddings(embeddings, article_ids)
    comparisons = {}
    for object_id in indexed_ids:
        comparisons[object_id] = find_neighbors(object_id, limit=neighbor_limit)
    return comparisons

def main():
    embeddings_raw = os.environ.get('ARTICLE_EMBEDDINGS_JSON', '')
    if not embeddings_raw:
        raise RuntimeError('ARTICLE_EMBEDDINGS_JSON environment variable is required')
    embeddings = json.loads(embeddings_raw)
    article_ids_raw = os.environ.get('ARTICLE_IDS_JSON', '')
    article_ids = json.loads(article_ids_raw) if article_ids_raw else None
    neighbor_limit = int(os.environ.get('NEIGHBOR_LIMIT', '5'))
    result = index_and_compare(embeddings, article_ids, neighbor_limit)
    print(json.dumps(result, indent=2, sort_keys=True))

main()

import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

AIRTABLE_API_URL = "https://api.airtable.com/v0"
MAX_BATCH_SIZE = 10
MAX_RETRIES = 5
RETRY_BASE_DELAY = 1.0
REQUEST_TIMEOUT = 30


def _build_record(duplicate):
    """Convert one duplicate pair into an Airtable record payload."""
    id1 = str(duplicate.get("id1", "")).strip()
    id2 = str(duplicate.get("id2", "")).strip()
    if not id1 or not id2:
        raise ValueError(f"duplicate pair is missing article ids: {duplicate!r}")
    try:
        score = float(duplicate["score"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(f"duplicate pair has an invalid score: {duplicate!r}") from exc
    if not 0.0 <= score <= 1.0:
        raise ValueError(f"similarity score out of range: {score}")
    return {
        "fields": {
            "article_id_1": id1,
            "article_id_2": id2,
            "similarity_score": round(score, 6),
        }
    }


def _post_json(url, payload, api_key):
    """Send a single JSON POST request to the Airtable REST API."""
    body = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=body,
        method="POST",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )
    with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT) as response:
        return json.loads(response.read().decode("utf-8"))


def _post_with_retry(url, payload, api_key):
    """POST with exponential backoff for rate limits and transient failures."""
    delay = RETRY_BASE_DELAY
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return _post_json(url, payload, api_key)
        except urllib.error.HTTPError as exc:
            if exc.code == 429 and attempt < MAX_RETRIES:
                retry_after = exc.headers.get("Retry-After") if exc.headers else None
                try:
                    wait = float(retry_after) if retry_after else delay
                except (TypeError, ValueError):
                    wait = delay
                time.sleep(wait)
                delay = min(delay * 2, 30.0)
                continue
            detail = exc.read().decode("utf-8", errors="replace")
            raise RuntimeError(f"Airtable request failed ({exc.code}): {detail}") from exc
        except urllib.error.URLError as exc:
            if attempt < MAX_RETRIES:
                time.sleep(delay)
                delay = min(delay * 2, 30.0)
                continue
            raise RuntimeError(f"Airtable request failed: {exc.reason}") from exc
    raise RuntimeError("Airtable request exhausted all retries")


def log_duplicates(duplicates, base_id, table_name, api_key):
    """Log near-duplicate article pairs into the Airtable audit table."""
    if not base_id:
        raise ValueError("AIRTABLE_BASE_ID is not set")
    if not table_name:
        raise ValueError("AIRTABLE_TABLE_NAME is not set")
    if not api_key:
        raise ValueError("AIRTABLE_API_KEY is not set")

    records = []
    for item in duplicates:
        try:
            records.append(_build_record(item))
        except ValueError as exc:
            print(f"skipping invalid duplicate pair: {exc}", file=sys.stderr)
    if not records:
        return []

    url = "{}/{}/{}".format(
        AIRTABLE_API_URL,
        urllib.parse.quote(base_id, safe=""),
        urllib.parse.quote(table_name, safe=""),
    )

    created_ids = []
    for start in range(0, len(records), MAX_BATCH_SIZE):
        batch = records[start:start + MAX_BATCH_SIZE]
        result = _post_with_retry(url, {"records": batch, "typecast": True}, api_key)
        for record in result.get("records", []):
            record_id = record.get("id")
            if record_id:
                created_ids.append(record_id)
    return created_ids


def main():
    api_key = os.environ.get("AIRTABLE_API_KEY", "")
    base_id = os.environ.get("AIRTABLE_BASE_ID", "")
    table_name = os.environ.get("AIRTABLE_TABLE_NAME", "Duplicates")

    raw = sys.stdin.read().strip()
    if not raw:
        raise SystemExit("no duplicate pairs provided on stdin")
    duplicates = json.loads(raw)
    if not isinstance(duplicates, list):
        raise SystemExit("duplicate payload must be a JSON array")

    created = log_duplicates(duplicates, base_id, table_name, api_key)
    print(json.dumps({"logged": len(created), "record_ids": created}))


if __name__ == "__main__":
    main()

import json
import os
import urllib.error
import urllib.request

RESEND_ENDPOINT = 'https://api.resend.com/emails'
RESEND_API_KEY = os.environ.get('RESEND_API_KEY', '')
RESEND_FROM_EMAIL = os.environ.get('RESEND_FROM_EMAIL', 'onboarding@resend.dev')

def send_via_resend(messages):
    results = []
    if not RESEND_API_KEY:
        for message in messages:
            results.append({
                'email': message,
                'provider': 'resend',
                'success': False,
                'message_id': '',
                'status_code': 0,
                'error': 'RESEND_API_KEY is not configured'
            })
        return results
    for message in messages:
        payload = {
            'from': RESEND_FROM_EMAIL,
            'to': [message.get('recipient', '')],
            'subject': message.get('subject', ''),
            'html': message.get('html', ''),
            'headers': {'X-Entity-Ref-ID': message.get('id', '')}
        }
        data = json.dumps(payload).encode('utf-8')
        headers = {
            'Authorization': f'Bearer {RESEND_API_KEY}',
            'Content-Type': 'application/json'
        }
        request = urllib.request.Request(RESEND_ENDPOINT, data=data, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                body = json.loads(response.read().decode('utf-8'))
                results.append({
                    'email': message,
                    'provider': 'resend',
                    'success': True,
                    'message_id': str(body.get('id', '')),
                    'status_code': int(response.status),
                    'error': ''
                })
        except urllib.error.HTTPError as exc:
            error_body = exc.read().decode('utf-8', errors='replace')
            results.append({
                'email': message,
                'provider': 'resend',
                'success': False,
                'message_id': '',
                'status_code': int(exc.code),
                'error': error_body[:500]
            })
        except (urllib.error.URLError, ValueError) as exc:
            results.append({
                'email': message,
                'provider': 'resend',
                'success': False,
                'message_id': '',
                'status_code': 0,
                'error': str(exc)[:500]
            })
    return results

