import json
import os
import urllib.error
import urllib.request

LOG_SUPABASE_URL = os.environ.get('SUPABASE_URL', '').rstrip('/')
LOG_SUPABASE_KEY = os.environ.get('SUPABASE_KEY', '')
DELIVERY_LOG_TABLE = 'email_delivery_logs'

def record_outcomes(outcomes):
    if not LOG_SUPABASE_URL or not LOG_SUPABASE_KEY:
        return {'error': 'Supabase credentials are not configured', 'records': []}
    if not outcomes:
        return []
    records = []
    for item in outcomes:
        records.append({
            'email_id': str(item.get('email_id', '')),
            'recipient': str(item.get('recipient', '')),
            'subject': str(item.get('subject', '')),
            'provider': str(item.get('provider', '')),
            'success': bool(item.get('success', False)),
            'message_id': str(item.get('message_id', '')),
            'status_code': int(item.get('status_code', 0) or 0),
            'error_message': str(item.get('error', ''))[:500]
        })
    url = f'{LOG_SUPABASE_URL}/rest/v1/{DELIVERY_LOG_TABLE}'
    headers = {
        'apikey': LOG_SUPABASE_KEY,
        'Authorization': f'Bearer {LOG_SUPABASE_KEY}',
        'Content-Type': 'application/json',
        'Prefer': 'return=representation'
    }
    data = json.dumps(records).encode('utf-8')
    request = urllib.request.Request(url, data=data, headers=headers, method='POST')
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            if response.status not in (200, 201, 204):
                return {'error': f'Unexpected Supabase status: {response.status}', 'records': []}
            body = response.read().decode('utf-8')
            return json.loads(body) if body else []
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode('utf-8', errors='replace')
        return {'error': error_body[:500], 'records': []}
    except (urllib.error.URLError, ValueError) as exc:
        return {'error': str(exc)[:500], 'records': []}

