import json
import os
from typing import Any

DEFAULT_CRITICAL_SEVERITIES = {'critical', 'high', 'urgent'}
SEVERITY_PRIORITY = {'critical': 0, 'urgent': 1, 'high': 2}


def _normalise_severity(value: Any) -> str:
    if isinstance(value, str):
        return value.strip().lower()
    return ''


def _parse_critical_severities(raw: str) -> set[str]:
    parsed = {part.strip().lower() for part in raw.split(',') if part.strip()}
    return parsed or set(DEFAULT_CRITICAL_SEVERITIES)


def _read_alert_queue(path: str) -> list[dict[str, Any]]:
    if not path:
        print('ALERT_QUEUE_PATH is not configured; no alerts loaded.')
        return []
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            payload = json.load(handle)
    except FileNotFoundError:
        print(f'Alert queue file not found: {path}')
        return []
    except (OSError, json.JSONDecodeError) as exc:
        print(f'Unable to read alert queue {path}: {exc}')
        return []
    if isinstance(payload, list):
        return [item for item in payload if isinstance(item, dict)]
    if isinstance(payload, dict) and isinstance(payload.get('alerts'), list):
        return [item for item in payload['alerts'] if isinstance(item, dict)]
    print('Alert queue must be a JSON list or an object with an alerts list.')
    return []


def load_critical_alerts() -> list[dict[str, Any]]:
    queue_path = os.environ.get('ALERT_QUEUE_PATH', '')
    critical_raw = os.environ.get('ALERT_CRITICAL_SEVERITIES', '')
    critical_severities = _parse_critical_severities(critical_raw)
    alerts = _read_alert_queue(queue_path)
    critical_alerts: list[dict[str, Any]] = []
    for alert in alerts:
        severity = _normalise_severity(alert.get('severity'))
        if severity not in critical_severities:
            continue
        enriched = dict(alert)
        enriched['severity'] = severity
        critical_alerts.append(enriched)
    critical_alerts.sort(
        key=lambda item: (
            SEVERITY_PRIORITY.get(item['severity'], len(SEVERITY_PRIORITY)),
            str(item.get('created_at', '')),
        )
    )
    print(f'Loaded {len(critical_alerts)} critical alert(s) from {len(alerts)} queued alert(s).')
    return critical_alerts


critical_alerts = load_critical_alerts()

import base64
import json
import os
import urllib.error
import urllib.parse
import urllib.request

TWILIO_API_BASE = "https://api.twilio.com/2010-04-01/Accounts"
MAX_SMS_BODY_LENGTH = 1600


def _required_env(name: str) -> str:
    value = os.environ.get(name, "").strip()
    if not value:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value


def _validate_phone_number(number: str, label: str) -> str:
    cleaned = number.strip()
    if not cleaned.startswith("+") or not cleaned[1:].isdigit() or not (8 <= len(cleaned) <= 16):
        raise ValueError(f"{label} must be an E.164 phone number")
    return cleaned


def send_sms_twilio(alert: dict) -> dict:
    account_sid = _required_env("TWILIO_ACCOUNT_SID")
    auth_token = _required_env("TWILIO_AUTH_TOKEN")
    to_number = _validate_phone_number(_required_env("TO_PHONE_NUMBER"), "TO_PHONE_NUMBER")
    from_number = _validate_phone_number(_required_env("TWILIO_PHONE_NUMBER"), "TWILIO_PHONE_NUMBER")
    message = str(alert.get("message", "")).strip()
    if not message:
        raise ValueError("Alert message is empty")
    if len(message) > MAX_SMS_BODY_LENGTH:
        raise ValueError(f"Alert message exceeds {MAX_SMS_BODY_LENGTH} characters")
    url = f"{TWILIO_API_BASE}/{urllib.parse.quote(account_sid, safe='')}/Messages.json"
    payload = urllib.parse.urlencode({"To": to_number, "From": from_number, "Body": message}).encode("utf-8")
    credentials = base64.b64encode(f"{account_sid}:{auth_token}".encode("utf-8")).decode("ascii")
    request = urllib.request.Request(url, data=payload, method="POST")
    request.add_header("Authorization", f"Basic {credentials}")
    request.add_header("Content-Type", "application/x-www-form-urlencoded")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response_body = response.read().decode("utf-8")
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Twilio HTTP {exc.code}: {error_body}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Twilio request failed: {exc.reason}") from exc
    return json.loads(response_body)


def load_alerts() -> list[dict]:
    raw = os.environ.get("CRITICAL_ALERTS_JSON", "").strip()
    if not raw:
        raise RuntimeError("Missing required environment variable: CRITICAL_ALERTS_JSON")
    alerts = json.loads(raw)
    if not isinstance(alerts, list) or not alerts:
        raise ValueError("CRITICAL_ALERTS_JSON must contain a non-empty JSON array")
    return alerts


def main() -> None:
    alerts = load_alerts()
    for alert in alerts:
        if not isinstance(alert, dict):
            raise ValueError("Each alert must be a JSON object")
        response = send_sms_twilio(alert)
        print(json.dumps({"sid": response.get("sid"), "status": response.get("status")}))


if __name__ == "__main__":
    main()

import base64
import json
import os
import urllib.error
import urllib.parse
import urllib.request


class RateLimitError(RuntimeError):
    """Raised when Twilio rejects a message because of rate limiting."""


def _required_env(name: str) -> str:
    value = os.environ.get(name, "").strip()
    if not value:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value


def send_sms_twilio(message: str) -> dict:
    account_sid = _required_env("TWILIO_ACCOUNT_SID")
    auth_token = _required_env("TWILIO_AUTH_TOKEN")
    from_number = _required_env("TWILIO_FROM_NUMBER")
    to_number = _required_env("TO_PHONE_NUMBER")
    url = f"https://api.twilio.com/2010-04-01/Accounts/{account_sid}/Messages.json"
    payload = urllib.parse.urlencode({
        "To": to_number,
        "From": from_number,
        "Body": message,
    }).encode("utf-8")
    credentials = base64.b64encode(f"{account_sid}:{auth_token}".encode("utf-8")).decode("ascii")
    request = urllib.request.Request(url, data=payload, method="POST")
    request.add_header("Authorization", f"Basic {credentials}")
    request.add_header("Content-Type", "application/x-www-form-urlencoded")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        lowered = body.lower()
        if exc.code == 429 or "20429" in body or "rate limit" in lowered or "too many requests" in lowered:
            raise RateLimitError(f"Twilio rate limit response: HTTP {exc.code}") from exc
        raise RuntimeError(f"Twilio SMS failed: HTTP {exc.code}: {body}") from exc


def send_sms_sendinblue(message: str) -> dict:
    api_key = _required_env("SENDINBLUE_API_KEY")
    sender = _required_env("SENDINBLUE_SENDER")
    recipient = _required_env("TO_PHONE_NUMBER")
    url = "https://api.sendinblue.com/v3/sms/send"
    payload = json.dumps({
        "sender": sender,
        "recipient": recipient,
        "content": message,
    }).encode("utf-8")
    request = urllib.request.Request(url, data=payload, method="POST")
    request.add_header("Authorization", f"Bearer {api_key}")
    request.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Sendinblue SMS failed: HTTP {exc.code}: {body}") from exc


def main() -> None:
    message = os.environ.get("ALERT_MESSAGE", "").strip()
    if not message:
        raise RuntimeError("Missing required environment variable: ALERT_MESSAGE")
    try:
        result = send_sms_twilio(message)
        print(json.dumps({"provider": "twilio", "result": result}, sort_keys=True))
    except RateLimitError as exc:
        print(f"Twilio rate limit detected: {exc}")
        result = send_sms_sendinblue(message)
        print(json.dumps({"provider": "sendinblue", "result": result}, sort_keys=True))


if __name__ == "__main__":
    main()

import json
import os
import urllib.error
import urllib.parse
import urllib.request


def _required_env(name: str) -> str:
    value = os.environ.get(name, '')
    if not value:
        raise RuntimeError(f'Missing required environment variable: {name}')
    return value


def _normalize_receipt(receipt: dict, provider: str) -> dict:
    if not isinstance(receipt, dict):
        raise TypeError('receipt must be a dictionary')
    message_id = receipt.get('sid') or receipt.get('messageId') or receipt.get('message_id')
    status = receipt.get('status') or receipt.get('delivery_status')
    if not message_id:
        raise ValueError(f'{provider} receipt is missing a message identifier')
    if not status:
        raise ValueError(f'{provider} receipt is missing a delivery status')
    return {
        'provider': provider,
        'message_id': str(message_id),
        'status': str(status),
    }


def store_receipt(receipt: dict, provider: str) -> dict:
    supabase_url = _required_env('SUPABASE_URL').rstrip('/')
    supabase_key = _required_env('SUPABASE_KEY')
    table = os.environ.get('SUPABASE_RECEIPTS_TABLE', 'delivery_receipts')
    if not table:
        raise RuntimeError('SUPABASE_RECEIPTS_TABLE must not be empty')

    row = _normalize_receipt(receipt, provider)
    query = urllib.parse.urlencode({'on_conflict': 'provider,message_id'}, safe=',')
    endpoint = f'{supabase_url}/rest/v1/{urllib.parse.quote(table)}?{query}'
    body = json.dumps(row, separators=(',', ':')).encode('utf-8')
    request = urllib.request.Request(endpoint, data=body, method='POST')
    request.add_header('apikey', supabase_key)
    request.add_header('Authorization', f'Bearer {supabase_key}')
    request.add_header('Content-Type', 'application/json')
    request.add_header('Accept', 'application/json')
    request.add_header('Prefer', 'resolution=merge-duplicates,return=representation')

    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response_body = response.read().decode('utf-8')
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode('utf-8', errors='replace')
        raise RuntimeError(f'Supabase upsert failed with HTTP {exc.code}: {error_body}') from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f'Supabase request failed: {exc.reason}') from exc

    if not response_body:
        return {}
    parsed = json.loads(response_body)
    if isinstance(parsed, list):
        return parsed[0] if parsed else {}
    if isinstance(parsed, dict):
        return parsed
    raise RuntimeError('Unexpected Supabase response shape')


def _load_receipt_from_env(name: str) -> dict:
    raw = os.environ.get(name, '')
    if not raw:
        raise RuntimeError(f'Missing required environment variable: {name}')
    parsed = json.loads(raw)
    if not isinstance(parsed, dict):
        raise ValueError(f'{name} must contain a JSON object')
    return parsed


def main() -> None:
    twilio_receipt = _load_receipt_from_env('TWILIO_RECEIPT_JSON')
    sendinblue_receipt = _load_receipt_from_env('SENDINBLUE_RECEIPT_JSON')
    store_receipt(twilio_receipt, 'Twilio')
    store_receipt(sendinblue_receipt, 'Sendinblue')


main()

