import json
import os
import urllib.parse
import urllib.request

NOTION_TOKEN = os.environ.get('NOTION_TOKEN', '')
NOTION_VERSION = '2022-06-28'
NOTION_BASE = 'https://api.notion.com/v1'

def notion_request(path, method='GET', payload=None):
    url = NOTION_BASE + path
    data = json.dumps(payload).encode('utf-8') if payload is not None else None
    headers = {
        'Authorization': 'Bearer ' + NOTION_TOKEN,
        'Notion-Version': NOTION_VERSION,
        'Content-Type': 'application/json',
    }
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    with urllib.request.urlopen(request, timeout=30) as response:
        return json.loads(response.read().decode('utf-8'))

def extract_rich_text(rich_text_items):
    parts = []
    for item in rich_text_items or []:
        plain = item.get('plain_text', '')
        if plain:
            parts.append(plain)
    return ''.join(parts)

def extract_page_text(page_id):
    chunks = []
    cursor = None
    while True:
        query = '?page_size=100'
        if cursor:
            query = query + '&start_cursor=' + urllib.parse.quote(cursor)
        block_data = notion_request('/blocks/' + page_id + '/children' + query)
        for block in block_data.get('results', []):
            block_type = block.get('type', '')
            block_payload = block.get(block_type, {})
            rich = block_payload.get('rich_text', []) if isinstance(block_payload, dict) else []
            text = extract_rich_text(rich)
            if text:
                chunks.append(text)
        if not block_data.get('has_more', False):
            break
        cursor = block_data.get('next_cursor')
        if not cursor:
            break
    return chr(10).join(chunks)

def fetch_help_articles():
    payload = {'filter': {'property': 'object', 'value': 'page'}, 'page_size': 50}
    search_data = notion_request('/search', method='POST', payload=payload)
    articles = []
    for page in search_data.get('results', []):
        page_id = page.get('id', '')
        properties = page.get('properties', {})
        title = ''
        for prop in properties.values():
            if prop.get('type') == 'title':
                title = extract_rich_text(prop.get('title', []))
                break
        if not title:
            title = 'Untitled article'
        body = extract_page_text(page_id)
        if not body:
            continue
        articles.append({
            'id': page_id,
            'title': title,
            'url': page.get('url', ''),
            'text': body,
        })
    return articles

articles = fetch_help_articles()
print('Exported articles:', len(articles))

