import json
import os
import urllib.request

OPENAI_API_KEY = os.environ.get('OPENAI_API_KEY', '')
PINECONE_API_KEY = os.environ.get('PINECONE_API_KEY', '')
PINECONE_HOST = os.environ.get('PINECONE_HOST', '')
PINECONE_NAMESPACE = os.environ.get('PINECONE_NAMESPACE', 'help-center')
TOP_K = 3

# Respond ONLY with a float between -1.0 and 1.0
NUMERIC_OUTPUT_INSTRUCTION = 'Respond ONLY with a float between -1.0 and 1.0'


def to_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def embed_query(query_text):
    payload = {'model': 'text-embedding-3-small', 'input': query_text}
    data = json.dumps(payload).encode('utf-8')
    headers = {
        'Authorization': 'Bearer ' + OPENAI_API_KEY,
        'Content-Type': 'application/json',
    }
    request = urllib.request.Request(
        'https://api.openai.com/v1/embeddings',
        data=data,
        headers=headers,
        method='POST',
    )
    with urllib.request.urlopen(request, timeout=60) as response:
        body = json.loads(response.read().decode('utf-8'))
    items = body.get('data', [])
    if not items:
        return []
    return items[0].get('embedding', [])


def query_pinecone(vector):
    if not PINECONE_HOST:
        raise ValueError('PINECONE_HOST is required')
    payload = {
        'vector': vector,
        'topK': TOP_K,
        'includeMetadata': True,
        'namespace': PINECONE_NAMESPACE,
    }
    data = json.dumps(payload).encode('utf-8')
    headers = {
        'Api-Key': PINECONE_API_KEY,
        'Content-Type': 'application/json',
    }
    url = PINECONE_HOST.rstrip('/') + '/query'
    request = urllib.request.Request(url, data=data, headers=headers, method='POST')
    with urllib.request.urlopen(request, timeout=60) as response:
        return json.loads(response.read().decode('utf-8'))


def answer_query(query_text):
    vector = embed_query(query_text)
    if not vector:
        return {'query': query_text, 'matches': []}
    result = query_pinecone(vector)
    matches = []
    for match in result.get('matches', []):
        metadata = match.get('metadata', {})
        matches.append({
            'score': to_float(match.get('score', 0.0)),
            'title': metadata.get('title', ''),
            'url': metadata.get('url', ''),
        })
    return {'query': query_text, 'matches': matches}


if __name__ == '__main__':
    answer = answer_query('How do I reset my password?')
    top_matches = answer.get('matches', [])
    if top_matches:
        print('Top match:', top_matches[0].get('title', ''))
    else:
        print('No matches found')

import json
import os
import urllib.error
import urllib.parse
import urllib.request

STRIPE_API_BASE = "https://api.stripe.com/v1"

def _stripe_request(method, path, api_key, data=None):
    if not api_key:
        raise RuntimeError("STRIPE_API_KEY is not configured")
    url = f"{STRIPE_API_BASE}{path}"
    body = None
    headers = {"Authorization": f"Bearer {api_key}"}
    if data is not None:
        body = urllib.parse.urlencode(data).encode("utf-8")
        headers["Content-Type"] = "application/x-www-form-urlencoded"
    request = urllib.request.Request(url, data=body, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Stripe API error {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Stripe API connection error: {exc.reason}") from exc

def create_or_fetch_customer(email, api_key=None):
    normalized_email = email.strip().lower()
    if normalized_email.count("@") != 1 or " " in normalized_email:
        raise ValueError("A valid customer email address is required")
    local_part, domain_part = normalized_email.split("@", 1)
    if not local_part or "." not in domain_part or domain_part.startswith(".") or domain_part.endswith("."):
        raise ValueError("A valid customer email address is required")
    key = api_key if api_key is not None else os.environ.get("STRIPE_API_KEY", "")
    query = urllib.parse.urlencode({"email": normalized_email, "limit": 1})
    existing = _stripe_request("GET", f"/customers?{query}", key)
    data = existing.get("data", [])
    if data:
        return data[0]
    payload = {"email": normalized_email}
    return _stripe_request("POST", "/customers", key, payload)

customer_email = os.environ.get("CUSTOMER_EMAIL", "").strip()
if not customer_email:
    raise RuntimeError("CUSTOMER_EMAIL is not configured")
customer = create_or_fetch_customer(customer_email)
print(json.dumps({"id": customer.get("id"), "email": customer.get("email")}))

import json
import os
import time
import urllib.error
import urllib.request

RESEND_ENDPOINT = 'https://api.resend.com/emails'

def _required_env(name: str) -> str:
    value = os.environ.get(name, '').strip()
    if not value:
        raise RuntimeError('Missing required environment variable: ' + name)
    return value

def _validate_email(value: object) -> str:
    email = str(value).strip()
    if not email or email.count('@') != 1:
        raise ValueError('Invalid customer email address')
    local_part, domain_part = email.split('@')
    if not local_part or not domain_part or '.' not in domain_part:
        raise ValueError('Invalid customer email address')
    if any(ch.isspace() for ch in email):
        raise ValueError('Invalid customer email address')
    return email

def _normalize_invoice_summary(invoice_summary: object) -> str:
    empty_message = 'No invoice line items were provided.'
    if invoice_summary is None:
        return empty_message
    if isinstance(invoice_summary, str):
        text = invoice_summary.strip()
        return text if text else empty_message
    if isinstance(invoice_summary, (list, tuple)):
        if not invoice_summary:
            return empty_message
        return chr(10).join(str(item) for item in invoice_summary)
    if isinstance(invoice_summary, dict):
        if not invoice_summary:
            return empty_message
        return chr(10).join(str(key) + ': ' + str(value) for key, value in invoice_summary.items())
    return str(invoice_summary)

def send_receipt_email(customer_email: object, invoice_summary: object) -> dict:
    api_key = _required_env('RESEND_API_KEY')
    from_email = _validate_email(_required_env('RESEND_FROM_EMAIL'))
    recipient = _validate_email(customer_email)
    summary_text = _normalize_invoice_summary(invoice_summary)
    body_text = chr(10).join([
        'Thank you for your subscription payment.',
        '',
        'Invoice summary:',
        summary_text,
    ])
    payload = {
        'from': from_email,
        'to': [recipient],
        'subject': 'Your Subscription Receipt',
        'text': body_text,
    }
    data = json.dumps(payload).encode('utf-8')
    headers = {
        'Authorization': 'Bearer ' + api_key,
        'Content-Type': 'application/json',
        'Accept': 'application/json',
    }
    last_error = None
    for attempt in range(3):
        request = urllib.request.Request(RESEND_ENDPOINT, data=data, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                response_body = response.read().decode('utf-8')
                parsed = json.loads(response_body) if response_body else {}
                if not isinstance(parsed, dict):
                    raise RuntimeError('Unexpected Resend response shape')
                return parsed
        except urllib.error.HTTPError as exc:
            last_error = exc
            if exc.code == 429 or 500 <= exc.code < 600:
                retry_after = exc.headers.get('Retry-After', '')
                delay = float(retry_after) if retry_after.isdigit() else 2 ** attempt
                time.sleep(delay)
                continue
            detail = exc.read().decode('utf-8', errors='replace')
            raise RuntimeError('Resend API error ' + str(exc.code) + ': ' + detail) from exc
        except urllib.error.URLError as exc:
            last_error = exc
            if attempt < 2:
                time.sleep(2 ** attempt)
                continue
            raise RuntimeError('Resend API connection error: ' + str(exc.reason)) from exc
    raise RuntimeError('Resend API request failed after retries: ' + str(last_error))

def main() -> None:
    customer_email = _required_env('CUSTOMER_EMAIL')
    invoice_summary = os.environ.get('INVOICE_SUMMARY', '')
    response = send_receipt_email(customer_email, invoice_summary)
    status = response.get('status', '')
    message = response.get('message', '')
    if status and str(status).lower() not in {'success', 'sent', 'queued', 'ok'}:
        raise RuntimeError('Receipt email was not accepted: ' + (message or str(status)))
    print(json.dumps({'status': status or 'accepted', 'message': message or 'Receipt email sent'}))

main()

import os
from collections.abc import Iterable as IterableABC
from datetime import date, datetime, timezone
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, Iterable, List, Optional

# Secrets are not required for this deterministic comparison step.
_ = os.environ.get('FLOWMATRIX_STEP_SECRET', '')

def _normalize_amount(value: Any) -> Optional[Decimal]:
    if value is None or value == '':
        return None
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool):
        return None
    try:
        if isinstance(value, (int, float)):
            return Decimal(str(value))
        text = str(value).strip().replace(',', '')
        if text.startswith('$'):
            text = text[1:].strip()
        return Decimal(text)
    except (InvalidOperation, ValueError, TypeError):
        return None

def _normalize_date(value: Any) -> Optional[str]:
    if value is None or value == '':
        return None
    if isinstance(value, datetime):
        dt = value
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return dt.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    text = str(value).strip()
    if not text:
        return None
    try:
        if 'T' in text or ' ' in text:
            parsed = datetime.fromisoformat(text.replace('Z', '+00:00'))
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
            return parsed.date().isoformat()
        return date.fromisoformat(text[:10]).isoformat()
    except ValueError:
        return text[:10]

def _ledger_index(ledger: Any) -> Dict[str, Dict[str, Any]]:
    index: Dict[str, Dict[str, Any]] = {}
    if isinstance(ledger, dict):
        for key, entry in ledger.items():
            if isinstance(entry, dict):
                entry_id = str(entry.get('id') or entry.get('invoice_id') or key)
                index[entry_id] = entry
        return index
    if isinstance(ledger, IterableABC) and not isinstance(ledger, (str, bytes)):
        for entry in ledger:
            if not isinstance(entry, dict):
                continue
            entry_id = entry.get('id') or entry.get('invoice_id')
            if entry_id is not None:
                index[str(entry_id)] = entry
    return index

def detect_mismatches(paid_invoices: Iterable[Dict[str, Any]], ledger: Any) -> List[Dict[str, Any]]:
    ledger_by_id = _ledger_index(ledger)
    mismatches: List[Dict[str, Any]] = []
    seen_invoice_ids = set()

    for invoice in paid_invoices or []:
        if not isinstance(invoice, dict):
            continue
        invoice_id = invoice.get('id') or invoice.get('invoice_id')
        if invoice_id is None:
            mismatches.append({'invoice_id': None, 'issue': 'missing_invoice_id'})
            continue
        invoice_id = str(invoice_id)
        seen_invoice_ids.add(invoice_id)
        ledger_entry = ledger_by_id.get(invoice_id)

        if ledger_entry is None:
            mismatches.append({
                'invoice_id': invoice_id,
                'issue': 'missing_ledger_entry',
                'stripe_amount': invoice.get('amount'),
                'stripe_date': invoice.get('date') or invoice.get('created'),
            })
            continue

        invoice_amount = _normalize_amount(invoice.get('amount'))
        ledger_amount = _normalize_amount(ledger_entry.get('amount'))
        invoice_date = _normalize_date(invoice.get('date') or invoice.get('created'))
        ledger_date = _normalize_date(ledger_entry.get('date') or ledger_entry.get('created'))

        if invoice_amount is None or ledger_amount is None:
            mismatches.append({
                'invoice_id': invoice_id,
                'issue': 'invalid_amount',
                'stripe_amount': invoice.get('amount'),
                'ledger_amount': ledger_entry.get('amount'),
            })
        elif invoice_amount != ledger_amount:
            mismatches.append({
                'invoice_id': invoice_id,
                'issue': 'amount_mismatch',
                'stripe_amount': str(invoice_amount),
                'ledger_amount': str(ledger_amount),
            })

        if invoice_date is None or ledger_date is None:
            mismatches.append({
                'invoice_id': invoice_id,
                'issue': 'invalid_date',
                'stripe_date': invoice.get('date') or invoice.get('created'),
                'ledger_date': ledger_entry.get('date') or ledger_entry.get('created'),
            })
        elif invoice_date != ledger_date:
            mismatches.append({
                'invoice_id': invoice_id,
                'issue': 'date_mismatch',
                'stripe_date': invoice_date,
                'ledger_date': ledger_date,
            })

    for ledger_id, entry in ledger_by_id.items():
        if ledger_id not in seen_invoice_ids:
            mismatches.append({
                'invoice_id': ledger_id,
                'issue': 'missing_stripe_invoice',
                'ledger_amount': entry.get('amount'),
                'ledger_date': entry.get('date') or entry.get('created'),
            })

    return mismatches

mismatches = detect_mismatches(paid_invoices, ledger)

import json
import os
import time
import urllib.error
import urllib.request

OPENAI_URL = "https://api.openai.com/v1/chat/completions"
OPENAI_MODEL = "gpt-4o"
REQUEST_TIMEOUT_SECONDS = 30
MAX_RETRIES = 3
RETRY_BACKOFF_SECONDS = 2.0


def _build_prompt(mismatch: dict) -> str:
    invoice_id = mismatch.get("invoice_id")
    stripe_amount = mismatch.get("stripe_amount")
    ledger_amount = mismatch.get("ledger_amount")
    currency = mismatch.get("currency", "")
    if invoice_id is None or stripe_amount is None or ledger_amount is None:
        raise ValueError("Mismatch entry must include invoice_id, stripe_amount, and ledger_amount")
    return (
        "You are assisting with invoice reconciliation. "
        f"Invoice {invoice_id} has a discrepancy: Stripe reports {stripe_amount} {currency}, "
        f"while the ledger reports {ledger_amount} {currency}. "
        "Explain the likely cause of this mismatch in one short paragraph and suggest a concrete action to resolve it. "
        "Do not invent transaction IDs or amounts that are not provided."
    )


def _call_openai(api_key: str, prompt: str) -> str:
    payload = {
        "model": OPENAI_MODEL,
        "messages": [
            {"role": "system", "content": "You explain payment reconciliation mismatches and suggest practical next actions."},
            {"role": "user", "content": prompt},
        ],
        "temperature": 0.2,
    }
    body = json.dumps(payload).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    last_error = None
    for attempt in range(1, MAX_RETRIES + 1):
        request = urllib.request.Request(OPENAI_URL, data=body, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
                response_body = response.read().decode("utf-8")
            parsed = json.loads(response_body)
            choices = parsed.get("choices") or []
            if not choices:
                raise RuntimeError("OpenAI response did not contain any choices")
            content = choices[0].get("message", {}).get("content", "")
            if not isinstance(content, str) or not content.strip():
                raise RuntimeError("OpenAI response contained empty explanation content")
            return content.strip()
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            last_error = RuntimeError(f"OpenAI HTTP {exc.code}: {detail}")
            if exc.code not in (429, 500, 502, 503, 504):
                break
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError, RuntimeError) as exc:
            last_error = exc
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_BACKOFF_SECONDS * attempt)
    raise RuntimeError(f"OpenAI request failed after {MAX_RETRIES} attempts") from last_error


def explain_mismatches(mismatches: list[dict]) -> list[dict]:
    if not isinstance(mismatches, list):
        raise TypeError("mismatches must be a list")
    api_key = os.environ.get("OPENAI_API_KEY", "")
    if not api_key:
        raise RuntimeError("Missing required environment variable: OPENAI_API_KEY")
    explanations: list[dict] = []
    for index, mismatch in enumerate(mismatches):
        if not isinstance(mismatch, dict):
            raise TypeError(f"Mismatch at index {index} must be a dictionary")
        prompt = _build_prompt(mismatch)
        explanation = _call_openai(api_key, prompt)
        explanations.append({
            "invoice_id": mismatch.get("invoice_id"),
            "stripe_amount": mismatch.get("stripe_amount"),
            "ledger_amount": mismatch.get("ledger_amount"),
            "explanation": explanation,
        })
    return explanations


def main() -> None:
    raw_mismatches = os.environ.get("INVOICE_MISMATCHES_JSON", "")
    if not raw_mismatches:
        raise RuntimeError("Missing required environment variable: INVOICE_MISMATCHES_JSON")
    try:
        mismatches = json.loads(raw_mismatches)
    except json.JSONDecodeError as exc:
        raise ValueError("INVOICE_MISMATCHES_JSON must contain valid JSON") from exc
    explanations = explain_mismatches(mismatches)
    print(json.dumps({"explanations": explanations}, indent=2))


main()

