import json
import os
import time
import urllib.error
import urllib.request

OPENAI_URL = "https://api.openai.com/v1/chat/completions"
OPENAI_API_KEY = os.environ.get("OPENAI_API_KEY", "")
OPENAI_MODEL = "gpt-4o-mini"
CATEGORY_LIST = [
    "Groceries", "Dining", "Transport", "Utilities", "Subscription",
    "Healthcare", "Retail", "Travel", "Income", "Other",
]


def request_categories(names):
    system_prompt = "You are a bank transaction categorizer. Map every merchant name to exactly one allowed category."
    # The merchant list is embedded as JSON so the model receives an unambiguous machine-readable input.
    user_prompt = (
        "Allowed categories: " + ", ".join(CATEGORY_LIST) + ". Merchant names: " + json.dumps(names)
        + ". Respond ONLY with a JSON object whose keys are the merchant names and whose values are categories."
    )
    payload = {
        "model": OPENAI_MODEL,
        "temperature": 0,
        "response_format": {"type": "json_object"},
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
    }
    headers = {"Content-Type": "application/json", "Authorization": "Bearer " + OPENAI_API_KEY}
    request = urllib.request.Request(OPENAI_URL, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=60) as response:
            body = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        print("OpenAI HTTP error " + str(error.code))
        return {}
    choices = body.get("choices", [])
    first_choice = choices[0] if choices else {}
    content = first_choice.get("message", {}).get("content", "{}")
    try:
        parsed = json.loads(content)
    except ValueError:
        print("OpenAI content was not valid JSON, falling back to Other")
        return {}
    # A defensive isinstance check keeps the merge step safe if the model returns a list or scalar.
    return parsed if isinstance(parsed, dict) else {}


def categorize_merchants(transactions):
    unique_names = sorted({item.get("merchant_name", "") for item in transactions if item.get("merchant_name", "")})
    mapping = {}
    for start in range(0, len(unique_names), 40):
        mapping.update(request_categories(unique_names[start:start + 40]))
        time.sleep(1)
    enriched = []
    for transaction in transactions:
        merchant = transaction.get("merchant_name", "")
        category = mapping.get(merchant, "Other")
        if category not in CATEGORY_LIST:
            category = "Other"
        record = {
            "transaction_id": transaction.get("transaction_id", ""),
            "merchant_name": merchant,
            "category": category,
            "amount": transaction.get("amount", 0.0),
            "iso_currency_code": transaction.get("iso_currency_code", "USD"),
            "date": transaction.get("date", ""),
            "pending": bool(transaction.get("pending", False)),
        }
        enriched.append(record)
    return enriched


