def report_violation(decision, state):
    # Skip the network call when the request is allowed so Sentry only receives real violations.
    if decision.get('allowed', True):
        return {'sent': False, 'reason': 'request_allowed', 'event_id': ''}
    event = {
        'message': 'Rate limit exceeded for API key',
        'level': 'warning',
        'tags': {'api_key': decision.get('api_key', ''), 'limiter': 'redis-rate-limit-store'},
        'extra': {
            'count': decision.get('count', 0),
            'limit': decision.get('limit', 0),
            'retry_after': decision.get('retry_after', 0),
            'redis_key': state.get('redis_key', ''),
        },
    }
    url = 'https://sentry.io/api/0/projects/' + SENTRY_ORG + '/' + SENTRY_PROJECT + '/events/'
    body = json.dumps(event).encode('utf-8')
    headers = {'Authorization': 'Bearer ' + SENTRY_AUTH_TOKEN, 'Content-Type': 'application/json'}
    request = urllib.request.Request(url, data=body, headers=headers, method='POST')
    with urllib.request.urlopen(request, timeout=10) as response:
        raw = response.read().decode('utf-8')
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        payload = {}
    return {'sent': True, 'event_id': payload.get('id', ''), 'status': 'reported'}

