REPORT_TO = os.environ.get("REPORT_TO", "stakeholders@yourdomain.com")


def build_report_html(narrative_text, rows):
    # Every dynamic value is stringified because floats and None cannot be concatenated into HTML.
    parts = ["<html><body><h1>KPI Report</h1><table>"
    ]
    for row in rows:
        parts.append("<tr><td>" + str(row.get("metric", "")) + "</td><td>" + str(row.get("actual", "")) + "</td><td>" + str(row.get("target", "")) + "</td><td>" + str(row.get("unit", "")) + "</td></tr>")
    parts.append("</table><hr/>")
    # The model separates paragraphs with blank lines, so the split mirrors its conventions.
    for paragraph in narrative_text.split("\n\n"):
        if paragraph.strip():
            parts.append("<p>" + paragraph.strip() + "</p>")
    parts.append("</body></html>")
    return "".join(parts)


def send_report(api_key, sender, recipient, subject, html_body, text_body):
    body = {"from": sender, "to": [recipient], "subject": subject, "html": html_body, "text": text_body}
    data = json.dumps(body).encode("utf-8")
    headers = {"Authorization": "Bearer " + api_key, "Content-Type": "application/json"}
    request = urllib.request.Request(RESEND_URL, data=data, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            status_code = response.status
            payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        # The API returns a JSON error body; reading it once preserves the failure reason for the log.
        return {"id": "", "status": error.code, "error": error.read().decode("utf-8")}
    return {"id": payload.get("id", ""), "status": status_code, "error": ""}


