import json
import os
import time
import urllib.error
import urllib.request


API_BASE = os.environ.get("LAUNCHDARKLY_BASE_URL", "https://app.launchdarkly.com")
MAX_RETRIES = 3


def _request_flag(project_key, flag_key, token):
    url = f"{API_BASE}/api/v2/flags/{project_key}/{flag_key}"
    headers = {"Authorization": token, "Content-Type": "application/json"}
    for attempt in range(MAX_RETRIES):
        request = urllib.request.Request(url, headers=headers, method="GET")
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            if exc.code == 429 and attempt < MAX_RETRIES - 1:
                retry_after = exc.headers.get("Retry-After", "1")
                time.sleep(float(retry_after))
                continue
            raise RuntimeError(f"LaunchDarkly flag request failed: HTTP {exc.code}") from exc
    raise RuntimeError("LaunchDarkly flag request failed after retries")


def extract_rollout_percentage(flag, environment_key):
    environments = flag.get("environments") or {}
    environment = environments.get(environment_key)
    if not isinstance(environment, dict):
        raise ValueError(f"Environment '{environment_key}' not found in flag response")
    fallthrough = environment.get("fallthrough") or {}
    if "percentageRollout" in fallthrough:
        variations = fallthrough["percentageRollout"].get("variations") or []
    else:
        variations = fallthrough.get("variations") or []
    weights = [int(item.get("weight", 0)) for item in variations if isinstance(item, dict)]
    if not weights:
        raise ValueError("Flag response does not contain rollout weights")
    total = sum(weights)
    if total <= 0:
        raise ValueError("Flag rollout weights are not positive")
    return round(total / 1000.0, 2)


def fetch_flag_rollout():
    token = os.environ.get("LAUNCHDARKLY_API_TOKEN", "")
    project_key = os.environ.get("LAUNCHDARKLY_PROJECT_KEY", "")
    flag_key = os.environ.get("LAUNCHDARKLY_FLAG_KEY", "")
    environment_key = os.environ.get("LAUNCHDARKLY_ENVIRONMENT_KEY", "production")
    if not token or not project_key or not flag_key:
        raise RuntimeError("Missing LaunchDarkly credentials or flag identifiers in environment")
    flag = _request_flag(project_key, flag_key, token)
    return extract_rollout_percentage(flag, environment_key)


current_percentage = fetch_flag_rollout()
print(f"Current rollout percentage: {current_percentage}%")

import json
import os
import urllib.error
import urllib.request


GITHUB_API_BASE = "https://api.github.com"


def verify_release(owner: str, repo: str, expected_tag: str, token: str) -> dict:
    if not owner or not repo:
        raise ValueError("GitHub owner and repository must be provided")
    if not expected_tag:
        raise ValueError("Expected release tag must be provided")

    url = f"{GITHUB_API_BASE}/repos/{owner}/{repo}/releases"
    headers = {
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "flowmatrix-feature-flag-rollout",
    }
    if token:
        headers["Authorization"] = f"Bearer {token}"

    request = urllib.request.Request(url, headers=headers, method="GET")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            raise RuntimeError(f"Repository {owner}/{repo} was not found or has no releases") from exc
        raise RuntimeError(f"GitHub API request failed with status {exc.code}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Unable to reach GitHub API: {exc.reason}") from exc

    if not isinstance(payload, list):
        raise RuntimeError("Unexpected GitHub releases response format")

    matching = [release for release in payload if release.get("tag_name") == expected_tag]
    if not matching:
        available = [release.get("tag_name", "") for release in payload]
        return {
            "verified": False,
            "expected_tag": expected_tag,
            "available_tags": available,
        }

    release = matching[0]
    return {
        "verified": True,
        "expected_tag": expected_tag,
        "release_id": release.get("id"),
        "release_name": release.get("name"),
        "published_at": release.get("published_at"),
        "html_url": release.get("html_url"),
    }


def main() -> None:
    owner = os.environ.get("GITHUB_OWNER", "")
    repo = os.environ.get("GITHUB_REPO", "")
    expected_tag = os.environ.get("FEATURE_FLAG_RELEASE_TAG", "")
    token = os.environ.get("GITHUB_TOKEN", "")

    result = verify_release(owner, repo, expected_tag, token)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

