def post_to_slack(channel: str, message: str, token: str) -> str:
    if not channel:
        raise ValueError('SLACK_CHANNEL must be set')
    if not message:
        raise ValueError('message must not be empty')
    if not token:
        raise ValueError('SLACK_BOT_TOKEN must be set')
    payload = json.dumps({'channel': channel, 'text': message}).encode('utf-8')
    request = urllib.request.Request(
        SLACK_POST_MESSAGE_URL,
        data=payload,
        headers={
            'Authorization': f'Bearer {token}',
            'Content-Type': 'application/json; charset=utf-8',
        },
        method='POST',
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response_body = response.read().decode('utf-8')
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode('utf-8', errors='replace')
        raise RuntimeError(f'Slack HTTP error {exc.code}: {error_body}') from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f'Slack connection error: {exc.reason}') from exc
    try:
        result = json.loads(response_body)
    except json.JSONDecodeError as exc:
        raise RuntimeError('Slack returned a non-JSON response') from exc
    if not result.get('ok'):
        error = result.get('error', 'unknown_error')
        raise RuntimeError(f'Slack API rejected the message: {error}')
    timestamp = result.get('ts')
    if not timestamp:
        raise RuntimeError('Slack response did not include a message timestamp')
    return timestamp

def main() -> None:
    token = os.environ.get('SLACK_BOT_TOKEN', '')
    channel = os.environ.get('SLACK_CHANNEL', '')
    percentage_raw = os.environ.get('ROLLOUT_PERCENTAGE', '')
    release_url = os.environ.get('RELEASE_URL', '')
    if not token:
        raise RuntimeError('SLACK_BOT_TOKEN is required')
    if not channel:
        raise RuntimeError('SLACK_CHANNEL is required')
    if not percentage_raw:
        raise RuntimeError('ROLLOUT_PERCENTAGE is required')
    if not release_url:
        raise RuntimeError('RELEASE_URL is required')
    try:
        percentage = int(percentage_raw)
    except ValueError as exc:
        raise RuntimeError('ROLLOUT_PERCENTAGE must be an integer') from exc
    if percentage < 0 or percentage > 100:
        raise RuntimeError('ROLLOUT_PERCENTAGE must be between 0 and 100')
    message = f'Rollout update: feature flag is now at {percentage}%. Release details: {release_url}'
    timestamp = post_to_slack(channel, message, token)
    print(f'Slack announcement sent to {channel} at {timestamp}')

main()

import json
import datetime

def compute_secret_drift(doppler_secrets, github_secrets):
    drift = []
    github_secret_names = {secret['name'] for secret in github_secrets}
    for secret in doppler_secrets:
        last_updated = datetime.datetime.fromisoformat(secret['last_updated'].replace('Z', '+00:00'))
        age_days = (datetime.datetime.now(datetime.timezone.utc) - last_updated).days
        if secret['name'] not in github_secret_names:
            drift.append({'name': secret['name'], 'status': 'missing in GitHub', 'age_days': age_days})
        elif age_days > 30:
            drift.append({'name': secret['name'], 'status': 'rotation overdue', 'age_days': age_days})
    return drift

rotation_drift = compute_secret_drift(secrets, github_secrets)

import json
import os
import re
import urllib.error
import urllib.request

SLACK_POST_MESSAGE_URL = 'https://slack.com/api/chat.postMessage'
CHANNEL_ID_PATTERN = re.compile(r'[CGD][A-Z0-9]{2,}')

def _slack_token() -> str:
    token = os.environ.get('SLACK_BOT_TOKEN', '')
    if not token:
        raise RuntimeError('SLACK_BOT_TOKEN is not set')
    return token

def _security_channel() -> str:
    channel = os.environ.get('SLACK_SECURITY_CHANNEL_ID', '')
    if not channel:
        raise RuntimeError('SLACK_SECURITY_CHANNEL_ID is not set')
    if not CHANNEL_ID_PATTERN.fullmatch(channel):
        raise ValueError('SLACK_SECURITY_CHANNEL_ID is not a valid Slack channel ID')
    return channel

def _format_findings(drift: list[dict]) -> str:
    if drift is None:
        raise ValueError('drift must be a list of findings')
    if not isinstance(drift, list):
        raise ValueError('drift must be a list of findings')
    if not drift:
        return 'Secrets rotation audit: no overdue or missing secrets found.'
    lines = ['Secrets rotation audit findings:']
    for index, item in enumerate(drift, start=1):
        if not isinstance(item, dict):
            raise ValueError(f'Drift item {index} is not an object')
        name = item.get('name')
        status = item.get('status')
        if not name or not status:
            raise ValueError(f'Drift item {index} is missing name or status')
        age = item.get('age_days')
        if age is None:
            lines.append(f'- {name}: {status}')
        else:
            lines.append(f'- {name}: {status} (age: {age} days)')
    return chr(10).join(lines)

def send_alert_to_slack(drift: list[dict]) -> dict:
    token = _slack_token()
    channel = _security_channel()
    text = _format_findings(drift)
    payload = {'channel': channel, 'text': text}
    data = json.dumps(payload).encode('utf-8')
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json; charset=utf-8',
    }
    request = urllib.request.Request(
        SLACK_POST_MESSAGE_URL,
        data=data,
        headers=headers,
        method='POST',
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            body = response.read().decode('utf-8', errors='replace')
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode('utf-8', errors='replace')
        raise RuntimeError(f'Slack HTTP error {exc.code}: {detail}') from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f'Slack request failed: {exc.reason}') from exc
    except TimeoutError as exc:
        raise RuntimeError('Slack request timed out') from exc
    except OSError as exc:
        raise RuntimeError(f'Slack request failed: {exc}') from exc
    try:
        result = json.loads(body)
    except json.JSONDecodeError as exc:
        raise RuntimeError('Slack returned invalid JSON') from exc
    if not isinstance(result, dict):
        raise RuntimeError('Slack returned a non-object JSON response')
    if not result.get('ok'):
        error = result.get('error')
        raise RuntimeError(f'Slack API error: {error}')
    return result

# rotation_drift is produced by the previous workflow step.
send_alert_to_slack(rotation_drift)

