import os
import json
import urllib.request
import urllib.error
import urllib.parse

NOTION_API_BASE = "https://api.notion.com/v1/"
NOTION_TOKEN = os.environ.get("NOTION_TOKEN")
TARGET_PAGE_ID = os.environ.get("NOTION_PAGE_ID")
NOTION_VERSION = "2022-06-28"

notion_updates = []


def update_notion_roadmap(projects, milestones):
    """Updates Notion roadmap sections based on Linear progress."""
    projects = projects or []
    milestones = milestones or {}
    if projects and (not NOTION_TOKEN or not TARGET_PAGE_ID):
        raise RuntimeError("NOTION_TOKEN and NOTION_PAGE_ID must be set")

    for project in projects:
        project_name = project.get("name", "Unknown Project")
        project_id = project.get("id")
        progress = float(project.get("progress", 0.0) or 0.0)
        milestone_info = milestones.get(project_id, {})
        if not isinstance(milestone_info, dict):
            milestone_info = {}

        if progress >= 0.9:
            status_text = "Complete"
        elif progress >= 0.5:
            status_text = "In Progress"
        else:
            status_text = "Planning"

        block_content = {
            "object": "block",
            "type": "paragraph",
            "paragraph": {
                "rich_text": [
                    {
                        "type": "text",
                        "text": {
                            "content": (
                                f"Project: {project_name} | Status: {status_text} "
                                f"({progress * 100:.0f}%) | Milestone: "
                                f"{milestone_info.get('milestone_name', 'N/A')}"
                            )
                        }
                    }
                ]
            }
        }

        payload = json.dumps({"children": [block_content]})
        encoded_page_id = urllib.parse.quote(str(TARGET_PAGE_ID), safe="")
        url = f"{NOTION_API_BASE}blocks/{encoded_page_id}/children"

        headers = {
            "Authorization": f"Bearer {NOTION_TOKEN}",
            "Content-Type": "application/json",
            "Notion-Version": NOTION_VERSION
        }

        try:
            req = urllib.request.Request(url, data=payload.encode("utf-8"), headers=headers, method="POST")
            with urllib.request.urlopen(req) as response:
                response_status = response.status
                if response_status in [200, 201, 204]:
                    notion_updates.append({
                        "project": project_name,
                        "status": status_text,
                        "milestone": milestone_info.get("milestone_name", "N/A")
                    })
                    print(f"Successfully updated Notion for {project_name}")
                else:
                    notion_updates.append({
                        "project": project_name,
                        "status": "Failed",
                        "error": f"HTTP {response_status}"
                    })
        except urllib.error.HTTPError as e:
            notion_updates.append({
                "project": project_name,
                "status": "Failed",
                "error": f"HTTP {e.code}"
            })
        except Exception as e:
            notion_updates.append({
                "project": project_name,
                "status": "Failed",
                "error": str(e)
            })

    return notion_updates


linear_projects = globals().get("linear_projects", []) or []
matched_milestones = globals().get("matched_milestones", {}) or {}
notion_updates = update_notion_roadmap(linear_projects, matched_milestones)

import json
import os
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime

API_BASE = 'https://api.github.com'
PER_PAGE = 100
MAX_PAGES = 50


def _parse_timestamp(value):
    # Normalise GitHub ISO-8601 timestamps into aware datetimes.
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError:
        return None


def _check_rate_limit(headers):
    # Fail fast instead of hammering the API when the quota is gone.
    if not headers:
        return
    remaining = headers.get('X-RateLimit-Remaining')
    if remaining is not None and remaining.isdigit() and int(remaining) <= 0:
        reset = headers.get('X-RateLimit-Reset', 'unknown')
        raise RuntimeError(f'GitHub rate limit exhausted, resets at epoch {reset}')


def _next_page_url(headers):
    # Parse the Link header to follow GitHub pagination.
    link_header = headers.get('Link', '') if headers else ''
    for part in link_header.split(','):
        segments = part.split(';')
        if len(segments) < 2:
            continue
        target = segments[0].strip().strip('<>')
        if any('next' in param for param in segments[1:]):
            return target
    return None


def _get_json(url, token, allow_not_found=False):
    # Perform an authenticated GitHub GET request and decode JSON.
    request_headers = {
        'Authorization': f'Bearer {token}',
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        'User-Agent': 'flowmatrix-release-notes-generator',
    }
    request = urllib.request.Request(url, headers=request_headers, method='GET')
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            body = response.read().decode('utf-8')
            _check_rate_limit(response.headers)
            payload = json.loads(body) if body.strip() else None
            return payload, response.headers
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode('utf-8', errors='replace')
        if exc.code in (403, 429):
            _check_rate_limit(exc.headers)
        if exc.code == 404 and allow_not_found:
            return None, exc.headers
        raise RuntimeError(f'GitHub API error {exc.code} for {url}: {detail}') from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f'Network error calling GitHub API: {exc.reason}') from exc


def fetch_last_release_time(owner, repo, token):
    # Use the published date of the latest release as the changelog cutoff.
    url = f'{API_BASE}/repos/{urllib.parse.quote(owner)}/{urllib.parse.quote(repo)}/releases/latest'
    payload, _ = _get_json(url, token, allow_not_found=True)
    if not isinstance(payload, dict):
        return None
    return _parse_timestamp(payload.get('published_at') or payload.get('created_at'))


def fetch_merged_pull_requests():
    token = os.environ.get('GITHUB_TOKEN', '')
    owner = os.environ.get('GITHUB_OWNER', '')
    repo = os.environ.get('GITHUB_REPO', '')
    if not token or not owner or not repo:
        raise RuntimeError('GITHUB_TOKEN, GITHUB_OWNER and GITHUB_REPO environment variables are required')

    since = fetch_last_release_time(owner, repo, token)
    query = urllib.parse.urlencode({
        'state': 'closed',
        'sort': 'updated',
        'direction': 'desc',
        'per_page': PER_PAGE,
    })
    url = f'{API_BASE}/repos/{urllib.parse.quote(owner)}/{urllib.parse.quote(repo)}/pulls?{query}'

    merged = []
    seen = set()
    page = 0
    while url and page < MAX_PAGES:
        page += 1
        payload, headers = _get_json(url, token)
        if not isinstance(payload, list):
            raise RuntimeError('Unexpected GitHub response while listing pull requests')
        if not payload:
            break
        for item in payload:
            if not isinstance(item, dict) or item.get('merged_at') is None:
                continue
            number = item.get('number')
            if number in seen:
                continue
            merged_at = _parse_timestamp(item.get('merged_at'))
            if since is not None and (merged_at is None or merged_at <= since):
                continue
            seen.add(number)
            merged.append({
                'number': number,
                'title': item.get('title', ''),
                'author': (item.get('user') or {}).get('login', ''),
                'merged_at': item.get('merged_at'),
                'url': item.get('html_url', ''),
                'labels': [label.get('name') for label in item.get('labels', []) if isinstance(label, dict)],
            })
        if since is not None:
            # Results are sorted by updated_at descending, so we can stop once the page is older than the cutoff.
            updated_times = [
                stamp for stamp in (_parse_timestamp(pr.get('updated_at')) for pr in payload if isinstance(pr, dict))
                if stamp is not None
            ]
            if updated_times and max(updated_times) <= since:
                break
        url = _next_page_url(headers)

    merged.sort(key=lambda pr: pr['merged_at'] or '', reverse=True)
    return merged


merged_prs = fetch_merged_pull_requests()
print(f'Collected {len(merged_prs)} merged pull requests since the last release')
print(json.dumps(merged_prs, indent=2))

import json
import os
import time
import urllib.error
import urllib.request

OPENAI_URL = "https://api.openai.com/v1/chat/completions"
MODEL = "gpt-4o"
REQUEST_TIMEOUT = 60
MAX_ATTEMPTS = 4
RETRY_STATUS = {408, 409, 429, 500, 502, 503, 504}

SYSTEM_PROMPT = (
    "You are a release manager writing a changelog. Group the merged pull requests "
    "into sections: Features, Fixes, Performance, Documentation, Chores. "
    "Write concise bullet points, keep the PR links, and omit empty sections."
)


def _validate_prs(merged_prs):
    if not isinstance(merged_prs, list) or not merged_prs:
        raise ValueError("merged_prs must be a non-empty list of pull requests")
    cleaned = []
    for index, pr in enumerate(merged_prs):
        if not isinstance(pr, dict):
            raise ValueError(f"pull request at index {index} is not an object")
        title = str(pr.get("title") or "").strip()
        url = str(pr.get("url") or "").strip()
        if not title or not url:
            raise ValueError(f"pull request at index {index} is missing title or url")
        labels = pr.get("labels") or []
        if not isinstance(labels, list):
            labels = []
        cleaned.append({"title": title, "url": url, "labels": [str(label) for label in labels]})
    return cleaned


def _build_payload(merged_prs):
    user_content = json.dumps({"merged_pull_requests": merged_prs}, ensure_ascii=False, indent=2)
    return {
        "model": MODEL,
        "temperature": 0.2,
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": user_content},
        ],
    }


def _post_json(url, payload, api_key):
    body = json.dumps(payload).encode("utf-8")
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
    last_error = None
    for attempt in range(1, MAX_ATTEMPTS + 1):
        request = urllib.request.Request(url, data=body, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT) as response:
                raw = response.read().decode("utf-8")
            return json.loads(raw)
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:500]
            last_error = RuntimeError(f"OpenAI HTTP {exc.code}: {detail}")
            if exc.code not in RETRY_STATUS or attempt == MAX_ATTEMPTS:
                raise last_error from exc
        except (urllib.error.URLError, TimeoutError) as exc:
            last_error = RuntimeError(f"OpenAI request failed: {exc}")
            if attempt == MAX_ATTEMPTS:
                raise last_error from exc
        time.sleep(min(2 ** attempt, 30))
    raise last_error or RuntimeError("OpenAI request failed without a captured error")


def _extract_content(response):
    choices = response.get("choices") if isinstance(response, dict) else None
    if not choices:
        raise RuntimeError("OpenAI response contained no choices")
    message = choices[0].get("message") or {}
    content = (message.get("content") or "").strip()
    if not content:
        raise RuntimeError("OpenAI response contained an empty changelog")
    return content


def generate_changelog(merged_prs, api_key=None):
    key = api_key or os.environ.get("OPENAI_API_KEY", "")
    if not key:
        raise RuntimeError("OPENAI_API_KEY is not set")
    cleaned = _validate_prs(merged_prs)
    response = _post_json(OPENAI_URL, _build_payload(cleaned), key)
    return _extract_content(response)


def main():
    raw = os.environ.get("MERGED_PRS_JSON", "")
    if not raw:
        raise SystemExit("MERGED_PRS_JSON is not set; provide the merged pull requests as JSON")
    merged_prs = json.loads(raw)
    changelog = generate_changelog(merged_prs)
    print(changelog)


if __name__ == "__main__":
    main()

import json
import os
import time
import urllib.error
import urllib.request


def create_github_release(owner: str, repo: str, token: str, tag_name: str, release_name: str, changelog: str, max_retries: int = 3) -> dict:
    """Create a GitHub release and return the API response payload."""
    if not owner or not repo:
        raise ValueError("GITHUB_OWNER and GITHUB_REPO must be set")
    if not token:
        raise ValueError("GITHUB_TOKEN must be set")
    if not tag_name:
        raise ValueError("RELEASE_TAG must be set")
    if not changelog.strip():
        raise ValueError("CHANGELOG must contain the generated release notes")

    url = f"https://api.github.com/repos/{owner}/{repo}/releases"
    payload = {
        "tag_name": tag_name,
        "name": release_name or tag_name,
        "body": changelog,
        "draft": False,
        "prerelease": False,
    }
    data = json.dumps(payload).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github+json",
        "Content-Type": "application/json",
        "X-GitHub-Api-Version": "2022-11-28",
    }

    for attempt in range(1, max_retries + 1):
        request = urllib.request.Request(url, data=data, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                body = response.read().decode("utf-8")
                return json.loads(body)
        except urllib.error.HTTPError as exc:
            error_body = exc.read().decode("utf-8", errors="replace")
            remaining = exc.headers.get("X-RateLimit-Remaining", "")
            reset = exc.headers.get("X-RateLimit-Reset", "")
            if exc.code == 403 and remaining == "0" and reset.isdigit():
                wait_seconds = max(1, int(reset) - int(time.time()) + 1)
                if attempt == max_retries:
                    raise RuntimeError(f"GitHub rate limit exceeded; retry after {wait_seconds}s: {error_body}") from exc
                time.sleep(min(wait_seconds, 60))
                continue
            if exc.code in (500, 502, 503, 504) and attempt < max_retries:
                time.sleep(2 ** attempt)
                continue
            raise RuntimeError(f"GitHub release creation failed ({exc.code}): {error_body}") from exc
        except urllib.error.URLError as exc:
            if attempt == max_retries:
                raise RuntimeError(f"Network error while creating GitHub release: {exc}") from exc
            time.sleep(2 ** attempt)

    raise RuntimeError("GitHub release creation exhausted retries")


def main() -> None:
    owner = os.environ.get("GITHUB_OWNER", "").strip()
    repo = os.environ.get("GITHUB_REPO", "").strip()
    token = os.environ.get("GITHUB_TOKEN", "").strip()
    tag_name = os.environ.get("RELEASE_TAG", "").strip()
    release_name = os.environ.get("RELEASE_NAME", "").strip()
    changelog = os.environ.get("CHANGELOG", "").strip()

    result = create_github_release(owner, repo, token, tag_name, release_name, changelog)
    print(json.dumps({"id": result.get("id"), "url": result.get("html_url"), "created_at": result.get("created_at")}, indent=2))


if __name__ == "__main__":
    main()

import json
import os
import re
import time
import urllib.error
import urllib.request

RESEND_ENDPOINT = 'https://api.resend.com/emails'
EMAIL_PATTERN = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')
MAX_BATCH_SIZE = 50
MAX_RETRIES = 5


def _valid_email(value):
    if not isinstance(value, str):
        return False
    return bool(EMAIL_PATTERN.match(value.strip()))


def _post_json(url, payload, headers, timeout=30):
    body = json.dumps(payload).encode('utf-8')
    request = urllib.request.Request(url, data=body, headers=headers, method='POST')
    with urllib.request.urlopen(request, timeout=timeout) as response:
        raw = response.read().decode('utf-8')
    return json.loads(raw) if raw else {}


def send_changelog(changelog, subscribers):
    api_key = os.environ.get('RESEND_API_KEY', '')
    from_email = os.environ.get('RESEND_FROM_EMAIL', '')
    if not api_key:
        raise RuntimeError('RESEND_API_KEY is not configured')
    if not from_email:
        raise RuntimeError('RESEND_FROM_EMAIL is not configured')
    if not isinstance(changelog, str) or not changelog.strip():
        raise ValueError('changelog must be a non-empty string')
    if not isinstance(subscribers, (list, tuple, set)):
        raise TypeError('subscribers must be a list, tuple, or set')
    recipients = []
    seen = set()
    for item in subscribers:
        email = str(item).strip()
        if _valid_email(email) and email.lower() not in seen:
            seen.add(email.lower())
            recipients.append(email)
    if not recipients:
        raise ValueError('no valid subscriber email addresses were provided')
    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json',
    }
    results = []
    for start in range(0, len(recipients), MAX_BATCH_SIZE):
        batch = recipients[start:start + MAX_BATCH_SIZE]
        payload = {
            'from': from_email,
            'to': batch,
            'subject': 'New Release Available',
            'text': changelog,
        }
        attempt = 0
        while True:
            try:
                response = _post_json(RESEND_ENDPOINT, payload, headers)
                results.append({'recipients': batch, 'response': response})
                break
            except urllib.error.HTTPError as exc:
                if exc.code == 429 and attempt < MAX_RETRIES:
                    retry_after = exc.headers.get('Retry-After', '') if exc.headers else ''
                    try:
                        delay = float(retry_after)
                    except ValueError:
                        delay = 2 ** attempt
                    time.sleep(min(delay, 60))
                    attempt += 1
                    continue
                detail = exc.read().decode('utf-8', errors='replace')
                raise RuntimeError(f'Resend API error {exc.code}: {detail}') from exc
            except urllib.error.URLError as exc:
                if attempt < MAX_RETRIES:
                    time.sleep(min(2 ** attempt, 60))
                    attempt += 1
                    continue
                raise RuntimeError(f'Resend API connection error: {exc.reason}') from exc
    return results


def main():
    changelog = os.environ.get('CHANGELOG_TEXT', '')
    raw_subscribers = os.environ.get('SUBSCRIBER_EMAILS', '')
    subscribers = [part.strip() for part in raw_subscribers.split(',') if part.strip()]
