import json
import os
import sys
import urllib.error
import urllib.request

NOTION_API_BASE = "https://api.notion.com/v1"
NOTION_VERSION = "2022-06-28"
PAGE_SIZE = 100
REQUEST_TIMEOUT = 30


def _query_database(token, database_id, payload):
    """POST a query to a Notion database and return the decoded JSON body."""
    url = f"{NOTION_API_BASE}/databases/{database_id}/query"
    body = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=body,
        method="POST",
        headers={
            "Authorization": f"Bearer {token}",
            "Notion-Version": NOTION_VERSION,
            "Content-Type": "application/json",
        },
    )
    with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT) as response:
        return json.loads(response.read().decode("utf-8"))


def _build_filter(status_property, pending_status, kind):
    """Build a Notion filter for the given property type, or None for no filter."""
    if not status_property or not pending_status or kind is None:
        return None
    return {"property": status_property, kind: {"equals": pending_status}}


def _extract_title(properties):
    """Return the plain text of the first title property found."""
    for prop in properties.values():
        if prop.get("type") == "title":
            fragments = prop.get("title") or []
            return "".join(fragment.get("plain_text", "") for fragment in fragments).strip()
    return ""


def _extract_status(properties, status_property):
    """Return the status or select value name for the configured property."""
    prop = properties.get(status_property) or {}
    prop_type = prop.get("type")
    if prop_type == "status":
        return (prop.get("status") or {}).get("name", "")
    if prop_type == "select":
        return (prop.get("select") or {}).get("name", "")
    return ""


def _is_pending(properties, status_property, pending_status):
    """Client-side check used when the server-side filter is unavailable."""
    if status_property not in properties:
        return True
    return _extract_status(properties, status_property).casefold() == pending_status.casefold()


def fetch_briefs():
    token = os.environ.get("NOTION_INTEGRATION_TOKEN", "")
    database_id = os.environ.get("NOTION_DATABASE_ID", "")
    status_property = os.environ.get("NOTION_STATUS_PROPERTY", "Status")
    pending_status = os.environ.get("NOTION_PENDING_STATUS", "Needs Draft")
    if not token or not database_id:
        raise RuntimeError("NOTION_INTEGRATION_TOKEN and NOTION_DATABASE_ID must be set")

    briefs = []
    cursor = None
    filter_kind = "status"
    while True:
        payload = {"page_size": PAGE_SIZE}
        notion_filter = _build_filter(status_property, pending_status, filter_kind)
        if notion_filter:
            payload["filter"] = notion_filter
        if cursor:
            payload["start_cursor"] = cursor
        try:
            data = _query_database(token, database_id, payload)
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            if exc.code == 400 and filter_kind is not None:
                # Property type mismatch: retry with a select filter, then unfiltered.
                filter_kind = "select" if filter_kind == "status" else None
                continue
            raise RuntimeError(f"Notion query failed ({exc.code}): {detail}") from exc
        except urllib.error.URLError as exc:
            raise RuntimeError(f"Notion query network error: {exc.reason}") from exc

        for item in data.get("results", []):
            properties = item.get("properties", {})
            if filter_kind is None and not _is_pending(properties, status_property, pending_status):
                continue
            briefs.append(
                {
                    "id": item.get("id", ""),
                    "title": _extract_title(properties),
                    "status": _extract_status(properties, status_property),
                    "url": item.get("url", ""),
                }
            )

        if not data.get("has_more"):
            break
        cursor = data.get("next_cursor")
        if not cursor:
            break

    return briefs


if __name__ == "__main__":
    try:
        briefs = fetch_briefs()
    except RuntimeError as exc:
        print(f"Failed to fetch briefs: {exc}", file=sys.stderr)
        raise SystemExit(1)
    print(json.dumps(briefs, indent=2))

import json
import os
import time
import urllib.error
import urllib.request


def create_review_page(article, max_retries=3, retry_delay=2.0):
    token = os.environ.get("NOTION_INTEGRATION_TOKEN", "")
    database_id = os.environ.get("NOTION_REVIEW_DATABASE_ID", "")
    if not token:
        raise RuntimeError("NOTION_INTEGRATION_TOKEN environment variable is not set")
    if not database_id:
        raise RuntimeError("NOTION_REVIEW_DATABASE_ID environment variable is not set")
    if not isinstance(article, str) or not article.strip():
        raise ValueError("article must be a non-empty string")

    notion_url = "https://api.notion.com/v1/pages"
    headers = {
        "Authorization": f"Bearer {token}",
        "Notion-Version": "2022-06-28",
        "Content-Type": "application/json",
    }
    # Notion limits rich_text content to 2000 characters per block, so chunk the article.
    chunks = [article[i:i + 2000] for i in range(0, len(article), 2000)]
    payload = {
        "parent": {"database_id": database_id},
        "properties": {
            "Status": {"select": {"name": "Review"}},
            "Content": {
                "rich_text": [{"type": "text", "text": {"content": chunk}} for chunk in chunks]
            },
        },
    }
    body = json.dumps(payload).encode("utf-8")

    last_error = None
    for attempt in range(1, max_retries + 1):
        request = urllib.request.Request(notion_url, data=body, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                raw = response.read().decode("utf-8")
                return json.loads(raw)
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            last_error = RuntimeError(
                f"Notion API returned HTTP {exc.code} on attempt {attempt}: {detail}"
            )
            if exc.code in (400, 401, 403, 404):
                raise last_error from exc
        except urllib.error.URLError as exc:
            last_error = RuntimeError(
                f"Notion API connection failed on attempt {attempt}: {exc.reason}"
            )
        if attempt < max_retries:
            time.sleep(retry_delay * attempt)
    raise last_error if last_error else RuntimeError("Notion page creation failed")


review_page = create_review_page(article)
print(json.dumps({"page_id": review_page.get("id"), "url": review_page.get("url")}))

import json
import os
import time
import urllib.error
import urllib.request
from typing import Any, Iterable

RESEND_ENDPOINT = 'https://api.resend.com/emails'
MAX_RETRIES = 3
RETRY_BASE_SECONDS = 1.0
RECIPIENT_BATCH_SIZE = 50

def _is_valid_email(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    email = value.strip()
    if email.count('@') != 1:
        return False
    local, domain = email.split('@', 1)
    return bool(local and domain and '.' in domain and ' ' not in email)

def _normalise_recipients(reviewers: Iterable[Any]) -> list[str]:
    seen: set[str] = set()
    recipients: list[str] = []
    for reviewer in reviewers or []:
        if isinstance(reviewer, dict):
            raw_email = reviewer.get('email') or reviewer.get('address')
        else:
            raw_email = reviewer
        if isinstance(raw_email, str):
            email = raw_email.strip().lower()
            if _is_valid_email(email) and email not in seen:
                seen.add(email)
                recipients.append(email)
    return recipients

def _post_resend(payload: dict[str, Any], api_key: str) -> dict[str, Any]:
    data = json.dumps(payload).encode('utf-8')
    headers = {'Authorization': f'Bearer {api_key}', 'Content-Type': 'application/json'}
    last_error: Exception | None = None
    for attempt in range(MAX_RETRIES):
        request = urllib.request.Request(RESEND_ENDPOINT, data=data, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                body = response.read().decode('utf-8')
                return json.loads(body) if body else {}
        except urllib.error.HTTPError as exc:
            error_body = exc.read().decode('utf-8', errors='replace')
            if exc.code == 429 or 500 <= exc.code < 600:
                last_error = RuntimeError(f'Resend transient HTTP {exc.code}: {error_body}')
                time.sleep(RETRY_BASE_SECONDS * (2 ** attempt))
                continue
            raise RuntimeError(f'Resend request failed HTTP {exc.code}: {error_body}') from exc
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
            last_error = exc
            time.sleep(RETRY_BASE_SECONDS * (2 ** attempt))
    raise RuntimeError('Resend request failed after retries') from last_error

def notify_reviewers(review_page_id: str, reviewers: Iterable[Any], article_title: str = '') -> list[dict[str, Any]]:
    api_key = os.environ.get('RESEND_API_KEY', '')
    if not api_key:
        raise RuntimeError('RESEND_API_KEY is not configured')
    if not isinstance(review_page_id, str) or not review_page_id.strip():
        raise ValueError('A valid Notion review page id is required')
    recipients = _normalise_recipients(reviewers)
    if not recipients:
        return []
    from_email = os.environ.get('RESEND_FROM_EMAIL', '')
    if not from_email:
        raise RuntimeError('RESEND_FROM_EMAIL is not configured')
    safe_title = article_title.strip() if isinstance(article_title, str) else ''
    subject = f'Review requested: {safe_title}' if safe_title else 'Review requested for new article draft'
    page_url = f'https://www.notion.so/{review_page_id.strip()}'
    results: list[dict[str, Any]] = []
    for start in range(0, len(recipients), RECIPIENT_BATCH_SIZE):
        batch = recipients[start:start + RECIPIENT_BATCH_SIZE]
        html = f'<p>A new article draft is ready for editorial review.</p><p><a href={page_url}>Open the Notion review page</a></p>'
        payload = {'from': from_email, 'to': batch, 'subject': subject, 'html': html}
        results.append(_post_resend(payload, api_key))
    return results

review_page_id = os.environ.get('NOTION_REVIEW_PAGE_ID', '')
reviewers_json = os.environ.get('REVIEWERS_JSON', '')
article_title = os.environ.get('ARTICLE_TITLE', '')
if not reviewers_json:
    raise RuntimeError('REVIEWERS_JSON is not configured')
try:
    reviewers = json.loads(reviewers_json)
except json.JSONDecodeError as exc:
    raise RuntimeError('REVIEWERS_JSON must be valid JSON') from exc
if not isinstance(reviewers, list):
    raise RuntimeError('REVIEWERS_JSON must encode a list')
email_response = notify_reviewers(review_page_id, reviewers, article_title)

import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request

ALGOLIA_HOST_TEMPLATE = 'https://{application_id}.algolia.net/1/indexes/{index_name}/query'
HITS_PER_PAGE = 1000
MAX_RETRIES = 3
RETRY_STATUSES = {429, 500, 502, 503, 504}


def _post_algolia_json(url: str, headers: dict, body: dict) -> dict:
    encoded_body = json.dumps(body).encode('utf-8')
    last_error = None
    for attempt in range(MAX_RETRIES):
        request = urllib.request.Request(url, data=encoded_body, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                raw = response.read().decode('utf-8')
                payload = json.loads(raw)
                if not isinstance(payload, dict):
                    raise RuntimeError('Algolia returned an unexpected JSON payload')
                return payload
        except urllib.error.HTTPError as exc:
            last_error = exc
            if exc.code not in RETRY_STATUSES or attempt == MAX_RETRIES - 1:
                raise RuntimeError(f'Algolia request failed with HTTP {exc.code}') from exc
            time.sleep(2 ** attempt)
        except urllib.error.URLError as exc:
            last_error = exc
            if attempt == MAX_RETRIES - 1:
                raise RuntimeError('Algolia request failed due to a network error') from exc
            time.sleep(2 ** attempt)
        except json.JSONDecodeError as exc:
            raise RuntimeError('Algolia returned a non-JSON response') from exc
    raise RuntimeError('Algolia request failed after retries') from last_error


def fetch_indexed_pages() -> list[dict]:
    application_id = os.environ.get('ALGOLIA_APPLICATION_ID', '')
    api_key = os.environ.get('ALGOLIA_API_KEY', '')
    index_name = os.environ.get('ALGOLIA_INDEX_NAME', '')
    if not application_id or not api_key or not index_name:
        raise RuntimeError('ALGOLIA_APPLICATION_ID, ALGOLIA_API_KEY, and ALGOLIA_INDEX_NAME must be set')

    encoded_index = urllib.parse.quote(index_name, safe='')
    url = ALGOLIA_HOST_TEMPLATE.format(application_id=application_id, index_name=encoded_index)
    headers = {
        'X-Algolia-API-Key': api_key,
        'X-Algolia-Application-Id': application_id,
        'Content-Type': 'application/json',
    }

    records: list[dict] = []
    page = 0
    while True:
        params = urllib.parse.urlencode({
            'hitsPerPage': HITS_PER_PAGE,
            'page': page,
            'attributesToRetrieve': 'title,slug,keywords',
        })
        payload = _post_algolia_json(url, headers, {'params': params})
        hits = payload.get('hits', [])
        if not isinstance(hits, list):
            raise RuntimeError('Algolia response field hits is not a list')
        if page == 0 and not hits:
            raise RuntimeError('Algolia returned no indexed pages')
        for hit in hits:
            if isinstance(hit, dict):
                records.append({
                    'title': hit.get('title'),
                    'slug': hit.get('slug'),
                    'keywords': hit.get('keywords'),
                })
        nb_pages = payload.get('nbPages', 0)
        try:
            nb_pages = int(nb_pages)
        except (TypeError, ValueError):
            nb_pages = 0
        page += 1
        if not hits or (nb_pages > 0 and page >= nb_pages):
            break
    return records


indexed_pages = fetch_indexed_pages()
print(f'Exported {len(indexed_pages)} indexed pages from Algolia.')

import os
import re
from collections import defaultdict

ALGOLIA_API_KEY = os.environ.get('ALGOLIA_API_KEY', '')
GOOGLE_SHEETS_API_KEY = os.environ.get('GOOGLE_SHEETS_API_KEY', '')
OPENAI_API_KEY = os.environ.get('OPENAI_API_KEY', '')

_PAGE_KEYWORD_SPLIT_RE = re.compile(r'[,;|]')

def _normalize_keyword(value: object) -> str:
    if value is None:
        return ''
    text = str(value).strip()
    if not text:
        return ''
    text = ' '.join(text.split())
    return text.casefold()

def _target_keyword_value(item: object) -> str:
    if isinstance(item, str):
        return item
    if isinstance(item, (list, tuple)) and item:
        return str(item[0])
    if isinstance(item, dict):
        for key in ('keyword', 'term', 'query'):
            if key in item:
                return str(item[key])
    return str(item)

def _page_keyword_values(raw: object) -> list[str]:
    if raw is None:
        return []
    if isinstance(raw, str):
        return [part for part in _PAGE_KEYWORD_SPLIT_RE.split(raw) if part.strip()]
    if isinstance(raw, (list, tuple, set)):
        values = []
        for item in raw:
            if isinstance(item, str):
                values.append(item)
            elif isinstance(item, (list, tuple)) and item:
                values.append(str(item[0]))
            elif isinstance(item, dict):
                for key in ('keyword', 'term', 'query'):
                    if key in item:
                        values.append(str(item[key]))
                        break
        return values
    return [str(raw)]

def score_keyword_coverage(indexed_pages: list[dict], target_keywords: list[object]) -> dict:
    target_terms: list[str] = []
    seen_targets: set[str] = set()
    for item in target_keywords or []:
        normalized = _normalize_keyword(_target_keyword_value(item))
        if normalized and normalized not in seen_targets:
            seen_targets.add(normalized)
            target_terms.append(normalized)

    keyword_pages: dict[str, set[int]] = defaultdict(set)
    for page_index, page in enumerate(indexed_pages or []):
        if not isinstance(page, dict):
            continue
        raw_keywords = page.get('keywords')
        if raw_keywords is None:
            raw_keywords = page.get('keyword')
        for raw_keyword in _page_keyword_values(raw_keywords):
            normalized = _normalize_keyword(raw_keyword)
            if normalized:
                keyword_pages[normalized].add(page_index)

    indexed_terms = set(keyword_pages)
    covered = [term for term in target_terms if term in indexed_terms]
    missing = [term for term in target_terms if term not in indexed_terms]
    cannibalized = [
        term for term in target_terms
        if len(keyword_pages.get(term, set())) > 1
    ]
    coverage_score = round((len(covered) / len(target_terms)) * 100.0, 2) if target_terms else 0.0

    return {
        'coverage_score': coverage_score,
        'covered_keywords': covered,
        'missing_keywords': missing,
        'cannibalized_keywords': cannibalized,
        'indexed_keyword_count': len(indexed_terms),
        'target_keyword_count': len(target_terms),
    }

coverage_result = score_keyword_coverage(indexed_pages, target_keywords)

