import json
import os
import urllib.error
import urllib.request

def _required_env(name: str) -> str:
    value = os.environ.get(name, '').strip()
    if not value:
        raise RuntimeError(f'Missing required environment variable: {name}')
    return value

def _parse_recipients(raw: str) -> list[str]:
    recipients = [item.strip() for item in raw.split(',') if item.strip()]
    if not recipients:
        raise ValueError('NEWSLETTER_RECIPIENTS must contain at least one address')
    return recipients

def send_newsletter(html_content: str, recipients: list[str], subject: str, from_address: str, api_key: str, reply_to: str = '') -> dict:
    if not html_content or not html_content.strip():
        raise ValueError('Newsletter HTML content is empty')
    if not recipients:
        raise ValueError('At least one recipient is required')
    if not subject.strip():
        raise ValueError('Newsletter subject is empty')
    if not from_address.strip():
        raise ValueError('Newsletter sender address is empty')
    if not api_key.strip():
        raise ValueError('Resend API key is empty')

    payload = {
        'from': from_address,
        'to': recipients,
        'subject': subject,
        'html': html_content,
    }
    if reply_to:
        payload['reply_to'] = reply_to

    request_data = json.dumps(payload, ensure_ascii=False).encode('utf-8')
    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
    }
    request = urllib.request.Request(
        'https://api.resend.com/emails',
        data=request_data,
        headers=headers,
        method='POST',
    )

    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response_status = response.status
            response_body = response.read().decode('utf-8')
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode('utf-8', errors='replace')
        raise RuntimeError(f'Resend API HTTP {exc.code}: {error_body}') from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f'Resend API connection failed: {exc.reason}') from exc

    if not response_body.strip():
        raise RuntimeError('Resend API returned an empty response body')
    try:
        result = json.loads(response_body)
    except json.JSONDecodeError as exc:
        raise RuntimeError('Resend API returned invalid JSON') from exc

    broadcast_id = result.get('id')
    if not broadcast_id:
        raise RuntimeError('Resend API response did not include an id')

    return {
        'broadcast_id': broadcast_id,
        'status_code': response_status,
        'response': result,
    }

def main() -> dict:
    html_content = _required_env('NEWSLETTER_HTML')
    recipients = _parse_recipients(_required_env('NEWSLETTER_RECIPIENTS'))
    subject = _required_env('NEWSLETTER_SUBJECT')
    from_address = _required_env('NEWSLETTER_FROM')
    api_key = os.environ.get('RESEND_API_KEY', '').strip()
    if not api_key:
        raise RuntimeError('Missing required environment variable: RESEND_API_KEY')
    reply_to = os.environ.get('NEWSLETTER_REPLY_TO', '').strip()

    send_result = send_newsletter(
        html_content=html_content,
        recipients=recipients,
        subject=subject,
        from_address=from_address,
        api_key=api_key,
        reply_to=reply_to,
    )
    print(json.dumps(send_result, ensure_ascii=False))
    return send_result

send_result = main()
broadcast_id = send_result['broadcast_id']

import json
import urllib.request
import os

def extract_decisions(transcription):
    url = 'https://api.openai.com/v1/chat/completions'
    headers = {
