import json
import os
import time
import urllib.error
import urllib.request

NOTION_API_BASE = 'https://api.notion.com/v1'
NOTION_VERSION = '2022-06-28'
DONE_STATUS_NAMES = {'done', 'complete', 'completed', 'closed', 'finished'}
DONE_PROPERTY_NAMES = {'done', 'completed', 'complete', 'is done', 'is completed'}

def _notion_request(url, token, payload=None, max_retries=5):
    headers = {
        'Authorization': f'Bearer {token}',
        'Notion-Version': NOTION_VERSION,
        'Content-Type': 'application/json',
    }
    data = None
    if payload is not None:
        data = json.dumps(payload).encode('utf-8')
    method = 'POST' if payload is not None else 'GET'
    for attempt in range(max_retries):
        request = urllib.request.Request(url, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                body = response.read().decode('utf-8')
                return json.loads(body)
        except urllib.error.HTTPError as exc:
            if exc.code == 429 or 500 <= exc.code < 600:
                retry_after = exc.headers.get('Retry-After')
                delay = float(retry_after) if retry_after and retry_after.isdigit() else 2 ** attempt
                time.sleep(min(delay, 30))
                continue
            error_body = exc.read().decode('utf-8', errors='replace')
            raise RuntimeError(f'Notion API request failed with status {exc.code}: {error_body}') from exc
        except urllib.error.URLError as exc:
            if attempt == max_retries - 1:
                raise RuntimeError(f'Notion API request failed: {exc.reason}') from exc
            time.sleep(2 ** attempt)
    raise RuntimeError('Notion API request exhausted retries')

def _plain_text(rich_text_items):
    parts = []
    for item in rich_text_items or []:
        text = item.get('plain_text')
        if text:
            parts.append(text)
    return ''.join(parts).strip()

def _task_title(page):
    properties = page.get('properties', {})
    for prop in properties.values():
        if prop.get('type') == 'title':
            title = _plain_text(prop.get('title', []))
            if title:
                return title
    return ''

def _is_done(page):
    properties = page.get('properties', {})
    for prop_name, prop in properties.items():
        prop_type = prop.get('type')
        normalized_name = prop_name.strip().lower()
        if prop_type == 'checkbox':
            if normalized_name in DONE_PROPERTY_NAMES and prop.get('checkbox') is True:
                return True
        if prop_type == 'status':
            status = prop.get('status') or {}
            name = (status.get('name') or '').strip().lower()
            group = (status.get('group') or '').strip().lower()
            if name in DONE_STATUS_NAMES or group == 'done':
                return True
        if prop_type == 'select':
            select = prop.get('select') or {}
            name = (select.get('name') or '').strip().lower()
            if name in DONE_STATUS_NAMES:
                return True
        if prop_type == 'formula':
            formula = prop.get('formula') or {}
            if formula.get('type') == 'boolean' and formula.get('boolean') is True and normalized_name in DONE_PROPERTY_NAMES:
                return True
    return False

def fetch_open_tasks():
    token = os.environ.get('NOTION_API_TOKEN', '')
    database_id = os.environ.get('NOTION_DATABASE_ID', '')
    if not token:
        raise RuntimeError('NOTION_API_TOKEN environment variable is required')
    if not database_id:
        raise RuntimeError('NOTION_DATABASE_ID environment variable is required')
    url = f'{NOTION_API_BASE}/databases/{database_id}/query'
    payload = {'page_size': 100}
    open_tasks = []
    while True:
        data = _notion_request(url, token, payload=payload)
        if not isinstance(data, dict):
            raise RuntimeError('Notion API returned an invalid response payload')
        results = data.get('results', [])
        if not isinstance(results, list):
            raise RuntimeError('Notion API returned an invalid results payload')
        for page in results:
            if not isinstance(page, dict):
                continue
            if _is_done(page):
                continue
            title = _task_title(page)
            if title:
                open_tasks.append(title)
        if not data.get('has_more'):
            break
        next_cursor = data.get('next_cursor')
        if not next_cursor:
            break
        payload = {'page_size': 100, 'start_cursor': next_cursor}
    return open_tasks

open_tasks = fetch_open_tasks()

