import json
import os
import urllib.error
import urllib.request
from collections import defaultdict

SLACK_POST_MESSAGE_URL = "https://slack.com/api/chat.postMessage"
MAX_SLACK_TEXT_LENGTH = 3900


def _group_by_assignee(overdue_tasks):
    grouped = defaultdict(list)
    for task in overdue_tasks:
        assignee = (task.get("assignee") or "Unassigned").strip() or "Unassigned"
        grouped[assignee].append(task)
    return grouped


def _format_task_line(task):
    name = (task.get("name") or "Untitled task").strip()
    due_date = (task.get("due_date") or "no due date").strip()
    return f"• {name} (due {due_date})"


def _split_section(section, limit):
    parts = []
    current = ""
    for line in section.splitlines(keepends=True):
        if current and len(current) + len(line) > limit:
            parts.append(current)
            current = line
        else:
            current += line
    if current:
        parts.append(current)
    return parts


def _build_message_chunks(overdue_tasks):
    grouped = _group_by_assignee(overdue_tasks)
    header = f":warning: *Overdue tasks* — {len(overdue_tasks)} total\n"
    sections = []
    for assignee in sorted(grouped):
        lines = [f"\n*{assignee}* ({len(grouped[assignee])})"]
        lines.extend(_format_task_line(t) for t in grouped[assignee])
        sections.append("\n".join(lines) + "\n")
    chunks = []
    current = header
    for section in sections:
        if len(section) > MAX_SLACK_TEXT_LENGTH:
            if current.strip():
                chunks.append(current)
                current = ""
            chunks.extend(_split_section(section, MAX_SLACK_TEXT_LENGTH))
            continue
        if len(current) + len(section) > MAX_SLACK_TEXT_LENGTH:
            chunks.append(current)
            current = section
        else:
            current += section
    if current.strip():
        chunks.append(current)
    return chunks


def _post_to_slack(channel_id, text, token):
    payload = json.dumps({"channel": channel_id, "text": text, "mrkdwn": True}).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json; charset=utf-8",
    }
    request = urllib.request.Request(SLACK_POST_MESSAGE_URL, data=payload, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            body = response.read().decode("utf-8")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Slack API HTTP error {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Slack API connection error: {exc.reason}") from exc
    result = json.loads(body)
    if not result.get("ok"):
        raise RuntimeError(f"Slack API rejected message: {result.get('error', 'unknown_error')}")
    return result


def report_overdue_tasks(overdue_tasks):
    token = os.environ.get("SLACK_BOT_TOKEN", "")
    channel_id = os.environ.get("SLACK_CHANNEL_ID", "")
    if not token:
        raise RuntimeError("SLACK_BOT_TOKEN is not set")
    if not channel_id:
        raise RuntimeError("SLACK_CHANNEL_ID is not set")
    if not overdue_tasks:
        _post_to_slack(channel_id, ":white_check_mark: No overdue tasks right now.", token)
        return []
    results = []
    for chunk in _build_message_chunks(overdue_tasks):
        results.append(_post_to_slack(channel_id, chunk, token))
    return results


report_overdue_tasks(overdue_tasks)

import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request

NOTION_API_BASE = 'https://api.notion.com/v1'
NOTION_VERSION = '2022-06-28'
PAGE_SIZE = 100
MAX_RETRIES = 5


def _notion_request(url, token, payload):
    headers = {
        'Authorization': f'Bearer {token}',
        'Notion-Version': NOTION_VERSION,
        'Content-Type': 'application/json',
    }
    body = json.dumps(payload).encode('utf-8')
    for attempt in range(MAX_RETRIES + 1):
        request = urllib.request.Request(url, data=body, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                return json.loads(response.read().decode('utf-8'))
        except urllib.error.HTTPError as exc:
            if exc.code == 429 and attempt < MAX_RETRIES:
                retry_after = exc.headers.get('Retry-After', '1')
                try:
                    delay = float(retry_after)
                except ValueError:
                    delay = 1.0
                time.sleep(max(delay, 1.0))
                continue
            detail = exc.read().decode('utf-8', errors='replace')
            raise RuntimeError(f'Notion API request failed with HTTP {exc.code}: {detail}') from exc
        except urllib.error.URLError as exc:
            if attempt < MAX_RETRIES:
                time.sleep(min(2 ** attempt, 10))
                continue
            raise RuntimeError(f'Notion API connection failed: {exc.reason}') from exc
    raise RuntimeError('Notion API request exhausted retries')


def fetch_pending_documents():
    token = os.environ.get('NOTION_API_TOKEN', '')
    database_id = os.environ.get('NOTION_DATABASE_ID', '')
    status_property = os.environ.get('NOTION_STATUS_PROPERTY', 'Status')
    pending_status = os.environ.get('NOTION_PENDING_STATUS', 'Pending Approval')
    if not token:
        raise RuntimeError('NOTION_API_TOKEN is not set')
    if not database_id:
        raise RuntimeError('NOTION_DATABASE_ID is not set')
    encoded_database_id = urllib.parse.quote(database_id, safe='')
    url = f'{NOTION_API_BASE}/databases/{encoded_database_id}/query'
    documents = []
    cursor = None
    while True:
        payload = {
            'page_size': PAGE_SIZE,
            'filter': {
                'property': status_property,
                'status': {'equals': pending_status},
            },
        }
        if cursor:
            payload['start_cursor'] = cursor
        data = _notion_request(url, token, payload)
        results = data.get('results', [])
        if not isinstance(results, list):
            raise RuntimeError('Unexpected Notion response: results is not a list')
        documents.extend(results)
        if not data.get('has_more'):
            break
        cursor = data.get('next_cursor')
        if not cursor:
            raise RuntimeError('Notion response indicated more pages but no next_cursor')
    return documents


documents = fetch_pending_documents()
print(f'Retrieved {len(documents)} document(s) pending approval from Notion.')

import json
import os
import urllib.error
import urllib.request

SLACK_POST_MESSAGE_URL = 'https://slack.com/api/chat.postMessage'

def send_approval_request(channel_id: str, pdf_url: str, document_summary: str) -> dict:
    token = os.environ.get('SLACK_BOT_TOKEN', '')
    if not token:
        raise RuntimeError('SLACK_BOT_TOKEN is not configured')
    if not channel_id:
        raise ValueError('Slack channel ID is required')
    if not pdf_url:
        raise ValueError('PDF URL is required')
    if not document_summary:
        raise ValueError('Document summary is required')
    message_text = chr(10).join([
        '*Document approval requested*',
        f'*Summary:* {document_summary}',
        f'*PDF:* {pdf_url}',
    ])
    payload = json.dumps({'channel': channel_id, 'text': message_text, 'unfurl_links': False}).encode('utf-8')
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json; charset=utf-8',
    }
    request = urllib.request.Request(SLACK_POST_MESSAGE_URL, data=payload, headers=headers, method='POST')
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            response_body = response.read().decode('utf-8')
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode('utf-8', errors='replace')
        raise RuntimeError(f'Slack API HTTP error {exc.code}: {error_body}') from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f'Slack API connection error: {exc.reason}') from exc
    try:
        result = json.loads(response_body)
    except json.JSONDecodeError as exc:
        raise RuntimeError('Slack API returned invalid JSON') from exc
    if not result.get('ok'):
        slack_error = result.get('error', 'Slack API returned ok=false without an error code')
        raise RuntimeError(f'Slack API rejected the message: {slack_error}')
    return result

def main() -> None:
    channel_id = os.environ.get('SLACK_CHANNEL_ID', '')
    pdf_url = os.environ.get('PDF_URL', '')
    document_summary = os.environ.get('DOCUMENT_SUMMARY', '')
    result = send_approval_request(channel_id, pdf_url, document_summary)
    print(json.dumps({'ok': result.get('ok'), 'ts': result.get('ts'), 'channel': result.get('channel')}))

main()

import json
import os
import urllib.parse
import urllib.request

NOTION_API_BASE = 'https://api.notion.com/v1/forms'
NOTION_VERSION = '2022-06-28'

def notion_plain_text(property_value):
    property_value = property_value or {}
    fragments = property_value.get('title', []) or property_value.get('rich_text', [])
    return ''.join(fragment.get('plain_text', '') for fragment in fragments).strip()

def normalize_submission(page):
    properties = page.get('properties', {}) or {}
    email_property = properties.get('Email', {}) or {}
    return {
        'id': page.get('id', ''),
        'name': notion_plain_text(properties.get('Name', {})),
        'email': email_property.get('email', '') or '',
        'subject': notion_plain_text(properties.get('Subject', {})),
        'message': notion_plain_text(properties.get('Message', {})),
    }

def fetch_and_validate_submissions():
    api_key = os.environ.get('NOTION_API_KEY')
    form_id = os.environ.get('NOTION_FORM_ID')
    if not api_key or not form_id:
        raise RuntimeError('NOTION_API_KEY and NOTION_FORM_ID must be set')
    url = NOTION_API_BASE + '/' + urllib.parse.quote(form_id, safe='') + '/submissions'
    headers = {'Authorization': 'Bearer ' + api_key, 'Notion-Version': NOTION_VERSION}
    request = urllib.request.Request(url, headers=headers, method='GET')
    with urllib.request.urlopen(request) as response:
        payload = json.loads(response.read().decode('utf-8'))
    submissions = []
    for page in payload.get('results', []):
        normalized = normalize_submission(page)
        if normalized.get('email') and normalized.get('message'):
            submissions.append(normalized)
    return submissions

