import json
import os
import urllib.parse
import urllib.request

NOTION_TOKEN = os.environ.get('NOTION_TOKEN', '')
NOTION_VERSION = '2022-06-28'
NOTION_BASE = 'https://api.notion.com/v1'

def fetch_wiki_pages():
    def notion_request(path, method='GET', payload=None):
        url = NOTION_BASE + path
        headers = {
            'Authorization': f'Bearer {NOTION_TOKEN}',
            'Notion-Version': NOTION_VERSION,
            'Content-Type': 'application/json',
        }
        data = json.dumps(payload).encode('utf-8') if payload is not None else None
        request = urllib.request.Request(url, data=data, headers=headers, method=method)
        with urllib.request.urlopen(request) as response:
            return json.loads(response.read().decode('utf-8'))

    def extract_rich_text(rich_text):
        parts = []
        for item in rich_text or []:
            text_obj = item.get('text', {})
            parts.append(text_obj.get('content', ''))
        return ''.join(parts)

    def fetch_block_text(block_id):
        text_parts = []
        cursor = None
        while True:
            query = {'page_size': '100'}
            if cursor:
                query['start_cursor'] = cursor
            path = '/blocks/' + block_id + '/children?' + urllib.parse.urlencode(query)
            data = notion_request(path)
            for block in data.get('results', []):
                block_type = block.get('type', '')
                block_payload = block.get(block_type, {})
                rich_text = block_payload.get('rich_text', [])
                if rich_text:
                    text_parts.append(extract_rich_text(rich_text))
                if block.get('has_children', False):
                    child_id = block.get('id', '')
                    if child_id:
                        text_parts.append(fetch_block_text(child_id))
            if not data.get('has_more', False):
                break
            cursor = data.get('next_cursor')
            if not cursor:
                break
        return '\n'.join(part for part in text_parts if part)

    pages = []
    cursor = None
    while True:
        payload = {'filter': {'property': 'object', 'value': 'page'}, 'page_size': 100}
        if cursor:
            payload['start_cursor'] = cursor
        data = notion_request('/search', method='POST', payload=payload)
        for page in data.get('results', []):
            page_id = page.get('id', '')
            properties = page.get('properties', {})
            title = 'Untitled'
            for prop in properties.values():
                if prop.get('type') == 'title':
                    title = extract_rich_text(prop.get('title', [])) or 'Untitled'
                    break
            page_url = page.get('url', '')
            page_text = fetch_block_text(page_id)
            pages.append({'id': page_id, 'title': title, 'url': page_url, 'text': page_text})
        if not data.get('has_more', False):
            break
        cursor = data.get('next_cursor')
        if not cursor:
            break
    return pages

wiki_pages = fetch_wiki_pages()
print('Fetched wiki pages:', len(wiki_pages))

import json
import os
import urllib.request

PINECONE_API_KEY = os.environ.get('PINECONE_API_KEY', '')
PINECONE_UPSERT_URL = os.environ.get('PINECONE_UPSERT_URL', 'https://docs.pinecone.io/reference/api/data-plane/upsert')
PINECONE_NAMESPACE = os.environ.get('PINECONE_NAMESPACE', 'team-wiki')

def upsert_vectors(chunks):
    vectors = []
    for record in chunks:
        vectors.append({
            'id': record.get('id', ''),
            'values': record.get('embedding', []),
            'metadata': {
                'page_id': record.get('page_id', ''),
                'title': record.get('title', ''),
                'url': record.get('url', ''),
                'chunk': record.get('chunk', ''),
            },
        })
    batch_size = 100
    total_upserted = 0
    for start in range(0, len(vectors), batch_size):
        batch = vectors[start:start + batch_size]
        payload = {'vectors': batch, 'namespace': PINECONE_NAMESPACE}
        data = json.dumps(payload).encode('utf-8')
        headers = {
            'Api-Key': PINECONE_API_KEY,
            'Content-Type': 'application/json',
        }
        request = urllib.request.Request(PINECONE_UPSERT_URL, data=data, headers=headers, method='POST')
        with urllib.request.urlopen(request) as response:
            result = json.loads(response.read().decode('utf-8'))
        total_upserted += int(result.get('upsertedCount', 0))
    return {'upsertedCount': total_upserted, 'namespace': PINECONE_NAMESPACE}

pinecone_upsert_result = upsert_vectors(wiki_chunks)
print('Upserted vectors:', pinecone_upsert_result.get('upsertedCount', 0))

import json
import os
import urllib.request

PINECONE_QUERY_URL = os.environ.get('PINECONE_QUERY_URL', 'https://docs.pinecone.io/reference/api/data-plane/query')

def search_wiki(query_text, top_k=5):
    def embed_query(text):
        payload = {'model': EMBEDDING_MODEL, 'input': text}
        data = json.dumps(payload).encode('utf-8')
        headers = {
            'Authorization': f'Bearer {OPENAI_API_KEY}',
            'Content-Type': 'application/json',
        }
        request = urllib.request.Request(OPENAI_EMBEDDINGS_URL, data=data, headers=headers, method='POST')
        with urllib.request.urlopen(request) as response:
            result = json.loads(response.read().decode('utf-8'))
        data_items = result.get('data', [])
        if not data_items:
            return []
        return data_items[0].get('embedding', [])

    if not pinecone_upsert_result.get('upsertedCount', 0):
        raise RuntimeError('No vectors were upserted; run the upsert step first.')
    query_vector = embed_query(query_text)
    if not query_vector:
        return []
    payload = {
        'vector': query_vector,
        'topK': top_k,
        'includeMetadata': True,
        'namespace': PINECONE_NAMESPACE,
    }
    data = json.dumps(payload).encode('utf-8')
    headers = {
        'Api-Key': PINECONE_API_KEY,
