import os
from collections import defaultdict

# Configurable fallbacks; no secrets are required for this grouping step.
DEFAULT_THEME = os.environ.get('DEFAULT_FEEDBACK_THEME', 'unclassified').strip().lower() or 'unclassified'
DEFAULT_ASSET = os.environ.get('DEFAULT_FEEDBACK_ASSET', 'Unknown Asset').strip() or 'Unknown Asset'


def _clean_text(value):
    '''Return stripped text for string values, empty string otherwise.'''
    if isinstance(value, str):
        return value.strip()
    return ''


def _clean_key(value, fallback):
    '''Normalize a grouping key and apply a fallback when it is blank.'''
    if isinstance(value, str):
        candidate = value.strip()
        if candidate:
            return candidate
    return fallback


def group_feedback(records):
    '''Group feedback records by asset and by asset+theme.

    Every input record is represented in the output either inside a group or
    in the empty_feedback_ids list, so no feedback is silently dropped.
    '''
    by_asset = defaultdict(list)
    by_asset_theme = defaultdict(lambda: defaultdict(list))
    empty_feedback_ids = []
    source = records or []

    for index, record in enumerate(source):
        if isinstance(record, dict):
            fields = record.get('fields') or {}
            record_id = record.get('id') or f'row-{index}'
        else:
            fields = {}
            record_id = f'row-{index}'
        if not isinstance(fields, dict):
            fields = {}

        asset = _clean_key(fields.get('Asset'), DEFAULT_ASSET)
        theme = _clean_key(fields.get('Theme'), DEFAULT_THEME).lower()
        feedback = _clean_text(fields.get('Feedback'))

        item = {'id': record_id, 'asset': asset, 'theme': theme, 'feedback': feedback}
        by_asset[asset].append(item)
        by_asset_theme[asset][theme].append(item)

        if not feedback:
            empty_feedback_ids.append(record_id)

    return {
        'by_asset': {asset: items for asset, items in by_asset.items()},
        'by_asset_theme': {asset: dict(themes) for asset, themes in by_asset_theme.items()},
        'empty_feedback_ids': empty_feedback_ids,
        'total_records': len(source),
    }


# feedback_records is supplied by the previous workflow step.
grouped_feedback = group_feedback(feedback_records)

