import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request

LIVEBLOCKS_API_BASE = "https://api.liveblocks.io"
PRESENCE_PATH_TEMPLATE = "/v2/rooms/{room_id}/presence"
MAX_RETRIES = 4
BASE_BACKOFF_SECONDS = 1.0
MAX_BACKOFF_SECONDS = 30.0
REQUEST_TIMEOUT_SECONDS = 15


def _api_key() -> str:
    key = os.environ.get("LIVEBLOCKS_API_KEY", "")
    if not key:
        raise RuntimeError("LIVEBLOCKS_API_KEY is not set")
    return key


def _room_ids() -> list[str]:
    raw = os.environ.get("LIVEBLOCKS_ROOM_IDS", "")
    rooms = [item.strip() for item in raw.split(",") if item.strip()]
    if not rooms:
        raise RuntimeError("LIVEBLOCKS_ROOM_IDS is not set or empty")
    return rooms


def fetch_liveblocks_presence(room_id: str) -> list[dict]:
    """Fetch active users for a single Liveblocks room with retry on 429/5xx."""
    if not room_id:
        raise ValueError("room_id must be a non-empty string")
    encoded_room = urllib.parse.quote(room_id, safe="")
    url = LIVEBLOCKS_API_BASE + PRESENCE_PATH_TEMPLATE.format(room_id=encoded_room)
    headers = {
        "Authorization": f"Bearer {_api_key()}",
        "Accept": "application/json",
    }
    last_error: Exception | None = None
    for attempt in range(MAX_RETRIES):
        request = urllib.request.Request(url, headers=headers, method="GET")
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
                payload = json.loads(response.read().decode("utf-8"))
            if not isinstance(payload, dict):
                raise ValueError(f"Unexpected presence payload for room {room_id!r}: not a JSON object")
            users = payload.get("users", [])
            if not isinstance(users, list):
                raise ValueError(f"Unexpected presence payload for room {room_id!r}: 'users' is not a list")
            return users
        except urllib.error.HTTPError as exc:
            last_error = exc
            if exc.code == 429 or 500 <= exc.code < 600:
                retry_after = exc.headers.get("Retry-After") if exc.headers else None
                if retry_after and retry_after.isdigit():
                    delay = float(retry_after)
                else:
                    delay = BASE_BACKOFF_SECONDS * (2 ** attempt)
                time.sleep(min(delay, MAX_BACKOFF_SECONDS))
                continue
            raise RuntimeError(
                f"Liveblocks presence request failed for room {room_id!r} with HTTP {exc.code}"
            ) from exc
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
            last_error = exc
            time.sleep(min(BASE_BACKOFF_SECONDS * (2 ** attempt), MAX_BACKOFF_SECONDS))
    raise RuntimeError(
        f"Liveblocks presence request failed for room {room_id!r} after {MAX_RETRIES} attempts"
    ) from last_error


def fetch_all_presence() -> dict[str, list[dict]]:
    """Fetch presence for every configured room and return a room->users mapping."""
    presence_by_room: dict[str, list[dict]] = {}
    for room_id in _room_ids():
        presence_by_room[room_id] = fetch_liveblocks_presence(room_id)
    return presence_by_room


active_users_by_room = fetch_all_presence()
print(json.dumps(active_users_by_room, indent=2, sort_keys=True))

