import json
import os
import urllib.request

LINEAR_ENDPOINT = "https://api.linear.app/graphql"
LINEAR_API_KEY = os.environ.get("LINEAR_API_KEY", "")
LINEAR_TEAM_ID = os.environ.get("LINEAR_TEAM_ID", "")

ISSUE_LOOKUP_QUERY = """
query ExistingIssues($teamId: String!) {
  team(id: $teamId) {
    issues(first: 100) {
      nodes { id identifier title }
    }
  }
}
"""

ISSUE_CREATE_MUTATION = """
mutation CreateIssue($teamId: String!, $title: String!, $description: String!) {
  issueCreate(input: {teamId: $teamId, title: $title, description: $description}) {
    success
    issue { id identifier url }
  }
}
"""


def linear_request(query, variables):
    body = json.dumps({"query": query, "variables": variables}).encode("utf-8")
    headers = {"Authorization": LINEAR_API_KEY, "Content-Type": "application/json"}
    request = urllib.request.Request(LINEAR_ENDPOINT, data=body, headers=headers, method="POST")
    with urllib.request.urlopen(request, timeout=30) as response:
        if response.status != 200:
            raise RuntimeError("Linear returned status " + str(response.status))
        return json.loads(response.read().decode("utf-8"))


def sync_linear_issues(groups):
    lookup = linear_request(ISSUE_LOOKUP_QUERY, {"teamId": LINEAR_TEAM_ID})
    # GraphQL returns null for absent nodes, so every hop falls back to an empty dict.
    data = lookup.get("data") or {}
    team = data.get("team") or {}
    issues_block = team.get("issues") or {}
    nodes = issues_block.get("nodes") or []
    existing = {}
    for node in nodes:
        existing[node.get("title", "")] = node.get("identifier", "")
    created = []
    updated = []
    for group in groups:
        title = "[Sentry] " + group.get("title", "unknown error")
        if title in existing:
            updated.append({"fingerprint": group.get("fingerprint", ""), "identifier": existing.get(title, "")})
            continue
        description = "Fingerprint: " + group.get("fingerprint", "") + "\nOccurrences: " + str(group.get("count", 0)) + "\nSentry: " + group.get("permalink", "")
        variables = {"teamId": LINEAR_TEAM_ID, "title": title, "description": description}
        result = linear_request(ISSUE_CREATE_MUTATION, variables)
        result_data = result.get("data") or {}
        create_block = result_data.get("issueCreate") or {}
        issue = create_block.get("issue") or {}
        created.append({"fingerprint": group.get("fingerprint", ""), "identifier": issue.get("identifier", ""), "url": issue.get("url", "")})
    return {"created": created, "updated": updated}


