SLACK_POST_MESSAGE_URL = "https://slack.com/api/chat.postMessage"
SLACK_BOT_TOKEN = os.environ.get("SLACK_BOT_TOKEN", "")
SLACK_CHANNEL_ID = os.environ.get("SLACK_CHANNEL_ID", "")
ALERT_THRESHOLD = int(os.environ.get("ALERT_THRESHOLD", "10"))


def build_alert_text(groups, sync):
    identifiers = {}
    for item in sync.get("created", []) + sync.get("updated", []):
        identifiers[item.get("fingerprint", "")] = item.get("identifier", "")
    lines = []
    for group in groups:
        count = int(group.get("count", 0) or 0)
        # Only groups above the threshold are worth waking the on-call engineer.
        if count < ALERT_THRESHOLD:
            continue
        key = group.get("fingerprint", "")
        lines.append("- " + group.get("title", "unknown") + " | " + str(count) + " events | " + identifiers.get(key, "no issue"))
    return "\n".join(lines)


def post_slack_message(text):
    body = json.dumps({"channel": SLACK_CHANNEL_ID, "text": text, "unfurl_links": False}).encode("utf-8")
    headers = {"Authorization": "Bearer " + SLACK_BOT_TOKEN, "Content-Type": "application/json; charset=utf-8"}
    request = urllib.request.Request(SLACK_POST_MESSAGE_URL, data=body, headers=headers, method="POST")
    with urllib.request.urlopen(request, timeout=30) as response:
        # chat.postMessage returns a JSON envelope, unlike an incoming webhook that returns plain ok.
        payload = json.loads(response.read().decode("utf-8"))
    if not payload.get("ok", False):
        raise RuntimeError("Slack error: " + str(payload.get("error", "unknown")))
    return {"channel": payload.get("channel", ""), "ts": payload.get("ts", ""), "text": text}


