import urllib.request

RESEND_ENDPOINT = "https://api.resend.com/emails"

def _required_env(name: str) -> str:
    value = os.environ.get(name, "").strip()
    if not value:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value

def _parse_recipients(raw: str) -> list[str]:
    recipients = [item.strip() for item in raw.split(",") if item.strip()]
    if not recipients:
        raise RuntimeError("REPORT_RECIPIENTS must contain at least one email address")
    for address in recipients:
        if "@" not in address or address.startswith("@") or address.endswith("@"):
            raise ValueError(f"Invalid recipient email address: {address}")
    return recipients

def send_email(report_html: str) -> dict:
    if not isinstance(report_html, str) or not report_html.strip():
        raise ValueError("report_html must be a non-empty string")
    api_key = _required_env("RESEND_API_KEY")
    from_email = _required_env("REPORT_FROM_EMAIL")
    recipients = _parse_recipients(_required_env("REPORT_RECIPIENTS"))
    subject = os.environ.get("REPORT_SUBJECT", "Weekly Performance Report").strip() or "Weekly Performance Report"
    payload = {
        "from": from_email,
        "to": recipients,
        "subject": subject,
        "html": report_html,
    }
    data = json.dumps(payload).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    request = urllib.request.Request(RESEND_ENDPOINT, data=data, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            body = response.read().decode("utf-8")
            if not body:
                return {"status": response.status, "body": {}}
            return {"status": response.status, "body": json.loads(body)}
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Resend API returned HTTP {exc.code}: {error_body}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Failed to reach Resend API: {exc.reason}") from exc
    except json.JSONDecodeError as exc:
        raise RuntimeError("Resend API returned a non-JSON response") from exc

report_html = globals().get("report")
if not isinstance(report_html, str) or not report_html.strip():
    raise RuntimeError("No report HTML was provided by the previous workflow step")
