import json
import os
from typing import Any, Iterable

def _to_int(value: Any) -> int | None:
    # Convert Airtable values to integers without accepting booleans or fractional stock counts.
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value) if value.is_integer() else None
    text = str(value).strip()
    if not text:
        return None
    try:
        number = float(text)
    except (TypeError, ValueError):
        return None
    if not number.is_integer():
        return None
    return int(number)

def _first_present(record: dict[str, Any], keys: tuple[str, ...]) -> Any:
    # Accept common Airtable and Shopify field names.
    for key in keys:
        if key in record and record[key] not in (None, ''):
            return record[key]
    return None

def detect_low_stock_variants(variants: Iterable[dict[str, Any]], default_reorder_point: int | None = None) -> list[dict[str, Any]]:
    low_stock: list[dict[str, Any]] = []
    for record in variants:
        if not isinstance(record, dict):
            continue
        sku_value = _first_present(record, ('sku', 'SKU', 'variant_sku', 'Variant SKU'))
        sku = str(sku_value).strip() if sku_value is not None else ''
        variant_id = _first_present(record, ('id', 'variant_id', 'variantId', 'Variant ID'))
        quantity = _to_int(_first_present(record, ('inventory_quantity', 'stock_level', 'Stock Level', 'quantity', 'Quantity')))
        reorder_point = _to_int(_first_present(record, ('reorder_point', 'reorderPoint', 'Reorder Point', 'threshold')))
        if reorder_point is None:
            reorder_point = default_reorder_point
        # Skip records that cannot be evaluated to avoid false positives.
        if quantity is None or reorder_point is None:
            continue
        if quantity < reorder_point:
            low_stock.append({
                'sku': sku,
                'variant_id': variant_id,
                'quantity': quantity,
                'reorder_point': reorder_point,
                'shortfall': reorder_point - quantity,
            })
    return low_stock

# The step is local, but the workflow still reads the Airtable key for consistency.
_airtable_api_key = os.environ.get('AIRTABLE_API_KEY', '')
default_reorder_point = _to_int(os.environ.get('INVENTORY_REORDER_POINT', ''))
variants_json = os.environ.get('INVENTORY_VARIANTS_JSON', '').strip()
try:
    variants = json.loads(variants_json) if variants_json else []
except json.JSONDecodeError as exc:
    raise ValueError('INVENTORY_VARIANTS_JSON must contain valid JSON') from exc
if not isinstance(variants, list):
    raise ValueError('INVENTORY_VARIANTS_JSON must decode to a list of variant records')
# End with the top-level call that produces the step result.
low_stock_variants = detect_low_stock_variants(variants, default_reorder_point)

import json
import logging
import os
from typing import Any

logging.basicConfig(level=logging.INFO, format='%(levelname)s:%(message)s')
LOGGER = logging.getLogger(__name__)

DEFAULT_THRESHOLDS = {
    'severity': 3.0,
    'wind_speed': 20.0,
    'precipitation': 10.0,
    'temperature': -5.0,
    'visibility': 1000.0,
}

def _as_float(value: Any, default: float | None = None) -> float | None:
    try:
        if value is None or value == '':
            return default
        return float(value)
    except (TypeError, ValueError):
        return default

def evaluate_alerts(normalised_forecasts: Any, thresholds: dict[str, float] | None = None) -> list[dict[str, Any]]:
    '''Return forecasts that meet severe weather alert thresholds.'''
    if not isinstance(normalised_forecasts, list):
        LOGGER.warning('Expected a list of forecasts, got %s', type(normalised_forecasts).__name__)
        return []
    active_thresholds = dict(DEFAULT_THRESHOLDS)
    if isinstance(thresholds, dict):
        for key, value in thresholds.items():
            if key in active_thresholds and isinstance(value, (int, float)):
                active_thresholds[key] = float(value)
    alerts: list[dict[str, Any]] = []
    for index, forecast in enumerate(normalised_forecasts):
        if not isinstance(forecast, dict):
            LOGGER.warning('Skipping forecast at index %s: not a mapping', index)
            continue
        location = str(forecast.get('location') or forecast.get('city') or f'index-{index}')
        severity = _as_float(forecast.get('severity'))
        wind_speed = _as_float(forecast.get('wind_speed'))
        precipitation = _as_float(forecast.get('precipitation'))
        temperature = _as_float(forecast.get('temperature'))
        visibility = _as_float(forecast.get('visibility'))
        reasons: list[str] = []
        severity_threshold = active_thresholds['severity']
        wind_threshold = active_thresholds['wind_speed']
        precipitation_threshold = active_thresholds['precipitation']
        temperature_threshold = active_thresholds['temperature']
        visibility_threshold = active_thresholds['visibility']
        if severity is not None and severity >= severity_threshold:
            reasons.append(f'severity {severity:g} >= {severity_threshold:g}')
        if wind_speed is not None and wind_speed >= wind_threshold:
            reasons.append(f'wind_speed {wind_speed:g} >= {wind_threshold:g}')
        if precipitation is not None and precipitation >= precipitation_threshold:
            reasons.append(f'precipitation {precipitation:g} >= {precipitation_threshold:g}')
        if temperature is not None and temperature <= temperature_threshold:
            reasons.append(f'temperature {temperature:g} <= {temperature_threshold:g}')
        if visibility is not None and visibility <= visibility_threshold:
            reasons.append(f'visibility {visibility:g} <= {visibility_threshold:g}')
        if reasons:
            alert = dict(forecast)
            alert['location'] = location
            alert['alert_reasons'] = reasons
            alerts.append(alert)
            LOGGER.info('Alert flagged for %s: %s', location, '; '.join(reasons))
    if not alerts:
        LOGGER.info('No locations met severe weather alert thresholds')
    return alerts

raw_forecasts = os.environ.get('NORMALISED_FORECASTS_JSON', '[]')
try:
    normalised_forecasts = json.loads(raw_forecasts)
except json.JSONDecodeError as exc:
    LOGGER.error('Invalid NORMALISED_FORECASTS_JSON: %s', exc)
    normalised_forecasts = []

alerts = evaluate_alerts(normalised_forecasts)

