def _normalize_asset(asset, index):
    if not isinstance(asset, dict):
        raise ValueError(f'Asset at index {index} must be a JSON object')
    required_fields = ('url', 'size', 'checksum', 'verification_status')
    missing_fields = [field for field in required_fields if field not in asset]
    if missing_fields:
        missing_text = ', '.join(missing_fields)
        raise ValueError(f'Asset at index {index} is missing fields: {missing_text}')
    url = str(asset['url']).strip()
    if not url:
        raise ValueError(f'Asset at index {index} has an empty url')
    try:
        size = int(asset['size'])
    except (TypeError, ValueError) as exc:
        raise ValueError(f'Asset at index {index} has a non-integer size') from exc
    if size < 0:
        raise ValueError(f'Asset at index {index} has a negative size')
    checksum = str(asset['checksum']).strip()
    if not checksum:
        raise ValueError(f'Asset at index {index} has an empty checksum')
    verification_status = str(asset['verification_status']).strip()
    if not verification_status:
        raise ValueError(f'Asset at index {index} has an empty verification_status')
    return {
        'url': url,
        'size': size,
        'checksum': checksum,
        'verification_status': verification_status,
    }

def build_manifest(assets):
    if not isinstance(assets, list):
        raise ValueError('assets must be a JSON array')
    normalized_assets = [_normalize_asset(asset, index) for index, asset in enumerate(assets)]
    return {
        'generated_at': datetime.now(timezone.utc).isoformat(),
        'asset_count': len(normalized_assets),
        'assets': normalized_assets,
    }

def write_manifest_file(manifest, output_path):
    absolute_path = os.path.abspath(output_path)
    directory = os.path.dirname(absolute_path)
    os.makedirs(directory, exist_ok=True)
    temp_path = f'{absolute_path}.tmp'
    with open(temp_path, 'w', encoding='utf-8') as handle:
        json.dump(manifest, handle, indent=2, sort_keys=True)
        handle.write(os.linesep)
    os.replace(temp_path, absolute_path)

def _post_json(url, token, payload):
    request_body = json.dumps(payload, separators=(',', ':')).encode('utf-8')
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {token}',
    }
    for attempt in range(1, MAX_RETRIES + 1):
        request = urllib.request.Request(url, data=request_body, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
                response_body = response.read().decode('utf-8', errors='replace')
                if response.status >= 400:
                    raise RuntimeError(f'POST {url} returned HTTP {response.status}: {response_body}')
                return response_body
        except urllib.error.HTTPError as exc:
            error_body = exc.read().decode('utf-8', errors='replace')
            if exc.code == 429 or 500 <= exc.code < 600:
                retry_after = exc.headers.get('Retry-After') if exc.headers else None
                if retry_after:
                    try:
                        delay = float(retry_after)
                    except ValueError:
                        delay = min(2 ** attempt, 30)
                else:
                    delay = min(2 ** attempt, 30)
                if attempt == MAX_RETRIES:
                    raise RuntimeError(
                        f'POST {url} failed after {MAX_RETRIES} attempts: HTTP {exc.code} {error_body}'
                    ) from exc
                time.sleep(delay)
                continue
            raise RuntimeError(f'POST {url} failed: HTTP {exc.code} {error_body}') from exc
        except urllib.error.URLError as exc:
            if attempt == MAX_RETRIES:
                raise RuntimeError(
                    f'POST {url} failed after {MAX_RETRIES} attempts: {exc.reason}'
                ) from exc
            time.sleep(min(2 ** attempt, 30))
    raise RuntimeError(f'POST {url} failed after {MAX_RETRIES} attempts')

def post_manifest(endpoint, token, manifest):
    assets = manifest['assets']
    if assets:
        batches = [
            assets[start:start + MAX_ASSETS_PER_REQUEST]
            for start in range(0, len(assets), MAX_ASSETS_PER_REQUEST)
        ]
    else:
        batches = [[]]
    total_pages = len(batches)
    for page_number, batch in enumerate(batches, start=1):
        payload = {
            'assets': batch,
            'page': page_number,
            'total_pages': total_pages,
            'generated_at': manifest['generated_at'],
        }
        _post_json(endpoint, token, payload)
    return total_pages

def main():
    endpoint = os.environ.get('BACKUP_MANIFEST_ENDPOINT', '').strip()
    token = os.environ.get('BACKUP_API_TOKEN', '').strip()
    output_path = os.environ.get('BACKUP_MANIFEST_PATH', 'backup_manifest.json').strip()
    assets_json = os.environ.get('BACKUP_ASSETS_JSON', '').strip()
    if not endpoint:
        raise ValueError('BACKUP_MANIFEST_ENDPOINT is required')
    if not token:
        raise ValueError('BACKUP_API_TOKEN is required')
    if not output_path:
        raise ValueError('BACKUP_MANIFEST_PATH must not be empty')
    if not assets_json:
        raise ValueError('BACKUP_ASSETS_JSON is required')
    try:
        assets = json.loads(assets_json)
    except json.JSONDecodeError as exc:
        raise ValueError('BACKUP_ASSETS_JSON must contain valid JSON') from exc
    manifest = build_manifest(assets)
    write_manifest_file(manifest, output_path)
    post_manifest(endpoint, token, manifest)
    return manifest

main()

import hashlib
import json
import os
import time
import urllib.error
import urllib.request
from typing import Any

MAX_ATTEMPTS = 4
BASE_BACKOFF = 1.0
MAX_BACKOFF = 8.0

def _env_required(name: str) -> str:
    value = os.environ.get(name, '').strip()
    if not value:
        raise RuntimeError(f'Missing required environment variable: {name}')
    return value

def _request_json(url: str, token: str) -> Any:
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
    }
    for attempt in range(1, MAX_ATTEMPTS + 1):
        request = urllib.request.Request(url, headers=headers, method='GET')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                raw = response.read()
                charset = response.headers.get_content_charset() or 'utf-8'
                return json.loads(raw.decode(charset))
        except urllib.error.HTTPError as exc:
            if exc.code in (429, 500, 502, 503, 504) and attempt < MAX_ATTEMPTS:
                retry_after = exc.headers.get('Retry-After', '')
                try:
                    delay = float(retry_after)
                except ValueError:
                    delay = BASE_BACKOFF * (2 ** (attempt - 1))
                time.sleep(min(max(delay, 0.0), MAX_BACKOFF))
                continue
            raise
        except urllib.error.URLError:
            if attempt < MAX_ATTEMPTS:
                time.sleep(min(BASE_BACKOFF * (2 ** (attempt - 1)), MAX_BACKOFF))
                continue
            raise
    raise RuntimeError('Request retries exhausted')

def _extract_checksum(payload: Any) -> str:
    if isinstance(payload, dict):
        checksum = payload.get('checksum')
        if isinstance(checksum, str) and checksum.strip():
            return checksum.strip()
        for key in ('items', 'results', 'data'):
            nested = payload.get(key)
            if isinstance(nested, list) and nested:
                return _extract_checksum(nested[0])
            if isinstance(nested, dict):
                return _extract_checksum(nested)
    if isinstance(payload, list) and payload:
        return _extract_checksum(payload[0])
    raise ValueError('Response does not contain a non-empty checksum field')

def _extract_content(payload: Any) -> bytes:
    if isinstance(payload, dict):
        content = payload.get('content')
        if isinstance(content, str):
            return content.encode('utf-8')
        if isinstance(content, (bytes, bytearray)):
            return bytes(content)
        return json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    if isinstance(payload, list):
        return json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    if isinstance(payload, str):
        return payload.encode('utf-8')
    raise ValueError('Unsupported response payload type for checksum verification')

def verify_deployment() -> bool:
    url = _env_required('DEPLOYMENT_HEALTH_URL')
    token = _env_required('DEPLOYMENT_AUTH_TOKEN')
    payload = _request_json(url, token)
    expected_checksum = _extract_checksum(payload)
    content = _extract_content(payload)
    actual_checksum = hashlib.sha256(content).hexdigest()
    if actual_checksum.lower() != expected_checksum.lower():
        raise RuntimeError(f'Deployment checksum mismatch: expected {expected_checksum}, got {actual_checksum}')
    return True

is_verified = verify_deployment()
print(json.dumps({'verified': is_verified}))

import json
import os
import urllib.error
import urllib.parse
import urllib.request

GRAPH_BASE = 'https://graph.microsoft.com/v1.0'
GRAPH_TOKEN = os.environ.get('MS_GRAPH_TOKEN', '')
GROUP_ID = os.environ.get('MS_GRAPH_GROUP_ID', '')
MAX_PAGES = 20

def graph_get(url):
    headers = {'Authorization': 'Bearer ' + GRAPH_TOKEN, 'Accept': 'application/json'}
    request = urllib.request.Request(url, headers=headers, method='GET')
    try:
        with urllib.request.urlopen(request, timeout=5) as response:
            return response.status, json.loads(response.read().decode('utf-8'))
    except urllib.error.HTTPError as error:
        body = error.read().decode('utf-8')
        parsed = json.loads(body) if body.strip() else {}
        return error.code, parsed

def fetch_group_members():
    members = []
    if not GROUP_ID:
        return members
    query = urllib.parse.urlencode({'$select': 'id,displayName,mail,userPrincipalName', '$top': '100'})
    next_link = GRAPH_BASE + '/groups/' + urllib.parse.quote(GROUP_ID, safe='') + '/members?' + query
    page_count = 0
    while next_link and page_count < MAX_PAGES:
        status, payload = graph_get(next_link)
        page_count += 1
        if status != 200:
            break
        for item in payload.get('value', []):
            email = item.get('mail') or item.get('userPrincipalName') or ''
            members.append({
                'id': item.get('id', ''),
                'displayName': item.get('displayName', ''),
                'email': email,
                'userPrincipalName': item.get('userPrincipalName', '')
            })
        next_link = payload.get('@odata.nextLink', '')
    return members

group_members = fetch_group_members()

import json
import os
import urllib.error
import urllib.parse
import urllib.request

AUTH0_API_BASE = 'https://auth0.com/api/v2'
AUTH0_TOKEN = os.environ.get('AUTH0_MANAGEMENT_TOKEN', '')
DEFAULT_PASSWORD = os.environ.get('AUTH0_DEFAULT_PASSWORD', '')

def auth0_request(method, path, payload=None):
    url = AUTH0_API_BASE + path
    headers = {'Authorization': 'Bearer ' + AUTH0_TOKEN, 'Content-Type': 'application/json'}
    data = None
    if payload is not None:
        data = json.dumps(payload).encode('utf-8')
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request, timeout=5) as response:
            body = response.read().decode('utf-8')
            if body.strip():
                return response.status, json.loads(body)
            return response.status, {}
    except urllib.error.HTTPError as error:
        body = error.read().decode('utf-8')
        parsed = json.loads(body) if body.strip() else {}
        return error.code, parsed

def provision_users(members):
    results = []
    for member in members:
        email = member.get('email', '').strip().lower()
        if not email:
            results.append({'email': '', 'user_id': '', 'status': 'failed', 'action': 'skipped', 'error': 'missing_email'})
            continue
        query = urllib.parse.urlencode({'email': email})
        lookup_status, existing = auth0_request('GET', '/users-by-email?' + query)
        if lookup_status == 200 and isinstance(existing, list) and existing:
            user = existing[0]
            user_id = user.get('user_id', '')
            update_payload = {
                'email': email,
                'name': member.get('displayName', email),
                'user_metadata': {'m365_id': member.get('id', ''), 'source': 'microsoft_graph'}
            }
            update_status, update_body = auth0_request('PATCH', '/users/' + urllib.parse.quote(user_id, safe=''), update_payload)
            if update_status in (200, 201):
                results.append({'email': email, 'user_id': user_id, 'status': 'success', 'action': 'updated', 'error': ''})
            else:
                error_text = update_body.get('message', update_body) if isinstance(update_body, dict) else str(update_body)
                results.append({'email': email, 'user_id': user_id, 'status': 'failed', 'action': 'updated', 'error': str(error_text)})
        elif lookup_status == 200 and isinstance(existing, list) and not existing:
            create_payload = {
                'email': email,
                'name': member.get('displayName', email),
                'connection': 'Username-Password-Authentication',
                'password': DEFAULT_PASSWORD,
                'user_metadata': {'m365_id': member.get('id', ''), 'source': 'microsoft_graph'}
            }
            create_status, create_body = auth0_request('POST', '/users', create_payload)
            if create_status in (200, 201):
                results.append({'email': email, 'user_id': create_body.get('user_id', ''), 'status': 'success', 'action': 'created', 'error': ''})
            else:
                error_text = create_body.get('message', create_body) if isinstance(create_body, dict) else str(create_body)
                results.append({'email': email, 'user_id': '', 'status': 'failed', 'action': 'created', 'error': str(error_text)})
        else:
            error_text = existing.get('message', existing) if isinstance(existing, dict) else 'lookup_error'
            results.append({'email': email, 'user_id': '', 'status': 'failed', 'action': 'lookup', 'error': str(error_text)})
    return results

provisioned_users = provision_users(group_members)

import os
import urllib.parse

ROLE_NAMES = [name.strip() for name in os.environ.get('AUTH0_ROLE_NAMES', '').split(',') if name.strip()]

def load_role_ids():
    role_ids = {}
    if not ROLE_NAMES:
        return role_ids
    status, payload = auth0_request('GET', '/roles?per_page=100&page=0')
    if status != 200:
        return role_ids
    roles = payload if isinstance(payload, list) else payload.get('roles', [])
    for role in roles:
        name = role.get('name', '')
        if name in ROLE_NAMES:
            role_ids[name] = role.get('id', '')
    return role_ids

def assign_roles(users):
    assignments = []
    role_ids = load_role_ids()
    selected_ids = [role_ids[name] for name in ROLE_NAMES if role_ids.get(name)]
    for user in users:
        email = user.get('email', '')
        user_id = user.get('user_id', '')
        if user.get('status') != 'success' or not user_id:
            assignments.append({'email': email, 'user_id': user_id, 'roles': [], 'status': 'skipped', 'error': 'user_not_provisioned'})
            continue
        if not selected_ids:
            assignments.append({'email': email, 'user_id': user_id, 'roles': [], 'status': 'skipped', 'error': 'no_configured_roles'})
            continue
        path = '/users/' + urllib.parse.quote(user_id, safe='') + '/roles'
        status, payload = auth0_request('POST', path, {'roles': selected_ids})
        if status in (200, 201, 204):
            assignments.append({'email': email, 'user_id': user_id, 'roles': selected_ids, 'status': 'success', 'error': ''})
        elif status == 409:
            assignments.append({'email': email, 'user_id': user_id, 'roles': selected_ids, 'status': 'skipped', 'error': 'already_assigned'})
        else:
            error_text = payload.get('message', payload) if isinstance(payload, dict) else str(payload)
            assignments.append({'email': email, 'user_id': user_id, 'roles': selected_ids, 'status': 'failed', 'error': str(error_text)})
    return assignments

role_assignments = assign_roles(provisioned_users)

import html
import json
import os
import time
import urllib.error
import urllib.request

RESEND_ENDPOINT = 'https://api.resend.com/emails'
MAX_ATTEMPTS = 3
RETRY_STATUS_CODES = {429, 500, 502, 503, 504}

def _is_valid_email(value):
    email_address = str(value or '').strip()
    if not email_address or email_address.count('@') != 1:
        return False
    if any(ch.isspace() for ch in email_address):
        return False
    local_part, domain_part = email_address.split('@', 1)
    if not local_part or not domain_part:
        return False
    if domain_part.startswith('.') or domain_part.endswith('.') or '..' in domain_part:
        return False
    return '.' in domain_part

def _post_json(url, payload, api_key):
    body = json.dumps(payload).encode('utf-8')
    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
    }
    request = urllib.request.Request(url, data=body, headers=headers, method='POST')
    with urllib.request.urlopen(request, timeout=30) as response:
        raw = response.read().decode('utf-8')
        return json.loads(raw) if raw else {}

def send_welcome_email(users):
    api_key = os.environ.get('RESEND_API_KEY', '')
    from_email = os.environ.get('RESEND_FROM_EMAIL', '')
    reply_to = os.environ.get('RESEND_REPLY_TO', '')
    if not api_key:
        raise RuntimeError('RESEND_API_KEY is required')
    if not from_email:
        raise RuntimeError('RESEND_FROM_EMAIL is required')
    if not isinstance(users, list):
        raise TypeError('users must be a list')
    results = []
    for user in users:
        if not isinstance(user, dict):
            results.append({'email': None, 'status': 'skipped', 'reason': 'user record is not an object'})
            continue
        email_address = str(user.get('email', '')).strip()
        if not _is_valid_email(email_address):
            results.append({'email': email_address, 'status': 'skipped', 'reason': 'invalid email address'})
            continue
        display_name = str(user.get('first_name') or user.get('name') or email_address.split('@', 1)[0]).strip()
        safe_name = html.escape(display_name)
        subject = 'Welcome to Our Service'
        text_body = chr(10).join([
            f'Hello {display_name},',
            '',
            'Thank you for joining us!',
        ])
        html_body = f'<p>Hello {safe_name},</p><p>Thank you for joining us!</p>'
        payload = {
            'from': from_email,
            'to': [email_address],
            'subject': subject,
            'text': text_body,
            'html': html_body,
        }
        if reply_to:
            payload['reply_to'] = reply_to
        last_error = None
        for attempt in range(1, MAX_ATTEMPTS + 1):
            try:
                response_data = _post_json(RESEND_ENDPOINT, payload, api_key)
                results.append({'email': email_address, 'status': 'sent', 'response': response_data})
                last_error = None
                break
            except urllib.error.HTTPError as exc:
                last_error = f'HTTP {exc.code}: {exc.reason}'
                if exc.code in RETRY_STATUS_CODES and attempt < MAX_ATTEMPTS:
                    time.sleep(2 ** (attempt - 1))
                    continue
                break
            except urllib.error.URLError as exc:
                last_error = f'network error: {exc.reason}'
                if attempt < MAX_ATTEMPTS:
                    time.sleep(2 ** (attempt - 1))
                    continue
                break
            except json.JSONDecodeError as exc:
                last_error = f'invalid JSON response: {exc}'
                break
        if last_error is not None:
            results.append({'email': email_address, 'status': 'failed', 'reason': last_error})
    return results

def main():
    users_json = os.environ.get('ONBOARDED_USERS_JSON', '')
    if not users_json:
        raise RuntimeError('ONBOARDED_USERS_JSON is required')
    users = json.loads(users_json)
    results = send_welcome_email(users)
    print(json.dumps(results, indent=2))

main()

import json
import os
import urllib.parse
import urllib.request

SLACK_API_BASE = 'https://slack.com/api'


def _decode_body(raw):
    """Convert a raw HTTP body into text without assuming its concrete type."""
    if raw is None:
        return ''
    if isinstance(raw, bytes):
        try:
            return raw.decode('utf-8', errors='replace')
        except Exception:
            return ''
    if isinstance(raw, str):
        return raw
    # Unknown object (e.g. a test double): treat as an empty body.
    return ''


def _parse_json_body(raw):
    """Parse a JSON body defensively and always return a plain dict."""
    if isinstance(raw, dict):
        return raw
    text = _decode_body(raw).strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except (ValueError, TypeError):
        return {}
    if isinstance(parsed, dict):
        return parsed
    return {}


def fetch_slack_messages():
    token = os.environ.get('SLACK_BOT_TOKEN')
    channel = os.environ.get('SLACK_CHANNEL_ID')
    if not token or not channel:
        raise RuntimeError('SLACK_BOT_TOKEN and SLACK_CHANNEL_ID must be set')
    records = []
    cursor = ''
    while True:
        params = {'channel': channel, 'limit': 100}
        if cursor:
            params['cursor'] = cursor
        query = urllib.parse.urlencode(params)
        url = f'{SLACK_API_BASE}/conversations.history?{query}'
        headers = {'Authorization': f'Bearer {token}'}
        request = urllib.request.Request(url, headers=headers, method='GET')
        with urllib.request.urlopen(request, timeout=30) as response:
            raw_body = response.read()
        payload = _parse_json_body(raw_body)
        if not payload:
            # Empty or non-JSON body: there is nothing left to ingest.
            break
        if not payload.get('ok', False):
            raise RuntimeError('Slack API error: ' + str(payload.get('error', 'unknown_error')))
        messages = payload.get('messages', [])
        if not isinstance(messages, list):
            messages = []
        for message in messages:
            if not isinstance(message, dict):
                continue
            text = message.get('text', '')
            if not text:
                continue
            record = {
                'source': 'slack',
                'channel_id': channel,
                'message_ts': message.get('ts', ''),
                'user': message.get('user', ''),
                'text': text,
            }
            records.append(record)
        metadata = payload.get('response_metadata', {})
        if not isinstance(metadata, dict):
            metadata = {}
        cursor = metadata.get('next_cursor', '')
        if not cursor:
            break
    return records


slack_records = fetch_slack_messages()

import json
import os
from collections import Counter

REQUIRED_FIELDS = (
    'source',
    'channel_id',
    'message_ts',
    'user',
    'text',
    'twitch_login',
    'is_live',
    'game_name',
    'viewer_count',
    'started_at',
)

def validate_records(records):
    validated = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError('Record ' + str(index) + ' is not a dictionary')
        missing = [field for field in REQUIRED_FIELDS if field not in record]
        if missing:
            raise ValueError('Record ' + str(index) + ' missing fields: ' + str(missing))
        viewer_count = record.get('viewer_count', 0)
        if not isinstance(viewer_count, int):
            raise ValueError('Record ' + str(index) + ' viewer_count is not an integer')
        validated.append(record)
    return validated

def aggregate_and_persist(records):
    validated = validate_records(records)
    live_records = [record for record in validated if record.get('is_live', False)]
    game_counter = Counter(
        record.get('game_name', '')
        for record in live_records
        if record.get('game_name', '')
    )
    summary = {
        'records_total': len(validated),
        'live_records': len(live_records),
        'total_viewers': sum(int(record.get('viewer_count', 0) or 0) for record in live_records),
        'unique_live_logins': sorted(
            {record.get('twitch_login', '') for record in live_records if record.get('twitch_login', '')}
        ),
        'top_games': [
            {'game_name': game, 'live_count': count}
            for game, count in game_counter.most_common(5)
        ],
    }
    output_path = os.environ.get('SUMMARY_OUTPUT_PATH', 'summary.json')
    with open(output_path, 'w', encoding='utf-8') as handle:
        json.dump(summary, handle, indent=2, sort_keys=True)
    return summary

final_summary = aggregate_and_persist(twitch_enriched)

