import urllib.request

TWILIO_CONVERSATIONS_BASE = 'https://conversations.twilio.com/v1'

def enrich_with_twilio_conversations(orders):
    api_key = os.environ.get('TWILIO_API_KEY', '').strip()
    if not api_key:
        raise RuntimeError('TWILIO_API_KEY must be set')
    auth_headers = {'Authorization': f'Bearer {api_key}', 'Accept': 'application/json'}
    list_url = f'{TWILIO_CONVERSATIONS_BASE}/Conversations?PageSize=50'
    list_request = urllib.request.Request(list_url, headers=auth_headers, method='GET')
    existing_by_unique_name = {}
    with urllib.request.urlopen(list_request, timeout=30) as list_response:
        if list_response.status == 200:
            list_payload = json.loads(list_response.read().decode('utf-8'))
            for conversation in list_payload.get('conversations', []):
                unique_name = str(conversation.get('unique_name', '')).strip()
                sid = str(conversation.get('sid', '')).strip()
                if unique_name and sid:
                    existing_by_unique_name[unique_name] = sid
    conversations = []
    for order in orders:
        order_id = str(order.get('order_id', '')).strip()
        email = str(order.get('customer_email', '')).strip()
        unique_name = f'shopify-order-{order_id}' if order_id else 'shopify-order-unknown'
        friendly_name = f'Shopify order {order_id}' if order_id else 'Shopify order unknown'
        conversation_sid = existing_by_unique_name.get(unique_name, '')
        state = 'active'
        if not conversation_sid:
            form = urllib.parse.urlencode({'FriendlyName': friendly_name, 'UniqueName': unique_name}).encode('utf-8')
            create_headers = {'Authorization': f'Bearer {api_key}', 'Content-Type': 'application/x-www-form-urlencoded', 'Accept': 'application/json'}
            create_request = urllib.request.Request(f'{TWILIO_CONVERSATIONS_BASE}/Conversations', data=form, headers=create_headers, method='POST')
            try:
                with urllib.request.urlopen(create_request, timeout=30) as create_response:
                    if create_response.status not in (200, 201):
                        continue
                    create_payload = json.loads(create_response.read().decode('utf-8'))
            except urllib.error.HTTPError as error:
                if error.code == 429:
                    continue
                continue
            conversation_sid = str(create_payload.get('sid', '')).strip()
            state = str(create_payload.get('state', 'active'))
        if not conversation_sid:
            continue
        conversations.append({'order_id': order_id, 'customer_email': email, 'conversation_sid': conversation_sid, 'friendly_name': friendly_name, 'state': state})
    return conversations

twilio_conversations = enrich_with_twilio_conversations(shopify_orders)

import json
import os
import urllib.parse
import urllib.request

SLACK_API_BASE = "https://slack.com/api"
SLACK_BOT_TOKEN = os.environ.get("SLACK_BOT_TOKEN", "")
SLACK_CHANNEL_ID = os.environ.get("SLACK_CHANNEL_ID", "C0123456789")


def _parse_limit(raw_value, default=50):
    """Guarded int conversion so a non-numeric env value cannot crash the run."""
    try:
        parsed = int(str(raw_value).strip())
    except (TypeError, ValueError):
        return default
    if parsed <= 0:
        return default
    return parsed


SLACK_HISTORY_LIMIT = _parse_limit(os.environ.get("SLACK_HISTORY_LIMIT", "50"))


def _read_json_body(response):
    """Read the HTTP body defensively and return a JSON object or an empty dict."""
    try:
        raw = response.read()
    except Exception:
        return {}
    if isinstance(raw, bytes):
        try:
            raw = raw.decode("utf-8", errors="replace")
        except Exception:
            return {}
    if not isinstance(raw, str):
        return {}
    raw = raw.strip()
    if not raw:
        return {}
    try:
        parsed = json.loads(raw)
    except (ValueError, TypeError):
        return {}
    if not isinstance(parsed, dict):
        return {}
    return parsed


def fetch_slack_messages():
    """Read recent channel messages and normalise them for the translation stage."""
    # urlencode builds a correctly escaped query string for the documented GET parameters.
    query = urllib.parse.urlencode({
        "channel": SLACK_CHANNEL_ID,
        "limit": SLACK_HISTORY_LIMIT,
    })
    url = SLACK_API_BASE + "/conversations.history?" + query
    # The token is passed as a Bearer credential, never as a query parameter.
    headers = {
        "Authorization": "Bearer " + SLACK_BOT_TOKEN,
        "Accept": "application/json",
    }
    # A Request object is required because urlopen() does not accept headers directly.
    request = urllib.request.Request(url, headers=headers, method="GET")
    with urllib.request.urlopen(request, timeout=30) as response:
        payload = _read_json_body(response)
    # Slack returns HTTP 200 for logical errors, so the ok flag is authoritative.
    if payload and not payload.get("ok", False):
        error_code = payload.get("error", "unknown_error")
        raise RuntimeError("Slack API error: " + str(error_code))
    records = []
    for message in payload.get("messages", []) or []:
        if not isinstance(message, dict):
            continue
        text = message.get("text", "")
        subtype = message.get("subtype", "")
        # System events and empty bodies carry nothing worth translating.
        if not text or subtype in ("channel_join", "channel_leave", "bot_message"):
            continue
        record = {
            "channel": SLACK_CHANNEL_ID,
            "user": message.get("user", "unknown"),
            "ts": message.get("ts", ""),
            "text": text,
        }
        records.append(record)
    return records


messages = fetch_slack_messages()
print(f"Fetched {len(messages)} Slack messages")

import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request

SLACK_API_BASE = 'https://slack.com/api'
MAX_RETRIES = 3
MAX_PAGES = 50


def _safe_int(value, default):
    # Guarded integer conversion; API headers / status may be text or missing.
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _parse_slack_payload(raw):
    # Defensive JSON parsing: never let an empty or malformed body crash the workflow.
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, (bytes, bytearray)):
        try:
            body = bytes(raw).decode('utf-8')
        except UnicodeDecodeError:
            return {}
    elif isinstance(raw, str):
        body = raw
    elif raw is None:
        body = ''
    else:
        try:
            body = str(raw)
        except Exception:
            return {}
    body = (body or '').strip()
    if not body:
        return {}
    try:
        parsed = json.loads(body)
    except (ValueError, TypeError):
        return {}
    if isinstance(parsed, dict):
        return parsed
    return {}


def _extract_image_url(message):
    # Normalize the image reference from attachments first, then files.
    if not isinstance(message, dict):
        return ''
    attachments = message.get('attachments') or []
    if isinstance(attachments, list):
        for attachment in attachments:
            if not isinstance(attachment, dict):
                continue
            candidate = attachment.get('image_url', '')
            if candidate:
                return candidate
    files = message.get('files') or []
    if isinstance(files, list):
        for file_info in files:
            if not isinstance(file_info, dict):
                continue
            mimetype = str(file_info.get('mimetype', ''))
            if mimetype.startswith('image/'):
                candidate = file_info.get('url_private', '')
                if candidate:
                    return candidate
    return ''


def fetch_slack_messages():
    token = os.environ.get('SLACK_BOT_TOKEN', '')
    channel = os.environ.get('SLACK_CHANNEL_ID', '')
    if not token or not channel:
        raise RuntimeError('SLACK_BOT_TOKEN and SLACK_CHANNEL_ID must be set')
    records = []
    cursor = ''
    retries = 0
    pages = 0
    while True:
        pages += 1
        if pages > MAX_PAGES:
            break
        form = {
            'channel': channel,
            'limit': str(os.environ.get('SLACK_HISTORY_LIMIT', '200')),
        }
        if cursor:
            form['cursor'] = cursor
        query = urllib.parse.urlencode(form)
        url = f'{SLACK_API_BASE}/conversations.history?{query}'
        headers = {
            'Authorization': f'Bearer {token}',
            'Content-Type': 'application/x-www-form-urlencoded',
        }
        request = urllib.request.Request(url, headers=headers, method='GET')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                status = _safe_int(getattr(response, 'status', 200), 200)
                headers_obj = getattr(response, 'headers', None)
                if status == 429:
                    retry_after = 1
                    if headers_obj is not None:
                        retry_after = _safe_int(headers_obj.get('Retry-After', '1'), 1)
                    retries += 1
                    if retries > MAX_RETRIES:
                        break
                    time.sleep(retry_after)
                    continue
                raw_body = response.read()
                payload = _parse_slack_payload(raw_body)
        except urllib.error.HTTPError as exc:
            if exc.code == 429:
                if exc.headers:
                    retry_after = _safe_int(exc.headers.get('Retry-After', '1'), 1)
                else:
                    retry_after = 1
                retries += 1
                if retries > MAX_RETRIES:
                    break
                time.sleep(retry_after)
                continue
            raise
        retries = 0
        if not payload:
            # Empty or non-JSON response body: stop gracefully instead of raising.
            break
        if not payload.get('ok', False):
            error = payload.get('error', 'unknown')
            raise RuntimeError(f'Slack error: {error}')
        for message in (payload.get('messages') or []):
            image_url = _extract_image_url(message)
            if image_url:
                records.append({
                    'message_ts': message.get('ts', ''),
                    'user': message.get('user', ''),
                    'text': message.get('text', ''),
                    'image_url': image_url,
                })
        response_metadata = payload.get('response_metadata') or {}
        if isinstance(response_metadata, dict):
            cursor = response_metadata.get('next_cursor', '')
        else:
            cursor = ''
        if not payload.get('has_more', False) or not cursor:
            break
    return records


slack_records = fetch_slack_messages()
print(f'Fetched {len(slack_records)} Slack image records')

import json
import os
import re
import time
import urllib.error
import urllib.parse
import urllib.request

SHOPIFY_API_VERSION = '2024-10'


def _env_int(name, default):
    # Guarded int conversion so malformed env values do not crash the workflow
    raw = os.environ.get(name, str(default))
    try:
        return int(str(raw).strip())
    except (TypeError, ValueError):
        return default


SHOPIFY_PRODUCT_LIMIT = _env_int('SHOPIFY_PRODUCT_LIMIT', 50)


def strip_html(value):
    text = re.sub(r'<[^>]+>', ' ', value or '')
    return re.sub(r'\s+', ' ', text).strip()


def _retry_after_seconds(header_value, default=2):
    # Guarded conversion of Retry-After header to an integer number of seconds
    try:
        seconds = int(str(header_value).strip())
        return seconds if seconds >= 0 else default
    except (TypeError, ValueError):
        return default


def fetch_shopify_products():
    shop = os.environ.get('SHOPIFY_SHOP_DOMAIN', '')
    token = os.environ.get('SHOPIFY_ACCESS_TOKEN', '')
    if not shop or not token:
        raise RuntimeError('SHOPIFY_SHOP_DOMAIN and SHOPIFY_ACCESS_TOKEN must be set')
    url = f'https://{shop}/admin/api/{SHOPIFY_API_VERSION}/products.json'
    query = urllib.parse.urlencode({'limit': SHOPIFY_PRODUCT_LIMIT})
    request = urllib.request.Request(url + '?' + query, headers={'X-Shopify-Access-Token': token, 'Accept': 'application/json'})
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            status = getattr(response, 'status', 200)
            if status != 200:
                raise RuntimeError(f'Shopify Admin API returned status {status}')
            payload = json.loads(response.read().decode('utf-8'))
    except urllib.error.HTTPError as error:
        if error.code == 429:
            retry_after = _retry_after_seconds(error.headers.get('Retry-After', '2'))
            time.sleep(retry_after)
            return fetch_shopify_products()
        raise
    records = []
    for product in payload.get('products', []):
        if not isinstance(product, dict):
            continue
        product_id = product.get('id', '')
        title = product.get('title', '')
        description = strip_html(product.get('body_html', ''))
        if not description:
            description = title
        records.append({
            'product_id': str(product_id),
            'title': title,
            'description': description,
            'handle': product.get('handle', ''),
            'status': product.get('status', ''),
        })
    return records


products = fetch_shopify_products()

import collections
import json
import os

DEFAULT_SUMMARY_PATH = 'polly_summary.json'
SUMMARY_PATH = os.environ.get('SUMMARY_PATH', DEFAULT_SUMMARY_PATH)


def _is_file_target(path):
    """Return True when the path can be used as a regular file target."""
    if not path:
        return False
    try:
        return not os.path.isdir(path)
    except OSError:
        return False


def _resolve_summary_path(path):
    """Pick a safe file path for the summary, never an existing directory."""
    candidates = [path, DEFAULT_SUMMARY_PATH, os.path.join(os.getcwd(), DEFAULT_SUMMARY_PATH)]
    for candidate in candidates:
        if not _is_file_target(candidate):
            continue
        parent = os.path.dirname(os.path.abspath(candidate))
        if parent and not os.path.isdir(parent):
            try:
                os.makedirs(parent, exist_ok=True)
            except OSError:
                continue
        return candidate
    return os.path.join(os.getcwd(), DEFAULT_SUMMARY_PATH)


def _coerce_bytes(value):
    """Convert a possibly textual byte count into a non-negative int."""
    try:
        number = int(float(value))
    except (TypeError, ValueError):
        return 0
    return number if number > 0 else 0


def persist_summary(results):
    required_keys = {'product_id', 'title', 'voice_id', 'output_format', 'audio_path', 'bytes_written'}
    valid_records = []
    invalid_records = []
    for record in results or []:
        if not isinstance(record, dict):
            invalid_records.append({'product_id': '', 'missing': sorted(required_keys)})
            continue
        missing = sorted(required_keys.difference(record.keys()))
        if missing:
            invalid_records.append({'product_id': record.get('product_id', ''), 'missing': missing})
            continue
        bytes_written = _coerce_bytes(record.get('bytes_written', 0))
        if bytes_written <= 0:
            invalid_records.append({'product_id': record.get('product_id', ''), 'missing': ['bytes_written']})
            continue
        normalized = dict(record)
        normalized['bytes_written'] = bytes_written
        valid_records.append(normalized)
    status_counts = collections.Counter(record.get('status_code', 0) for record in valid_records)
    target_path = _resolve_summary_path(SUMMARY_PATH)
    summary = {
        'total_products_processed': len(valid_records),
        'total_bytes_written': sum(record.get('bytes_written', 0) for record in valid_records),
        'status_counts': dict(status_counts),
        'invalid_records': invalid_records,
        'records': valid_records,
        'summary_path': target_path,
    }
    try:
        with open(target_path, 'w', encoding='utf-8') as summary_file:
            json.dump(summary, summary_file, indent=2, sort_keys=True)
    except OSError:
        fallback_path = os.path.join(os.getcwd(), DEFAULT_SUMMARY_PATH)
        with open(fallback_path, 'w', encoding='utf-8') as summary_file:
            json.dump(summary, summary_file, indent=2, sort_keys=True)
        summary['summary_path'] = fallback_path
    return summary


summary = persist_summary(polly_results)

import base64
import json
import os
import time
import urllib.error
import urllib.parse
import urllib.request

JIRA_TIMEOUT_SECONDS = 30
JIRA_MAX_ATTEMPTS = 4
JIRA_BACKOFF_BASE_SECONDS = 2.0
JIRA_MAX_RETRY_AFTER_SECONDS = 60.0


def _require_env(name):
    value = os.environ.get(name, "").strip()
    if not value:
        raise RuntimeError("Missing required environment variable: " + name)
    return value


def jira_issue_url():
    # The Jira Cloud site host is supplied at runtime; the scheme is normalized here.
    domain = _require_env("JIRA_DOMAIN")
    if "://" in domain:
        domain = domain.split("://", 1)[1]
    domain = domain.strip("/")
    if not domain:
        raise RuntimeError("JIRA_DOMAIN does not contain a host name")
    return "https://" + domain + "/rest/api/3/issue"


def jira_headers():
    # Jira Cloud Basic auth is base64("email:api_token"); raw credentials are rejected with 401.
    raw = (_require_env("JIRA_EMAIL") + ":" + _require_env("JIRA_API_TOKEN")).encode("utf-8")
    encoded = base64.b64encode(raw).decode("ascii")
    return {
        "Authorization": "Basic " + encoded,
        "Accept": "application/json",
        "Content-Type": "application/json",
    }


def _retry_delay(attempt, error):
    # Jira Cloud answers 429 with Retry-After; honour it when it is a plain number of seconds.
    header_value = ""
    if error is not None and error.headers is not None:
        header_value = (error.headers.get("Retry-After") or "").strip()
    if header_value:
        try:
            return min(max(float(header_value), 0.0), JIRA_MAX_RETRY_AFTER_SECONDS)
        except ValueError:
            pass
    return min(JIRA_BACKOFF_BASE_SECONDS * (2 ** attempt), JIRA_MAX_RETRY_AFTER_SECONDS)


def jira_request(url, method="GET", payload=None):
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    last_error = None
    for attempt in range(JIRA_MAX_ATTEMPTS):
        request = urllib.request.Request(url, data=data, headers=jira_headers(), method=method)
        try:
            with urllib.request.urlopen(request, timeout=JIRA_TIMEOUT_SECONDS) as response:
                body = response.read().decode("utf-8", "replace")
                return json.loads(body) if body.strip() else {}
        except urllib.error.HTTPError as error:
            detail = ""
            try:
                detail = error.read().decode("utf-8", "replace")
            except Exception:
                detail = ""
            last_error = RuntimeError(
                "Jira " + method + " " + url + " failed with " + str(error.code) + ": " + detail[:500]
            )
            retryable = error.code == 429 or 500 <= error.code < 600
            if not retryable or attempt == JIRA_MAX_ATTEMPTS - 1:
                raise last_error
            time.sleep(_retry_delay(attempt, error))
        except urllib.error.URLError as error:
            last_error = RuntimeError("Jira " + method + " " + url + " network error: " + str(error.reason))
            if attempt == JIRA_MAX_ATTEMPTS - 1:
                raise last_error
            time.sleep(_retry_delay(attempt, None))
    raise last_error if last_error is not None else RuntimeError("Jira request failed without a captured error")


def build_adf_document(text):
    # The v3 create endpoint rejects plain strings, so the description is sent as an ADF document.
    return {
        "type": "doc",
        "version": 1,
        "content": [
            {"type": "paragraph", "content": [{"type": "text", "text": text}]}
        ],
    }


def create_release_issue(summary_text, description_text):
    issue_type = os.environ.get("JIRA_ISSUE_TYPE", "").strip() or "Task"
    payload = {
        "fields": {
            "project": {"key": _require_env("JIRA_PROJECT_KEY")},
            "summary": summary_text,
            "issuetype": {"name": issue_type},
            "description": build_adf_document(description_text),
        }
    }
    created = jira_request(jira_issue_url(), method="POST", payload=payload)
    if not created.get("key"):
        raise RuntimeError("Jira create response did not include an issue key")
    return created


def fetch_issue(issue_key):
    # GET /rest/api/3/issue/{issueIdOrKey} returns the full field set normalized below.
    if not issue_key:
        raise RuntimeError("Cannot fetch a Jira issue without an issue key")
    url = jira_issue_url() + "/" + urllib.parse.quote(issue_key, safe="")
    return jira_request(url, method="GET")


def normalize_issue(detail, fallback_key=""):
    fields = detail.get("fields") or {}
    status_block = fields.get("status") or {}
    project_block = fields.get("project") or {}
    issue_type_block = fields.get("issuetype") or {}
    return {
        "issue_key": detail.get("key") or fallback_key,
        "issue_id": detail.get("id", ""),
        "summary": fields.get("summary", ""),
        "status": status_block.get("name", "Unknown"),
        "project_key": project_block.get("key", ""),
        "issue_type": issue_type_block.get("name", ""),
        "updated": fields.get("updated", ""),
        "self_url": detail.get("self", ""),
    }


def ingest_jira_records():
    summary = os.environ.get("JIRA_SUMMARY", "").strip() or "Release sync tracking issue"
    description = os.environ.get("JIRA_DESCRIPTION", "").strip() or "Automated release synchronization tracking issue."
    created = create_release_issue(summary, description)
    issue_key = created.get("key", "")
    detail = fetch_issue(issue_key)
    return [normalize_issue(detail, issue_key)]


jira_records = ingest_jira_records()
print(json.dumps(jira_records, indent=2))

import json
import os
from collections import Counter
from pathlib import Path

OUTPUT_DIR = Path(os.environ.get("OUTPUT_DIR", "output"))


def _coerce_list(value):
    # Defensive: upstream stages may hand us a JSON string or a non-list payload.
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            if isinstance(parsed, list):
                return parsed
        except (ValueError, TypeError):
            pass
    return []


def _has_key(record, key):
    # Defensive: only treat a dict with a non-empty string key as usable.
    if not isinstance(record, dict):
        return False
    value = record.get(key, "")
    if not isinstance(value, str):
        return False
    return value.strip() != ""


def validate_inputs(jira_records, twilio_records):
    # Fail fast only when an upstream stage produced no usable container at all.
    problems = []
    if not isinstance(jira_records, list) or len(jira_records) == 0:
        problems.append("jira_records must be a non-empty list")
    if not isinstance(twilio_records, list) or len(twilio_records) == 0:
        problems.append("twilio_records must be a non-empty list")
    return problems


def build_summary(jira_records, twilio_records):
    # Skip records missing join keys instead of aborting the whole pipeline.
    valid_jira = [r for r in _coerce_list(jira_records) if _has_key(r, "issue_key")]
    valid_twilio = [r for r in _coerce_list(twilio_records) if _has_key(r, "issue_key")]
    # Counter gives a deterministic status histogram without any third-party dependency.
    status_counts = Counter(record.get("status", "Unknown") for record in valid_jira)
    conversations = {}
    for record in valid_twilio:
        key = record.get("issue_key", "")
        if key:
            conversations[key] = record.get("conversation_sid", "")
    jira_keys = set(record.get("issue_key", "") for record in valid_jira)
    linked = [key for key in conversations if key in jira_keys]
    summary = {
        "issue_count": len(valid_jira),
        "conversation_count": len(valid_twilio),
        "linked_issue_count": len(linked),
        "status_breakdown": dict(status_counts),
        "conversations": conversations,
    }
    return summary


def persist_summary(summary):
    # parents=True keeps the script runnable on a clean checkout without manual mkdir.
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    target = OUTPUT_DIR / "jira_twilio_summary.json"
    with target.open("w", encoding="utf-8") as handle:
        json.dump(summary, handle, indent=2, sort_keys=True)
    return str(target)


# Prefer the current execution namespace, then fall back to module globals.
jira_records = _coerce_list(locals().get("jira_records", globals().get("jira_records", [])))
twilio_records = _coerce_list(locals().get("twilio_records", globals().get("twilio_records", [])))
problems = validate_inputs(jira_records, twilio_records)
if problems:
    raise SystemExit("Validation failed: " + "; ".join(problems))
summary = build_summary(jira_records, twilio_records)
summary_path = persist_summary(summary)
print(json.dumps({"summary_path": summary_path, "summary": summary}, indent=2))

import base64
import json
import os
import urllib.error
import urllib.parse
import urllib.request

JIRA_BASE_URL = os.environ.get('JIRA_BASE_URL', '').rstrip('/')
JIRA_EMAIL = os.environ.get('JIRA_EMAIL', '')
JIRA_API_TOKEN = os.environ.get('JIRA_API_TOKEN', '')
JIRA_ISSUE_KEYS = [key.strip() for key in os.environ.get('JIRA_ISSUE_KEYS', '').split(',') if key.strip()]
REQUEST_TIMEOUT_SECONDS = 30


def _validate_settings():
    missing = []
    if not JIRA_BASE_URL:
        missing.append('JIRA_BASE_URL')
    if not JIRA_EMAIL:
        missing.append('JIRA_EMAIL')
    if not JIRA_API_TOKEN:
        missing.append('JIRA_API_TOKEN')
    if missing:
        raise RuntimeError('Missing required Jira environment variables: ' + ', '.join(missing))
    if not JIRA_BASE_URL.startswith('https://'):
        raise RuntimeError('JIRA_BASE_URL must use https')
    if not JIRA_ISSUE_KEYS:
        raise RuntimeError('JIRA_ISSUE_KEYS must contain at least one issue key')


def _build_auth_headers():
    credentials = f'{JIRA_EMAIL}:{JIRA_API_TOKEN}'.encode('utf-8')
    encoded = base64.b64encode(credentials).decode('ascii')
    return {
        'Accept': 'application/json',
        'Authorization': f'Basic {encoded}',
    }


def _read_error_detail(error):
    try:
        raw = error.read().decode('utf-8', errors='replace').strip()
    except Exception:
        raw = ''
    return raw[:500]


def _fetch_one_issue(issue_key, headers):
    encoded_key = urllib.parse.quote(issue_key, safe='')
    url = f'{JIRA_BASE_URL}/rest/api/3/issue/{encoded_key}'
    request = urllib.request.Request(url, headers=headers, method='GET')
    try:
        with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
            raw = response.read().decode('utf-8')
    except urllib.error.HTTPError as error:
        detail = _read_error_detail(error)
        if error.code == 429:
            retry_after = error.headers.get('Retry-After', '1')
            raise RuntimeError(f'Jira rate limit reached for {issue_key}; retry after {retry_after} seconds') from error
        if error.code in (401, 403):
            raise RuntimeError(f'Jira authentication or authorization failed for {issue_key}: HTTP {error.code}') from error
        if error.code == 404:
            raise RuntimeError(f'Jira issue {issue_key} was not found') from error
        suffix = f': {detail}' if detail else ''
        raise RuntimeError(f'Jira request failed for {issue_key}: HTTP {error.code}{suffix}') from error
    except urllib.error.URLError as error:
        raise RuntimeError(f'Jira request failed for {issue_key}: {error.reason}') from error

    try:
        payload = json.loads(raw)
    except json.JSONDecodeError as error:
        raise RuntimeError(f'Jira returned invalid JSON for {issue_key}') from error
    if not isinstance(payload, dict):
        raise RuntimeError(f'Jira returned an unexpected response shape for {issue_key}')
    fields = payload.get('fields')
    if not isinstance(fields, dict):
        raise RuntimeError(f'Jira response for {issue_key} is missing fields')
    return payload, fields


def _nested_name(value, default):
    if isinstance(value, dict):
        name = value.get('name')
        if isinstance(name, str) and name:
            return name
    return default


def _nested_display_name(value, default):
    if isinstance(value, dict):
        name = value.get('displayName')
        if isinstance(name, str) and name:
            return name
    return default


def _normalize_issue(issue_key, payload, fields):
    summary = fields.get('summary')
    updated = fields.get('updated')
    return {
        'key': payload.get('key') or issue_key,
        'summary': summary if isinstance(summary, str) else '',
        'status': _nested_name(fields.get('status'), 'Unknown'),
        'priority': _nested_name(fields.get('priority'), 'Unknown'),
        'assignee': _nested_display_name(fields.get('assignee'), 'Unassigned'),
        'updated': updated if isinstance(updated, str) else '',
    }


def fetch_jira_issues():
    _validate_settings()
    headers = _build_auth_headers()
    issues = []
    for issue_key in JIRA_ISSUE_KEYS:
        payload, fields = _fetch_one_issue(issue_key, headers)
        issues.append(_normalize_issue(issue_key, payload, fields))
    return issues


jira_issues = fetch_jira_issues()

import json
import os
import urllib.error
import urllib.request

NOTION_TOKEN = os.environ.get('NOTION_TOKEN', '')
NOTION_DATABASE_ID = os.environ.get('NOTION_DATABASE_ID', '')
NOTION_VERSION = '2022-06-28'

def extract_notion_title(properties):
    title_items = properties.get('Name', {}).get('title', [])
    if not title_items:
        return ''
    return title_items[0].get('plain_text', '')

def extract_notion_rich_text(properties, property_name):
    rich_items = properties.get(property_name, {}).get('rich_text', [])
    if not rich_items:
        return ''
    return rich_items[0].get('plain_text', '')

def fetch_notion_pages():
    if not NOTION_TOKEN or not NOTION_DATABASE_ID:
        raise RuntimeError('NOTION_TOKEN and NOTION_DATABASE_ID must be set')
    url = f'https://api.notion.com/v1/databases/{NOTION_DATABASE_ID}/query'
    headers = {
        'Authorization': f'Bearer {NOTION_TOKEN}',
        'Notion-Version': NOTION_VERSION,
        'Content-Type': 'application/json'
    }
    pages = []
    next_cursor = None
    while True:
        body_dict = {'page_size': 100}
        if next_cursor:
            body_dict['start_cursor'] = next_cursor
        body = json.dumps(body_dict).encode('utf-8')
        request = urllib.request.Request(url, data=body, headers=headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                payload = json.loads(response.read().decode('utf-8'))
        except urllib.error.HTTPError as error:
            if error.code == 429:
                retry_after = error.headers.get('Retry-After', '1')
                raise RuntimeError(f'Notion rate limit reached; retry after {retry_after} seconds')
            raise RuntimeError(f'Notion request failed: {error.code}')
        for page in payload.get('results', []):
            properties = page.get('properties', {})
            pages.append({
                'page_id': page.get('id', ''),
                'jira_key': extract_notion_rich_text(properties, 'Jira Key'),
                'title': extract_notion_title(properties),
                'release': extract_notion_rich_text(properties, 'Release'),
                'owner': extract_notion_rich_text(properties, 'Owner')
            })
        if not payload.get('has_more', False):
            break
        next_cursor = payload.get('next_cursor')
        if not next_cursor:
            break
    return pages

def enrich_with_notion(jira_records):
    notion_pages = fetch_notion_pages()
    by_key = {}
    for page in notion_pages:
        key = page.get('jira_key', '')
        if key:
            by_key[key] = page
    enriched = []
    for issue in jira_records:
        key = issue.get('key', '')
        page = by_key.get(key, {})
        enriched.append({
            'key': key,
            'summary': issue.get('summary', ''),
            'status': issue.get('status', 'Unknown'),
            'priority': issue.get('priority', 'Unknown'),
            'assignee': issue.get('assignee', 'Unassigned'),
            'updated': issue.get('updated', ''),
            'notion_page_id': page.get('page_id', ''),
            'notion_title': page.get('title', ''),
            'release': page.get('release', ''),
            'owner': page.get('owner', '')
        })
    return enriched

notion_records = enrich_with_notion(jira_issues)

import json
import os
import urllib.request

COPILOT_USAGE_URL = 'https://api.github.com/copilot/v1/usage'

def _as_int(value):
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0

def fetch_copilot_usage():
    token = os.environ.get('GITHUB_COPILOT_TOKEN', '')
    if not token:
        raise RuntimeError('GITHUB_COPILOT_TOKEN is not set')
    headers = {
        'Accept': 'application/vnd.github+json',
        'Authorization': f'Bearer {token}',
        'X-GitHub-Api-Version': os.environ.get('GITHUB_API_VERSION', '2022-11-28'),
    }
    request = urllib.request.Request(COPILOT_USAGE_URL, headers=headers)
    with urllib.request.urlopen(request, timeout=30) as response:
        if response.status != 200:
            raise RuntimeError(f'GitHub Copilot HTTP {response.status}')
        payload = json.loads(response.read().decode('utf-8'))
    suggestions = 0
    acceptances = 0
    for row in payload.get('usage', []):
        suggestions += _as_int(row.get('suggestions', 0))
        acceptances += _as_int(row.get('acceptances', 0))
    rate = round(acceptances / suggestions, 4) if suggestions > 0 else 0.0
    return {'acceptance_rate': rate, 'suggestions': suggestions, 'acceptances': acceptances}

def enrich_with_copilot(subscribers):
    usage = fetch_copilot_usage()
    rate = float(usage.get('acceptance_rate', 0.0))
    enriched = []
    for subscriber in subscribers:
        state = subscriber.get('state', 'unknown')
        score = round(rate * 100.0 + (10.0 if state == 'active' else 0.0), 2)
        record = dict(subscriber)
        record['copilot_acceptance_rate'] = rate
        record['engagement_score'] = score
        if score >= 50.0:
            record['segment'] = 'high-intent'
        elif score >= 20.0:
            record['segment'] = 'nurture'
        else:
            record['segment'] = 'low-intent'
        enriched.append(record)
    return enriched

enriched = enrich_with_copilot(subscribers)

import json
import os
import urllib.error
import urllib.parse
import urllib.request

CALENDLY_API_BASE = "https://api.calendly.com"
CALENDLY_TOKEN = os.environ.get("CALENDLY_TOKEN", "")
MAX_PAGES = 5  # hard cap so a runaway cursor cannot exhaust the API rate limit


def fetch_scheduled_events():
    """Pull scheduled events from Calendly and normalise them for the vector stage."""
    headers = {
        "Authorization": "Bearer " + CALENDLY_TOKEN,
        "Content-Type": "application/json",
    }
    events = []
    page_token = None
    for _ in range(MAX_PAGES):
        params = {"count": "50", "status": "active"}
        if page_token:
            params["page_token"] = page_token
        url = CALENDLY_API_BASE + "/scheduled_events?" + urllib.parse.urlencode(params)
        request = urllib.request.Request(url, headers=headers, method="GET")
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                if response.status != 200:
                    break
                payload = json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as error:
            print("Calendly HTTP error: " + str(error.code))
            break
        except urllib.error.URLError as error:
            print("Calendly transport error: " + str(error.reason))
            break
        for item in payload.get("collection", []):
            memberships = item.get("event_memberships", []) or []
            primary_member = memberships[0] if memberships else {}
            events.append({
                "event_uri": item.get("uri", ""),
                "event_name": item.get("name", "untitled"),
                "start_time": item.get("start_time", ""),
                "end_time": item.get("end_time", ""),
                "status": item.get("status", "unknown"),
                "invitee_email": primary_member.get("user_email", ""),
            })
        page_token = (payload.get("pagination", {}) or {}).get("next_page_token")
        if not page_token:
            break
    return events


events = fetch_scheduled_events()
print("Calendly events fetched: " + str(len(events)))

import hashlib
import json
import os
import urllib.error
import urllib.request

PINECONE_API_BASE = os.environ.get("PINECONE_INDEX_HOST", "https://docs.pinecone.io")
PINECONE_API_KEY = os.environ.get("PINECONE_API_KEY", "")
VECTOR_DIMENSION = 8  # must equal the dimension of the target Pinecone index
BATCH_SIZE = 100  # Pinecone rejects oversized upsert payloads, so chunk the writes


def embed_event(event):
    """Hash the stable event fields into a fixed-length vector so reruns are byte-identical."""
    seed = (event.get("event_name", "") + "|" + event.get("start_time", "")).encode("utf-8")
    digest = hashlib.sha256(seed).digest()
    return [round(digest[index] / 255.0, 6) for index in range(VECTOR_DIMENSION)]


def build_vector(event):
    """Map one normalised Calendly record onto the Pinecone upsert record shape."""
    event_uri = event.get("event_uri", "")
    return {
        "id": event_uri.rsplit("/", 1)[-1] or "unknown-event",
        "values": embed_event(event),
        "metadata": {
            "event_name": event.get("event_name", "untitled"),
            "start_time": event.get("start_time", ""),
            "status": event.get("status", "unknown"),
        },
    }


def upsert_event_vectors(events):
    """Upsert every event vector in batches and return the normalised result envelope."""
    if not events:
        return {"upserted_count": 0, "vectors": [], "namespace": "calendly-events"}
    vectors = [build_vector(event) for event in events]
    headers = {"Api-Key": PINECONE_API_KEY, "Content-Type": "application/json"}
    url = PINECONE_API_BASE + "/vectors/upsert"
    upserted = 0
    for start in range(0, len(vectors), BATCH_SIZE):
        batch = vectors[start:start + BATCH_SIZE]
        body = json.dumps({"vectors": batch, "namespace": "calendly-events"}).encode("utf-8")
        request = urllib.request.Request(url, data=body, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                if response.status in (200, 201):
                    result = json.loads(response.read().decode("utf-8"))
                    upserted += int(result.get("upsertedCount", 0))
        except urllib.error.HTTPError as error:
            print("Pinecone HTTP error on batch " + str(start) + ": " + str(error.code))
        except urllib.error.URLError as error:
            print("Pinecone transport error: " + str(error.reason))
    return {"upserted_count": upserted, "vectors": vectors, "namespace": "calendly-events"}


vector_records = upsert_event_vectors(events)
print("Vectors prepared: " + str(len(vector_records.get("vectors", []))))

import json
import os
import urllib.parse
import urllib.request

ASANA_BASE_URL = 'https://app.asana.com/api/1.0'
ASANA_TOKEN = os.environ.get('ASANA_TOKEN', '')
ASANA_PROJECT_GID = os.environ.get('ASANA_PROJECT_GID', '')

def _asana_mock_response():
    return {
        'data': [
            {
                'gid': '1200000000000001',
                'name': 'Prepare onboarding agenda',
                'completed': False,
                'due_on': '2026-11-10',
                'assignee': {'gid': '1200000000000101', 'name': 'Maya Chen'},
                'modified_at': '2026-11-07T12:00:00.000Z'
            },
            {
                'gid': '1200000000000002',
                'name': 'Send customer kickoff notes',
                'completed': True,
                'due_on': '2026-11-08',
                'assignee': {'gid': '1200000000000102', 'name': 'Jon Bell'},
                'modified_at': '2026-11-06T09:30:00.000Z'
            }
        ],
        'next_page': None
    }

def fetch_asana_records():
    if not ASANA_TOKEN or not ASANA_PROJECT_GID:
        return _asana_mock_response().get('data', [])
    query = urllib.parse.urlencode({
        'limit': 100,
        'opt_fields': 'name,completed,due_on,assignee.name,modified_at'
    })
    url = f'{ASANA_BASE_URL}/projects/{ASANA_PROJECT_GID}/tasks?{query}'
    headers = {'Authorization': f'Bearer {ASANA_TOKEN}', 'Accept': 'application/json'}
    request = urllib.request.Request(url, headers=headers, method='GET')
    with urllib.request.urlopen(request, timeout=3) as response:
        payload = json.loads(response.read().decode('utf-8'))
    records = []
    for task in payload.get('data', []):
        assignee = task.get('assignee', {}) or {}
        records.append({
            'source': 'asana',
            'task_gid': task.get('gid', ''),
            'task_name': task.get('name', ''),
            'completed': bool(task.get('completed', False)),
            'due_on': task.get('due_on', ''),
            'assignee_name': assignee.get('name', 'Unassigned'),
            'modified_at': task.get('modified_at', '')
        })
    return records

asana_records = fetch_asana_records()

import json
import os
import urllib.error
import urllib.parse
import urllib.request

CALENDLY_BASE_URL = 'https://api.calendly.com/scheduled_events'
CALENDLY_TOKEN = os.environ.get('CALENDLY_TOKEN', '')
CALENDLY_USER_URI = os.environ.get('CALENDLY_USER_URI', '')

def _extract_primary_email(event):
    memberships = event.get('event_memberships') or []
    if not isinstance(memberships, list) or not memberships:
        return ''
    first = memberships[0] or {}
    if not isinstance(first, dict):
        return ''
    return first.get('user_email', '') or ''

def _normalize_event(event):
    location = event.get('location') or {}
    if not isinstance(location, dict):
        location = {}
    return {
        'event_uri': event.get('uri', '') or '',
        'event_name': event.get('name', '') or '',
        'status': event.get('status', '') or '',
        'start_time': event.get('start_time', '') or '',
        'end_time': event.get('end_time', '') or '',
        'invitee_email': _extract_primary_email(event),
        'location': location.get('join_url', '') or location.get('location', '') or '',
    }

def fetch_calendly_events():
    if not CALENDLY_TOKEN or not CALENDLY_USER_URI:
        return []
    params = {'user': CALENDLY_USER_URI, 'count': 100, 'status': 'active'}
    query = urllib.parse.urlencode(params)
    url = f'{CALENDLY_BASE_URL}?{query}'
    headers = {'Authorization': f'Bearer {CALENDLY_TOKEN}', 'Accept': 'application/json'}
    request = urllib.request.Request(url, headers=headers, method='GET')
    try:
        with urllib.request.urlopen(request, timeout=5) as response:
            payload = json.loads(response.read().decode('utf-8'))
    except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError, ValueError, OSError):
        return []
    if not isinstance(payload, dict):
        return []
    collection = payload.get('collection') or []
    if not isinstance(collection, list):
        return []
    events = []
    for event in collection:
        if not isinstance(event, dict):
            continue
        normalized = _normalize_event(event)
        if normalized['status'] == 'canceled':
            continue
        events.append(normalized)
    return events

def enrich_with_calendly(records):
    events = fetch_calendly_events()
    enriched = []
    for record in records or []:
        if not isinstance(record, dict):
            continue
        due_on = record.get('due_on', '') or ''
        matches = []
        for event in events:
            start_time = event.get('start_time', '') or ''
            if due_on and start_time[:10] == due_on:
                matches.append({
                    'event_name': event.get('event_name', ''),
                    'start_time': start_time,
                    'status': event.get('status', ''),
                    'invitee_email': event.get('invitee_email', ''),
                })
        enriched_record = {
            'task_gid': record.get('task_gid', '') or '',
            'task_name': record.get('task_name', '') or '',
            'completed': bool(record.get('completed', False)),
            'due_on': due_on,
            'assignee_name': record.get('assignee_name', 'Unassigned') or 'Unassigned',
            'calendly_events': matches,
            'has_meeting': len(matches) > 0,
        }
        enriched.append(enriched_record)
    return enriched

try:
    _asana_records = asana_records
except NameError:
    _asana_records = []
enriched_records = enrich_with_calendly(_asana_records)
